  cache = {};  // clear tab cache on filter change
  if (activeTab === 'overall')     loadOverall();
  if (activeTab === 'action')      loadActionCenter();
  if (activeTab === 'menu')      { loadMenuSubtab(); renderMenuSalesNarrative(); }
