// TAB 4 — ANALYSIS REPORT
// ════════════════════════════════════════════════════════════════
let _rptLastMonth = '';
// §8 Cost Contribution — latest month for a branch (or all), with real MoM Δ vs prior month
async function renderReportCost(branch) {
  branch = branch || '';
  const month = _rptLastMonth;
  const body = document.getElementById('rptCostContribBody');
  const foot = document.getElementById('rptCostContribFoot');
  const note = document.getElementById('rptCostContribNote');
  const kpis = document.getElementById('rptCostContribKpis');
  if (!body) return;
  if (!month) { body.innerHTML = '<tr><td colspan="9" class="py-4 text-center text-slate-400 text-xs">ไม่มีเดือนข้อมูล</td></tr>'; if(foot)foot.innerHTML=''; return; }
  const [y,m] = month.split('-').map(Number);
  const prevM = m === 1 ? `${y-1}-12` : `${y}-${String(m-1).padStart(2,'0')}`;
  if (note) note.textContent = `เดือน ${fmtMonth(month)} · ${branch||'ทุกสาขา'} · MoM Δ เทียบ ${fmtMonth(prevM)} · % = สัดส่วนต้นทุนรวม · สะสม% = ขนาดรวม Top 60`;
  body.innerHTML = '<tr><td colspan="9" class="py-6 text-center text-slate-400 text-xs">กำลังโหลด…</td></tr>';
  if (foot) foot.innerHTML = '';
  const qpf = mm => { const p = new URLSearchParams(); if (branch) p.set('branch', branch); p.set('month_from', mm); p.set('month_to', mm); return p.toString(); };
  let cur, prev;
  try {
    [cur, prev] = await Promise.all([
      fetch(`${API}/api/cost/analysis?${qpf(month)}`).then(r => r.json()),
      fetch(`${API}/api/cost/analysis?${qpf(prevM)}`).then(r => r.json()).catch(() => ({ items: [] })),
    ]);
  } catch (e) { body.innerHTML = '<tr><td colspan="9" class="py-6 text-center text-red-500 text-xs">โหลดไม่ได้</td></tr>'; return; }
  const costItems = (cur.items || []).filter(r => r.cogs != null && r.cogs > 0);
  const priorMap  = new Map((prev.items || []).map(r => [r.sku_code, r]));
  const top60 = [...costItems].sort((a,b)=>(b.cogs||0)-(a.cogs||0)).slice(0,60);
  const totalCogsAll = costItems.reduce((s,r)=>s+(r.cogs||0),0);
  const totalCogsTop = top60.reduce((s,r)=>s+(r.cogs||0),0);
  const totalQtyTop  = top60.reduce((s,r)=>s+(r.qty||0),0);

  kpis.innerHTML = [
    { label:'Total COGS (เดือนนี้)', value:fmtN(Math.round(totalCogsAll)), color:'#dc2626' },
    { label:`Top 60 = ${totalCogsAll ? (totalCogsTop/totalCogsAll*100).toFixed(1) : '—'}% ของต้นทุน`, value:fmtN(Math.round(totalCogsTop)), color:'#f59e0b' },
    { label:'จำนวนเมนูมีต้นทุน', value:fmtN(costItems.length), color:'#6366f1' },
    { label:'Costed SKUs', value:`${cur.summary?.costed_skus||0}/${cur.summary?.total_skus||0}`, color:'#64748b' },
  ].map(k=>`<div class="rounded-lg p-3 text-center" style="background:${k.color}0f;border:1px solid ${k.color}33">
    <p class="text-[10px] uppercase tracking-wide font-semibold" style="color:var(--text-muted)">${k.label}</p>
    <p class="text-lg font-bold" style="color:${k.color}">${k.value}</p></div>`).join('');

  let cum = 0, totQtyDelta = 0, totCogsDelta = 0, anyPrior = false;
  body.innerHTML = top60.length ? top60.map((r,i) => {
    const prior = priorMap.get(r.sku_code);
    const qtyDelta  = prior ? (r.qty||0)-(prior.qty||0) : null;
    const cogsDelta = prior ? (r.cogs||0)-(prior.cogs||0) : null;
    if (prior) { anyPrior = true; totQtyDelta += qtyDelta; totCogsDelta += cogsDelta; }
    const shareAll = totalCogsAll ? ((r.cogs||0)/totalCogsAll*100) : 0;
    cum += shareAll;
    const dCell = (v, round) => v==null ? '<span class="text-slate-300">—</span>'
      : `<span style="color:${v>0?'#dc2626':v<0?'#059669':'#64748b'}">${v>0?'+':''}${fmtN(round?Math.round(v):v)}</span>`;
    return `<tr class="border-t border-slate-100 ${i<5?'bg-red-50/30':''}">
      <td class="py-1.5 pr-3 text-slate-400">${i+1}</td>
      <td class="py-1.5 pr-3 font-medium text-slate-800">${esc(r.description||r.sku_code)}</td>
      <td class="py-1.5 pr-3 text-slate-400">${r.category||'—'}</td>
      <td class="py-1.5 pr-3 text-right">${fmtN(r.qty||0)}</td>
      <td class="py-1.5 pr-3 text-right font-semibold text-red-600">${fmtN(Math.round(r.cogs||0))}</td>
      <td class="py-1.5 pr-3 text-right text-slate-500">${shareAll.toFixed(1)}%</td>
      <td class="py-1.5 pr-3 text-right text-slate-400">${cum.toFixed(1)}%</td>
      <td class="py-1.5 pr-3 text-right">${dCell(qtyDelta,false)}</td>
      <td class="py-1.5 text-right">${dCell(cogsDelta,true)}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="9" class="py-4 text-center text-slate-400 text-xs">ไม่มีข้อมูลต้นทุนสำหรับสาขา/เดือนนี้ — อัปโหลดที่ Settings → Cost Management</td></tr>';

  if (foot && top60.length) {
    const dTot = (v, round) => !anyPrior ? '<span class="text-slate-300">—</span>'
      : `<span style="color:${v>0?'#dc2626':v<0?'#059669':'#64748b'}">${v>0?'+':''}${fmtN(round?Math.round(v):v)}</span>`;
    foot.innerHTML = `<tr class="border-t-2 border-slate-300 bg-slate-50">
      <td class="py-2 pr-3"></td>
      <td class="py-2 pr-3" colspan="2">รวม Top 60 เมนู</td>
      <td class="py-2 pr-3 text-right">${fmtN(totalQtyTop)}</td>
      <td class="py-2 pr-3 text-right text-red-700">${fmtN(Math.round(totalCogsTop))}</td>
      <td class="py-2 pr-3 text-right">${totalCogsAll?(totalCogsTop/totalCogsAll*100).toFixed(1):'—'}%</td>
      <td class="py-2 pr-3"></td>
      <td class="py-2 pr-3 text-right">${dTot(totQtyDelta,false)}</td>
      <td class="py-2 text-right">${dTot(totCogsDelta,true)}</td>
    </tr>`;
  }
}

// §9 Buffet price-tier block — reuses /api/reports/price-tier for the report's
// headline month (A = that month, B = auto previous same-length window). Hidden
// with a note when the tier fact tables don't cover the month.
async function renderReportTier(month) {
  const block = document.getElementById('rptTierBlock');
  const note = document.getElementById('rptTierNote');
  if (!block) return;
  if (!month) { block.innerHTML = '<p class="text-xs text-slate-400">ไม่มีเดือนข้อมูล</p>'; return; }
  block.innerHTML = '<p class="text-xs text-slate-400 py-2">กำลังโหลด…</p>';
  const [y, m] = month.split('-').map(Number);
  const lastDay = new Date(y, m, 0).getDate();
  const p = new URLSearchParams({ date_from: `${month}-01`, date_to: `${month}-${String(lastDay).padStart(2, '0')}`,
                                  scope: reportScope || 'all' });
  let d;
  try { d = await fetch(`${API}/api/reports/price-tier?${p}`).then(r => r.json()); }
  catch (e) { block.innerHTML = '<p class="text-xs text-slate-400">โหลดข้อมูล Tier ไม่สำเร็จ</p>'; return; }
  if (!d.ready || d.error || !(d.tiers || []).length) {
    block.innerHTML = `<p class="text-xs text-slate-400">${esc(d.error || d.hint || 'ไม่มีข้อมูล Tier สำหรับเดือนนี้')}</p>`;
    return;
  }
  if (note) note.textContent =
    `เดือน ${fmtMonth(month)} (A) เทียบ ${d.b_range[0]} → ${d.b_range[1]} (B) · ${d.scope_label || ''} · Tier = ราคาบุฟเฟ่ต์ผู้ใหญ่บนบิล (ไม่รวม VAT) · นับเฉพาะบิลบุฟเฟ่ต์`;
  const sgn = v => v == null ? '—' : `<span style="color:${v > 0 ? '#dc2626' : v < 0 ? '#059669' : '#64748b'}">${v > 0 ? '+' : ''}${v.toLocaleString('en-US', { maximumFractionDigits: 1 })}</span>`;
  const paxD = v => v == null ? '—' : `<span style="color:${v >= 0 ? '#059669' : '#dc2626'}">${v >= 0 ? '▲' : '▼'} ${Math.abs(v).toFixed(1)}%</span>`;
  const rows = d.tiers.map(x => `<tr class="border-t border-slate-100">
    <td class="py-2 pr-4 font-semibold">${esc(x.label)}</td>
    <td class="py-2 pr-4 text-right">${fmtN(x.a.pax)}</td>
    <td class="py-2 pr-4 text-right">${paxD(x.d_pax_pct)}</td>
    <td class="py-2 pr-4 text-right">${x.a.share ?? '—'}%<span class="text-[10px] text-slate-400"> (${x.d_share_pp != null ? (x.d_share_pp > 0 ? '+' : '') + x.d_share_pp : '—'}pp)</span></td>
    <td class="py-2 pr-4 text-right">${x.a.rev_head != null ? '฿' + fmtN(x.a.rev_head) : '—'}</td>
    <td class="py-2 pr-4 text-right">${x.a.cogs_head != null ? '฿' + fmtN(x.a.cogs_head) : '—'}<span class="text-[10px]"> (${sgn(x.d_cogs_head)})</span></td>
    <td class="py-2 pr-4 text-right font-semibold">${x.a.gp_head != null ? '฿' + fmtN(x.a.gp_head) : '—'}</td>
    <td class="py-2 text-right">${x.a.food_pct ?? '—'}%</td></tr>`).join('');
  const mix = (d.mix_effect != null && Math.abs(d.mix_effect) >= 1)
    ? `<p class="text-xs mt-2 font-medium" style="color:${d.mix_effect < 0 ? '#dc2626' : '#059669'}">${d.mix_effect < 0 ? 'ลูกค้าย้ายไป tier ถูกลง — ผลจาก mix กดรายได้/หัวลง ฿' + Math.abs(d.mix_effect).toFixed(2) : 'ลูกค้าย้ายขึ้น tier แพงขึ้น — ผลจาก mix เพิ่มรายได้/หัว ฿' + d.mix_effect.toFixed(2)}</p>` : '';
  const bullets = (d.insights || []).slice(0, 4).map(t => `<li>💡 ${esc(t)}</li>`).join('');
  block.innerHTML = `<table class="text-sm text-slate-700 w-full">
      <thead><tr class="text-left text-xs text-slate-500 uppercase tracking-wide border-b border-slate-200">
        <th class="py-2 pr-4">Tier</th><th class="py-2 pr-4 text-right">คนทาน (A)</th>
        <th class="py-2 pr-4 text-right">Δ คนทาน</th><th class="py-2 pr-4 text-right">สัดส่วน (Δpp)</th>
        <th class="py-2 pr-4 text-right">รายได้/หัว</th><th class="py-2 pr-4 text-right">ต้นทุน/หัว (Δ)</th>
        <th class="py-2 pr-4 text-right">GP/หัว</th><th class="py-2 text-right">Food%</th>
      </tr></thead><tbody>${rows}</tbody></table>
    ${mix}${bullets ? `<ul class="text-xs text-slate-600 mt-2 space-y-1" style="list-style:none;padding:0">${bullets}</ul>` : ''}
    <p class="text-[11px] text-slate-400 mt-2">ดูเชิงลึก (Top-30 เมนูต้นทุนตาม tier, เทรนด์รายเดือน, ข้อเสนอแนะ) ได้ที่แท็บ 🧪 วิเคราะห์วัตถุดิบ → 🏷️ วิเคราะห์ Tier ราคาขาย</p>`;
}

// Run async thunks with bounded concurrency, preserving input order. Used by the
// Analysis Report so it doesn't fire all ~16 queries at once (that put too many
// heavy queries on the small host simultaneously and OOM-killed it). Rejects if
// any thunk rejects — same failure semantics as Promise.all.
async function _poolAll(thunks, limit = 4) {
  const results = new Array(thunks.length);
  let next = 0;
  async function worker() {
    while (next < thunks.length) {
      const i = next++;
      results[i] = await thunks[i]();
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, thunks.length) }, worker));
  return results;
}

// Print / Export PDF. The Analysis Report fills its sections from ~15 async
// fetches (~2 s); calling window.print() immediately captured a blank report.
// When the report tab is active we force a full (re)load and await render before
// opening the print dialog, so the printed/saved PDF always has data.
//
// Two guards keep this robust on the small (512 MB) host:
//   • _printing re-entrancy lock — when the host is slow the dialog doesn't open
//     instantly, so users click 🖨️ repeatedly; without this each click re-fired
//     the whole ~17-query report load and the stacked batches thrashed/OOM'd the
//     host (a request storm seen in the logs). The lock collapses repeat clicks.
//   • Promise.race timeout — fetches have no per-request timeout, so one hung
//     request would block window.print() forever ("nothing happens"). After the
//     deadline we print whatever has rendered instead of hanging.
let _printing = false;
async function printReport() {
  if (_printing) return;                 // ignore repeat clicks while preparing
  _printing = true;
  try {
    if (typeof activeTab !== 'undefined' && activeTab === 'report') {
      showLoadingBar();
      try {
        _tabLastKey.report = null;
        await Promise.race([
          loadReport(),
          new Promise((_, rej) => setTimeout(() => rej(new Error('preload timeout')), 15000)),
        ]);
      }
      catch (e) { console.error('print preload failed/timed out — printing current view', e); }
      finally { hideLoadingBar(); }
      await new Promise(r => setTimeout(r, 80));   // let layout settle before snapshot
    }
    window.print();
  } finally { _printing = false; }
}

// Analysis Report scope: '' = overview (all branches), 'master' / 'franchise' =
// that branch group only. Report-local (independent of the global top-bar group
// filter) so the user can flip all/master/franchise from inside the report.
let reportScope = '';
function _rptScopeLabel(sc) {
  return sc === 'master' ? '🏢 เฉพาะสาขา Master'
       : sc === 'franchise' ? '🤝 เฉพาะแฟรนไชส์'
       : 'ภาพรวมทุกกลุ่ม (Master + Franchise)';
}
// Force `group` on a query string to the current report scope (overriding any
// global group), or strip it entirely for the overview.
function _rptScopeQp(qs) {
  const u = new URLSearchParams((qs || '').replace(/^\?/, ''));
  if (reportScope) u.set('group', reportScope); else u.delete('group');
  const s = u.toString();
  return s ? '?' + s : '';
}
function _rptScopeHighlight() {
  document.querySelectorAll('#rptScopeSel button').forEach(b => {
    const on = (b.dataset.scope || '') === reportScope;
    b.style.background = on ? 'rgba(255,255,255,0.95)' : 'transparent';
    b.style.color      = on ? '#4338ca' : '#fff';
  });
}
function setReportScope(sc) {
  reportScope = sc || '';
  _rptScopeHighlight();
  _tabLastKey.report = null;   // bust the per-tab cache so the report reloads
  loadReport();
}

async function loadReport() {
  // Include scope in the cache key so switching all/master/franchise reloads.
  const _fk = _filterKey() + '|scope=' + reportScope;
  if (_tabLastKey.report === _fk) return; _tabLastKey.report = _fk;
  _rptScopeHighlight();
  const branch = getBranch();
  const month  = getMonth();
  const monthFrom = getMonthFrom();
  const monthTo   = getMonthTo();

  // Header
  document.getElementById('rptPeriod').textContent = monthFrom ? (`${fmtMonth(monthFrom)} → ${fmtMonth(monthTo || monthFrom)}`) : (month ? fmtMonth(month) : 'All Months');
  document.getElementById('rptBranch').textContent =
    (branch ? 'Branch: ' + branch : 'All Branches') + ' · ' + _rptScopeLabel(reportScope);
  document.getElementById('rptDate').textContent   = new Date().toLocaleDateString('th-TH');

  // Sticky section nav — clickable chips that scroll to each §
  const topics = [
    'สรุปผู้บริหาร','รายได้และการเติบโต','อันดับสาขา',
    'ต้นทุน/หัว เมนู','พฤติกรรมลูกค้า','เวลาและการดำเนินงาน',
    'รายได้ตามวันและเวลา','ต้นทุนเมนูสูง','ราคาและส่วนลด','พยากรณ์และข้อเสนอแนะ',
  ];
  document.getElementById('rptNavInner').innerHTML = topics.map((t,i) =>
    `<a href="#rpt${i+1}" onclick="event.preventDefault();document.getElementById('rpt${i+1}')?.scrollIntoView({behavior:'smooth'})"
        class="px-2.5 py-1 rounded-lg hover:bg-indigo-50 text-slate-500 hover:text-indigo-700 transition-colors cursor-pointer">
        <span class="text-slate-300 font-mono">${i+1}</span> ${t}</a>`).join('');

  // Every report query is forced to the current scope (all / master / franchise)
  // via _rptScopeQp, independent of the global top-bar group filter.
  const qpStr = _rptScopeQp(qp());
  // Fetch all in parallel
  // Compute prior-month params for MoM cost comparison
  const _curTo   = monthTo   || monthFrom || '';
  const _curFrom = monthFrom || '';
  let priorQpStr = qpStr;
  if (_curTo) {
    const [py, pm] = _curTo.split('-').map(Number);
    const pp = pm === 1 ? `${py-1}-12` : `${py}-${String(pm-1).padStart(2,'0')}`;
    const priorP = new URLSearchParams();
    if (branch) priorP.set('branch', branch);
    priorP.set('month_from', pp); priorP.set('month_to', pp);
    priorQpStr = _rptScopeQp('?' + priorP.toString());
  }

  const [
    summary, trend, skus, cats, persona,
    branches, yoy, costAnalysis, costPrior,
    timeHourly, timeDow, discounts, anomalies, forecast, forecastBranches,
    costHead,
    // Bounded concurrency (≤4): firing all 16 at once put ~6 heavy queries on
    // the small host simultaneously and OOM-killed it. _poolAll keeps the order
    // and rejects if a non-caught fetch fails (same as Promise.all did).
  ] = await _poolAll([
    () => fetch(`${API}/api/summary${qpStr}`).then(r=>r.json()),
    () => fetch(`${API}/api/sales/monthly${qpStr}`).then(r=>r.json()),
    () => fetch(`${API}/api/sales/skus${_rptScopeQp(qp({limit:15}))}`).then(r=>r.json()),
    () => fetch(`${API}/api/sales/category${qpStr}`).then(r=>r.json()),
    () => fetch(`${API}/api/analysis/persona${qpStr}`).then(r=>r.json()),
    () => fetch(`${API}/api/analysis/branches${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/analysis/yoy${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/cost/analysis${qpStr}`).then(r=>r.json()).catch(()=>({items:[],summary:{}})),
    () => fetch(`${API}/api/cost/analysis${priorQpStr}`).then(r=>r.json()).catch(()=>({items:[],summary:{}})),
    () => fetch(`${API}/api/analysis/hourly_open${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/analysis/dow${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/analysis/discounts${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/analysis/anomalies${qpStr}`).then(r=>r.json()).catch(()=>[]),
    () => fetch(`${API}/api/forecast${_rptScopeQp(branch?'?branch='+encodeURIComponent(branch):'')}`).then(r=>r.json()).catch(()=>({available:false})),
    () => fetch(`${API}/api/forecast?mode=branches${reportScope?'&group='+reportScope:''}`).then(r=>r.json()).catch(()=>({available:false})),
    () => fetch(`${API}/api/sales/top_ordered${_rptScopeQp(qp({limit:60, sort:'cogs'}))}`).then(r=>r.json()).catch(()=>null),
  ], 4);

  // Full monthly history (branch/group only, no month-range) so MoM/YTD framing
  // works even when the user narrows the filter to a single month — otherwise
  // `trend` has 1 row and every MoM chip collapses to "—".
  const _fullP = new URLSearchParams();
  if (branch) _fullP.set('branch', branch);
  const _fullQp = _rptScopeQp(_fullP.toString() ? '?' + _fullP.toString() : '');
  const trendFull = await fetch(`${API}/api/sales/monthly${_fullQp}`).then(r=>r.json()).catch(()=>trend);
  // Per-branch monthly revenue (scoped, full history) → powers §3 ranking
  // movement, per-branch MoM, and YTD sparklines.
  const branchMonthlyRaw = await fetch(`${API}/api/gp/by-branch-month${_rptScopeQp('')}`).then(r=>r.json()).catch(()=>({rows:[]}));
  // Data window → the report must NOT headline a PARTIAL trailing month (e.g. data
  // through Jun-03) vs a full prior month (a misleading ~-90% MoM). Lead with the
  // last COMPLETE month; surface the partial month separately as MTD.
  const dataWin = await fetch(`${API}/api/meta/data-window`).then(r=>r.json()).catch(()=>({}));
  const completeMonth = dataWin.last_complete_month || null;   // e.g. 2026-05
  const partialMonth  = dataWin.partial_month || null;         // e.g. 2026-06 (3 days)

  // ── Monthly-framing helpers — lead with the latest COMPLETE month + MoM/YoY/YTD.
  const _rowFor = mm => (Array.isArray(trend) && trend.find(r => r.period_month === mm))
                     || (Array.isArray(trendFull) && trendFull.find(r => r.period_month === mm)) || null;
  const _prevMonthStr = mm => { if (!mm) return null; let [y,m]=mm.split('-').map(Number); m-=1; if(m<1){m=12;y-=1;} return `${y}-${String(m).padStart(2,'0')}`; };
  // Headline month — never lead with the in-progress (partial) month by default: a
  // partial month vs a full prior month reads as a false ~-100% MoM across every
  // section. Mirrors the Management Report's "anchor on the latest COMPLETE period"
  // guard. Rules:
  //   • user pinned ONLY the current month (from==to==partial) → honour it, flagged (MTD)
  //   • an explicit month that isn't the partial one          → use it
  //   • otherwise (no filter, or a range ending on the partial month, e.g. the
  //     default YTD range) → fall back to the last COMPLETE month
  const _filterHeadMonth = monthTo || monthFrom || null;
  const _explicitPartialOnly = partialMonth && monthFrom === partialMonth && monthTo === partialMonth;
  const _headMonth = _explicitPartialOnly ? partialMonth
    : (_filterHeadMonth && _filterHeadMonth !== partialMonth) ? _filterHeadMonth
    : (completeMonth || _filterHeadMonth || null);
  let mLast = _headMonth
    ? (_rowFor(_headMonth) || {period_month: _headMonth})
    : (trend[trend.length-1] || {});
  let mPrev = _rowFor(_prevMonthStr(mLast.period_month));
  if (!mPrev && trend.length >= 2 && !completeMonth) mPrev = trend[trend.length-2];
  // Partial (MTD) month, for a separate note.
  const mPartial = partialMonth ? _rowFor(partialMonth) : null;
  const _isMtdHeadline = mLast.period_month && mLast.period_month === partialMonth;
  const mLastLabel = mLast.period_month
    ? fmtMonth(mLast.period_month) + (_isMtdHeadline ? ' (MTD)' : '')
    : '—';
  const pctDelta = (cur, prev) => (prev && prev > 0) ? ((cur - prev) / prev * 100) : null;
  const momChip = p => p == null ? '<span class="text-slate-300">—</span>'
    : `<span style="color:${p>=0?'#059669':'#dc2626'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}%</span>`;
  const yoyForMonth = m => { const y = yoy.find(x => x.period_month === m); return (y && y.yoy_pct != null) ? y.yoy_pct : null; };
  const _cs0 = costAnalysis.summary || {};
  const lastAov = mLast.tx_count ? Math.round(mLast.revenue / mLast.tx_count) : 0;
  const prevAov = (mPrev && mPrev.tx_count) ? Math.round(mPrev.revenue / mPrev.tx_count) : 0;

  // ── §1 Executive Summary — latest month vs previous month (+ YoY), not a period sum
  const exKpis = [
    { label:`รายได้ · ${mLastLabel}`, value:fmt(mLast.revenue||0), mom:pctDelta(mLast.revenue, mPrev?.revenue), yoy:yoyForMonth(mLast.period_month) },
    { label:`บิล · ${mLastLabel}`, value:fmtN(mLast.tx_count||0), mom:pctDelta(mLast.tx_count, mPrev?.tx_count) },
    { label:`ลูกค้า · ${mLastLabel}`, value:fmtN(mLast.customer_count||0), mom:pctDelta(mLast.customer_count, mPrev?.customer_count) },
    { label:`ยอดบิลเฉลี่ย · ${mLastLabel}`, value:fmtN(lastAov), mom:pctDelta(lastAov, prevAov) },
  ];
  const mPrevLabel = (mPrev && mPrev.period_month) ? fmtMonth(mPrev.period_month) : '—';
  document.getElementById('rptKpis').innerHTML = exKpis.map(k =>
    `<div class="p-4 bg-slate-50 rounded-lg">
      <p class="text-xs text-slate-500 uppercase tracking-wide mb-1">${k.label}</p>
      <p class="text-2xl font-bold text-indigo-700">${k.value}</p>
      <p class="text-[11px] mt-1 text-slate-500">MoM ${momChip(k.mom)} <span class="text-slate-400">vs ${mPrevLabel}</span></p>
    </div>`).join('');

  // ── KPI hero band — latest month at-a-glance (+ period margin)
  const heroCards = [
    { label:`รายได้ · ${mLastLabel}`, value:fmt(mLast.revenue||0), accent:'#4f46e5', mom:pctDelta(mLast.revenue, mPrev?.revenue) },
    { label:'Gross Margin', value:_cs0.overall_margin_pct!=null?_cs0.overall_margin_pct.toFixed(1)+'%':'—', accent:'#059669' },
    { label:`บิล · ${mLastLabel}`, value:fmtN(mLast.tx_count||0), accent:'#0891b2', mom:pctDelta(mLast.tx_count, mPrev?.tx_count) },
    { label:`ลูกค้า · ${mLastLabel}`, value:fmtN(mLast.customer_count||0), accent:'#7c3aed', mom:pctDelta(mLast.customer_count, mPrev?.customer_count) },
    { label:`ยอดบิลเฉลี่ย · ${mLastLabel}`, value:fmtN(lastAov), accent:'#d97706', mom:pctDelta(lastAov, prevAov) },
  ];
  document.getElementById('rptHero').innerHTML = heroCards.map(h =>
    `<div class="card p-4" style="border-top:3px solid ${h.accent}">
      <p class="text-[11px] text-slate-500 uppercase tracking-wide mb-1">${h.label}</p>
      <p class="text-2xl font-bold" style="color:${h.accent}">${h.value}</p>
      ${h.mom!=null?`<p class="text-[11px] mt-0.5">MoM ${momChip(h.mom)}</p>`:''}
    </div>`).join('');

  // Alerts
  const alerts = [];
  const periodTotalRev = trend.reduce((a,r)=>a+(r.revenue||0),0);
  alerts.push(`🗓️ <b>เดือนล่าสุดที่จบแล้ว:</b> ${mLastLabel} · สรุปด้านบนเป็น<b>รายเดือนเต็ม</b> (MoM/YoY เทียบเดือนเต็มต่อเดือนเต็ม)${(partialMonth && mPartial) ? ` · <b>${fmtMonth(partialMonth)}</b> ยังไม่จบ (ข้อมูลถึงวันที่ ${dataWin.max_day}) แสดงเป็น MTD ใน §2 ไม่นำมาเทียบ` : ''} · ยอดรวมทั้งช่วง ${trend.length} เดือน = ${fmt(periodTotalRev)}`);
  const latestYoy = yoy[yoy.length-1];
  if (latestYoy && latestYoy.yoy_pct != null) {
    alerts.push(`📊 <b>YoY ${latestYoy.period_month}:</b> ${latestYoy.yoy_pct>=0?'+':''}${latestYoy.yoy_pct.toFixed(1)}% vs ${latestYoy.ly_period}`);
  }
  const cs = costAnalysis.summary || {};
  if (cs.overall_margin_pct != null) {
    alerts.push(`💰 <b>Gross margin:</b> ${cs.overall_margin_pct.toFixed(1)}% (on ${cs.costed_skus||0}/${cs.total_skus||0} costed SKUs)`);
  } else {
    alerts.push(`⚠ <b>No SKU costs uploaded.</b> Profit & margin analysis are unavailable.`);
  }
  if (anomalies.length) alerts.push(`🚨 <b>${anomalies.length} anomalies</b> detected in the last 90 days (see §10).`);
  document.getElementById('rptExecAlerts').innerHTML = alerts.map(a=>`<div class="px-3 py-2 bg-slate-50 rounded">${a}</div>`).join('');

  // ── §2 Revenue Performance & Growth — monthly + YTD movement (not a big sum)
  const trendWithYoy = trend.map(r => ({ ...r, yoy: yoy.find(y => y.period_month === r.period_month) }));
  const totalRevTrend = trend.reduce((a,r)=>a+(r.revenue||0),0);
  // YTD: current-year months up to the latest, vs the same months last year
  const curYear = (mLast.period_month || '').slice(0,4);
  const ytdMonths = trend.filter(r => (r.period_month||'').slice(0,4) === curYear);
  const ytdRev = ytdMonths.reduce((a,r)=>a+(r.revenue||0),0);
  // Only compare YTD vs last year when EVERY ytd month has a prior-year counterpart
  // with real revenue — otherwise a partial/empty base (data started mid-2025)
  // produces a meaningless 5-digit %.
  let priorYtd = 0, matched = 0;
  ytdMonths.forEach(r => {
    const [y,m] = (r.period_month||'').split('-');
    const lyRow = trend.find(x => x.period_month === `${(+y)-1}-${m}`);
    if (lyRow && (lyRow.revenue||0) > 0) { priorYtd += lyRow.revenue; matched++; }
  });
  const ytdComparable = ytdMonths.length > 0 && matched === ytdMonths.length && priorYtd > 0;
  let ytdGrowth = ytdComparable ? ((ytdRev - priorYtd)/priorYtd*100) : null;
  // Sanity: an extreme swing means the base year was still ramping up — don't mislead.
  if (ytdGrowth != null && Math.abs(ytdGrowth) > 300) ytdGrowth = null;
  const bestMonth = trend.length ? trend.reduce((mx,r)=>(r.revenue||0)>(mx.revenue||0)?r:mx, trend[0]) : null;
  const avgMonth = trend.length ? totalRevTrend/trend.length : 0;
  const momLast = pctDelta(mLast.revenue, mPrev?.revenue);
  const yoyLast = yoyForMonth(mLast.period_month);
  document.getElementById('rptRevHeadline').innerHTML = `
    <div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-1">
      ${(partialMonth && mPartial) ? `
      <div class="p-3 rounded-lg" style="background:#fffbeb;border:1px solid #fde68a">
        <p class="text-xs text-slate-500">MTD ${fmtMonth(partialMonth)} <span class="text-amber-600">(${dataWin.max_day||'?'} วันแรก)</span></p>
        <p class="text-lg font-bold text-amber-700">${fmt(mPartial.revenue||0)}</p>
        <p class="text-[11px] text-slate-400">เดือนยังไม่จบ — ไม่นำมาเทียบ MoM</p>
      </div>` : `
      <div class="p-3 rounded-lg bg-slate-50">
        <p class="text-xs text-slate-500">เดือนล่าสุด (${mLastLabel})</p>
        <p class="text-lg font-bold text-indigo-700">${fmt(mLast.revenue||0)}</p>
        <p class="text-[11px]">MoM ${momChip(momLast)} <span class="text-slate-400">vs ${mPrevLabel}</span></p>
      </div>`}
      <div class="p-3 rounded-lg bg-slate-50">
        <p class="text-xs text-slate-500">YTD ${curYear} (${ytdMonths.length} เดือน)</p>
        <p class="text-lg font-bold text-emerald-700">${fmt(ytdRev)}</p>
        <p class="text-[11px]">${ytdGrowth!=null?`vs YTD ${(+curYear)-1} ${momChip(ytdGrowth)}`:'<span class="text-slate-400">ไม่มีปีก่อนเทียบ</span>'}</p>
      </div>
      <div class="p-3 rounded-lg bg-slate-50">
        <p class="text-xs text-slate-500">เฉลี่ย/เดือน</p>
        <p class="text-lg font-bold text-slate-700">${fmt(avgMonth)}</p>
        <p class="text-[11px] text-slate-400">${trend.length} เดือนในช่วง</p>
      </div>
      <div class="p-3 rounded-lg bg-slate-50">
        <p class="text-xs text-slate-500">เดือนสูงสุด</p>
        <p class="text-lg font-bold text-amber-700">${bestMonth?fmtMonth(bestMonth.period_month):'—'}</p>
        <p class="text-[11px] text-slate-400">${bestMonth?fmt(bestMonth.revenue||0):''}</p>
      </div>
    </div>`;
  const _miniMoM = (cur, prev) => {
    if (!(prev > 0) || cur == null) return '';
    const p = (cur - prev) / prev * 100;
    return `<span class="block text-[10px]" style="color:${p>=0?'#059669':'#dc2626'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}%</span>`;
  };
  document.getElementById('rptTrendBody').innerHTML = trend.map((r,i) => {
    const prev = trend[i-1];
    const isPartial = r.period_month === partialMonth;   // suppress its misleading MoM
    const mom = (v, pv) => isPartial ? '' : _miniMoM(v, pv);
    const avgTicket = r.tx_count ? Math.round(r.revenue / r.tx_count) : 0;
    const prevAT = (prev && prev.tx_count) ? Math.round(prev.revenue / prev.tx_count) : 0;
    return `<tr class="border-t border-slate-100" style="${isPartial?'background:#fffbeb':''}">
      <td class="py-2 pr-6">${fmtMonth(r.period_month)}${isPartial?` <span class="text-[10px] text-amber-600">· บางส่วน ${dataWin.max_day||''} วัน</span>`:''}</td>
      <td class="py-2 pr-6 text-right font-semibold">${fmtN(r.revenue)}${mom(r.revenue, prev?.revenue)}</td>
      <td class="py-2 pr-6 text-right">${r.tx_count?fmtN(r.tx_count):'—'}${mom(r.tx_count, prev?.tx_count)}</td>
      <td class="py-2 pr-6 text-right">${r.customer_count?fmtN(r.customer_count):'—'}${mom(r.customer_count, prev?.customer_count)}</td>
      <td class="py-2 text-right">${avgTicket?fmtN(avgTicket):'—'}${isPartial?'':_miniMoM(avgTicket, prevAT)}</td>
    </tr>`;
  }).join('');

  // ── §3 Branch Performance Ranking — latest month, MoM, rank movement, YTD spark
  const _bm = {};   // branch -> { month: revenue }
  (branchMonthlyRaw.rows || []).forEach(r => {
    const mm = _bm[r.branch] || (_bm[r.branch] = {});
    (r.monthly || []).forEach(m => { mm[m.month] = (mm[m.month] || 0) + (m.revenue || 0); });
  });
  const _allMonthsB = Array.from(new Set(Object.values(_bm).flatMap(o => Object.keys(o)))).sort();
  // Rank by the last COMPLETE month (not the partial trailing one) so MoM is a
  // like-for-like full-month vs full-month comparison, not 3-days-vs-full-month.
  const _lastMo = (completeMonth && _allMonthsB.includes(completeMonth))
    ? completeMonth : (_allMonthsB[_allMonthsB.length - 1] || null);
  const _lastIdx = _allMonthsB.indexOf(_lastMo);
  const _prevMo = _lastIdx > 0 ? _allMonthsB[_lastIdx - 1] : null;
  const revOf = (br, mo) => (mo && _bm[br]) ? (_bm[br][mo] || 0) : 0;
  const rankByMonth = mo => {
    const map = {};
    Object.keys(_bm).map(br => ({ br, rev: revOf(br, mo) })).filter(x => x.rev > 0)
      .sort((a, b) => b.rev - a.rev).forEach((x, i) => map[x.br] = i + 1);
    return map;
  };
  const _curRank  = rankByMonth(_lastMo);
  const _prevRank = _prevMo ? rankByMonth(_prevMo) : {};
  const _spark = (vals, w = 84, h = 22) => {
    const v = (vals || []).filter(x => x != null);
    if (v.length < 2) return '<span class="text-slate-300 text-[10px]">—</span>';
    const mn = Math.min(...v), mx = Math.max(...v), rng = (mx - mn) || 1;
    const pts = v.map((x, i) => `${(i / (v.length - 1) * w).toFixed(1)},${(h - ((x - mn) / rng) * h).toFixed(1)}`).join(' ');
    const up = v[v.length - 1] >= v[0];
    return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="vertical-align:middle"><polyline points="${pts}" fill="none" stroke="${up?'#10b981':'#ef4444'}" stroke-width="1.5" stroke-linejoin="round"/></svg>`;
  };
  const _curYear = (_lastMo || '').slice(0, 4);
  const _ytdMonths = _allMonthsB.filter(m => m.slice(0, 4) === _curYear);
  const _curTotalRev = Object.keys(_bm).reduce((a, br) => a + revOf(br, _lastMo), 0) || 1;

  const branchesByLast = Object.keys(_bm).map(br => {
    const last = revOf(br, _lastMo), prev = revOf(br, _prevMo);
    const meta = branches.find(x => x.branch === br) || {};
    return {
      branch: br, last, prev,
      // A branch whose prior month is <5% of this month barely operated last
      // month (newly opened) — its MoM% would be a meaningless 5-digit number.
      mom: (prev > 0 && prev >= last * 0.05) ? (last - prev) / prev * 100 : null,
      ramp: (prev > 0 && prev < last * 0.05),
      dRank: (_curRank[br] && _prevRank[br]) ? (_prevRank[br] - _curRank[br]) : null,
      isNew: (_curRank[br] && !_prevRank[br]),
      share: last / _curTotalRev * 100,
      avg_ticket: meta.avg_ticket || 0,
      ytd: _ytdMonths.map(m => revOf(br, m)),
    };
  }).filter(b => b.last > 0).sort((a, b) => b.last - a.last);

  const _momChipS = p => p == null ? '<span class="text-slate-300">—</span>'
    : `<span style="color:${p>=0?'#059669':'#dc2626'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}%</span>`;
  const _rankMove = b => {
    if (b.isNew) return '<span style="color:#0891b2">🆕</span>';
    if (b.dRank == null || b.dRank === 0) return '<span class="text-slate-400">—</span>';
    return b.dRank > 0
      ? `<span style="color:#059669">▲ ${b.dRank}</span>`
      : `<span style="color:#dc2626">▼ ${Math.abs(b.dRank)}</span>`;
  };
  const rankSub = document.getElementById('rptBranchRankSub');
  if (rankSub && _lastMo) rankSub.innerHTML = `จัดอันดับตามรายได้เดือน <b>${fmtMonth(_lastMo)}</b>${_prevMo?` · MoM/ขยับ เทียบ ${fmtMonth(_prevMo)}`:''} · YTD = แนวโน้มรายได้ปี ${_curYear}`;

  document.getElementById('rptBranchBody').innerHTML = branchesByLast.length
    ? branchesByLast.map((b, i) => {
        const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1);
        return `<tr class="border-t border-slate-100">
          <td class="py-2 pr-4">${medal}</td>
          <td class="py-2 pr-4 font-medium">${esc(b.branch)}</td>
          <td class="py-2 pr-4 text-right font-semibold">${fmtN(b.last)}</td>
          <td class="py-2 pr-4 text-right">${b.ramp?'<span style="color:#0891b2">🆕 พุ่ง</span>':_momChipS(b.mom)}</td>
          <td class="py-2 pr-4 text-center">${_rankMove(b)}</td>
          <td class="py-2 pr-4 text-right">${b.share.toFixed(1)}%</td>
          <td class="py-2 pr-4 text-right">${fmtN(b.avg_ticket||0)}</td>
          <td class="py-2 text-center">${_spark(b.ytd)}</td>
        </tr>`;
      }).join('')
    : [...branches].sort((a,b)=>(b.revenue||0)-(a.revenue||0)).map((b,i)=>`<tr class="border-t border-slate-100">
        <td class="py-2 pr-4">${i+1}</td><td class="py-2 pr-4 font-medium">${esc(b.branch)}</td>
        <td class="py-2 pr-4 text-right">${fmtN(b.revenue||0)}</td><td class="py-2 pr-4 text-right">—</td>
        <td class="py-2 pr-4 text-center">—</td><td class="py-2 pr-4 text-right">—</td>
        <td class="py-2 pr-4 text-right">${fmtN(b.avg_ticket||0)}</td><td class="py-2 text-center">—</td></tr>`).join('');

  // ── §3b Branch profiling — how each branch deviates from the network median
  (function renderBranchProfile() {
    const el = document.getElementById('rptBranchProfile');
    if (!el) return;
    const rows = (branches || []).filter(b => (b.tx_count||0) > 0).map(b => ({
      branch: b.branch,
      aov: b.avg_ticket || 0,
      disc: b.discount_rate || 0,
      cpb: b.tx_count ? (b.customer_count||0)/b.tx_count : 0,   // customers per bill
      rev: b.revenue || 0,
    }));
    if (rows.length < 3) { el.innerHTML = '<p class="text-xs text-slate-400">ข้อมูลไม่พอสำหรับเทียบรายสาขา</p>'; return; }
    const median = arr => { const s=[...arr].sort((x,y)=>x-y); const n=s.length; return n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2; };
    const med = { aov:median(rows.map(r=>r.aov)), disc:median(rows.map(r=>r.disc)), cpb:median(rows.map(r=>r.cpb)), rev:median(rows.map(r=>r.rev)) };
    const dev = (v,m) => m ? (v-m)/m*100 : 0;
    const CAP = 60; // % deviation that maxes out the bar track
    const devColor = (d, goodHigh) => {
      if (Math.abs(d) < 20) return '#cbd5e1';
      const good = goodHigh==null ? null : ((d>0) === goodHigh);
      return good==null ? '#64748b' : (good ? '#059669' : '#dc2626');
    };
    // diverging mini-bar centered on the network median, ±CAP% maps to the half-track
    const bar = (d, goodHigh) => {
      const flagged = Math.abs(d) >= 20;
      const color = devColor(d, goodHigh);
      const w = (Math.min(Math.abs(d), CAP) / CAP * 50).toFixed(1);
      const side = d > 0
        ? `left:50%;width:${w}%;border-radius:0 3px 3px 0`
        : `right:50%;width:${w}%;border-radius:3px 0 0 3px`;
      const label = flagged ? `${d>0?'+':'-'}${Math.abs(d).toFixed(0)}%` : '—';
      return `<div class="flex items-center gap-2 justify-end" title="${d>=0?'+':''}${d.toFixed(1)}% vs median">
          <span class="text-[11px] tabular-nums w-10 text-right" style="color:${color}">${label}</span>
          <div class="relative w-14 h-2.5 bg-slate-100 rounded shrink-0">
            <div class="absolute top-0 left-1/2 w-px h-full bg-slate-300"></div>
            <div class="absolute top-0 h-full" style="${side};background:${color}"></div>
          </div>
        </div>`;
    };
    const highlight = (label, d, goodHigh) => {
      if (Math.abs(d) < 20) return null;
      const color = devColor(d, goodHigh);
      return `<span class="px-1.5 py-0.5 rounded text-[10px] whitespace-nowrap" style="background:${color}14;color:${color}">${label} ${d>0?'▲':'▼'}${Math.abs(d).toFixed(0)}%</span>`;
    };
    const scored = rows.map(r => ({
      ...r, dAov: dev(r.aov,med.aov), dDisc: dev(r.disc,med.disc), dCpb: dev(r.cpb,med.cpb), dRev: dev(r.rev,med.rev),
    })).sort((a,b) => b.rev - a.rev);
    el.innerHTML = `<div class="overflow-x-auto">
      <table class="text-xs w-full">
        <thead><tr class="text-left text-slate-400 border-b border-slate-100">
          <th class="py-1.5 pr-3">สาขา</th>
          <th class="py-1.5 pr-3 text-right">AOV</th>
          <th class="py-1.5 pr-3 text-right">ส่วนลด</th>
          <th class="py-1.5 pr-3 text-right">คน/บิล</th>
          <th class="py-1.5 pr-3 text-right">รายได้</th>
          <th class="py-1.5 pl-2">จุดเด่น</th>
        </tr></thead>
        <tbody>${scored.map(r => {
          const chips = [
            highlight('AOV', r.dAov, true),
            highlight('ส่วนลด', r.dDisc, false),
            highlight('คน/บิล', r.dCpb, null),
            highlight('รายได้', r.dRev, true),
          ].filter(Boolean);
          return `<tr class="border-t border-slate-50 hover:bg-slate-50">
            <td class="py-1.5 pr-3 font-medium text-slate-700 whitespace-nowrap">${esc(r.branch)}</td>
            <td class="py-1.5 pr-3">${bar(r.dAov, true)}</td>
            <td class="py-1.5 pr-3">${bar(r.dDisc, false)}</td>
            <td class="py-1.5 pr-3">${bar(r.dCpb, null)}</td>
            <td class="py-1.5 pr-3">${bar(r.dRev, true)}</td>
            <td class="py-1.5 pl-2"><div class="flex flex-wrap gap-1">${chips.length?chips.join(''):'<span class="text-[11px] text-slate-300">ใกล้เคียงค่ากลาง</span>'}</div></td>
          </tr>`;
        }).join('')}</tbody>
      </table></div>
      <p class="text-[11px] text-slate-400 mt-2">แถบ = ระยะห่างจากค่ากลาง (median) ของเครือ ณ ค่ากลาง (เส้นแบ่งกลาง) · 🟢เขียว = ทิศทางดี · 🔴แดง = ทิศทางแย่ · เทา = ต่างกันแต่ไม่มีทิศทางดี/แย่ชัดเจน</p>`;
  })();

  // ── §4 Top 60 เมนู — เทียบต้นทุนต่อหัว (reuses the Menu tab's renderer so the
  // numbers are identical; fed by /api/sales/top_ordered?sort=cogs with covers).
  _renderTop60CostHead(costHead, { body:'rpt4Body', foot:'rpt4Foot', momNote:'rpt4MomNote', note:'rpt4Note' });
  // costAnalysis food items (with menu-engineering quadrant) still power the §10
  // Action Items below — keep them available.
  const items = costAnalysis.items || [];

  // ── §5 Customer Behavior
  const o = persona.overall;
  document.getElementById('rptPersona').innerHTML = [
    { label:'Avg Party Size', value: (o.avg_party_size||0).toFixed(1)+' pax' },
    { label:'Avg Spend / Head', value: fmtN(o.avg_per_head||0) },
    { label:'ยอดบิลเฉลี่ย', value: fmtN(o.avg_ticket||0) },
    { label:'บิล', value: fmtN(o.tx_count||0) },
  ].map(k =>
    `<div class="text-center p-3 bg-slate-50 rounded-lg">
      <p class="text-xs text-slate-500 uppercase tracking-wide mb-1">${k.label}</p>
      <p class="text-xl font-bold text-slate-700">${k.value}</p>
    </div>`).join('');
  const fd = persona.food_drink_split || {};
  const fdTotal = (fd.food||0)+(fd.drink||0)+(fd.other||0);
  if (fdTotal > 0) {
    const fdPct = k => ((fd[k]||0)/fdTotal*100).toFixed(1);
    document.getElementById('rptPersonaNarrative').textContent = `Mix: ${fdPct('food')}% food, ${fdPct('drink')}% drink, ${fdPct('other')}% other.`;
  }

  // ── §5 rich — party-size distribution, spend/head consistency, sales structure
  (function renderPersonaRich() {
    const el = document.getElementById('rptPersonaRich'); if (!el) return;
    const ps = (persona.party_sizes || []).filter(p => (p.tx_count||0) > 0);
    if (!ps.length) { el.innerHTML = ''; return; }
    const totTx = ps.reduce((a,p)=>a+(p.tx_count||0),0) || (o.tx_count||1);
    const maxTx = Math.max(...ps.map(p=>p.tx_count||0), 1);
    const couples = ps.find(p=>p.size===2);
    const couplesPct = couples ? (couples.tx_count/totTx*100) : null;
    const phVals = ps.map(p=>p.avg_per_head||0).filter(Boolean);
    const phMin = phVals.length?Math.min(...phVals):0, phMax = phVals.length?Math.max(...phVals):0;
    const phSpread = phMax>0 ? ((phMax-phMin)/phMax*100) : 0;
    const bh = (persona.busy_hours||[]).filter(h=>(h.tx_count||0)>0);
    const peakH = bh.length ? bh.reduce((mx,h)=>h.tx_count>(mx?.tx_count||0)?h:mx,null) : null;
    const fdAbs = persona.food_drink_split || {};
    const fdTot = (fdAbs.food_abs||0)+(fdAbs.drink_abs||0)+(fdAbs.other_abs||0);
    const fdSeg = (lbl,val,color)=>{ const p = fdTot? val/fdTot*100:0; return p<0.5?'':`<div style="width:${p}%;background:${color}" class="h-full flex items-center justify-center text-[10px] text-white font-semibold" title="${lbl} ${p.toFixed(1)}%">${p>=8?p.toFixed(0)+'%':''}</div>`; };
    const PS_COLORS = ['#6366f1','#0ea5e9','#10b981','#f59e0b','#ef4444','#a855f7','#14b8a6','#f97316'];
    const psSorted = [...ps].sort((a,b)=>(a.size||0)-(b.size||0));
    const rows = psSorted.map((p,i)=>{
      const sharePct = p.tx_count/totTx*100, w = p.tx_count/maxTx*100;
      const color = PS_COLORS[i % PS_COLORS.length];
      const headDelta = o.avg_per_head ? ((p.avg_per_head||0)-o.avg_per_head)/o.avg_per_head*100 : null;
      const headChip = headDelta==null ? '<span class="text-slate-300">—</span>'
        : `<span style="color:${headDelta>=0?'#059669':'#dc2626'}">${headDelta>=0?'▲':'▼'}${Math.abs(headDelta).toFixed(0)}%</span>`;
      return `<tr class="border-t border-slate-50 hover:bg-slate-50">
        <td class="py-1.5 pr-3 font-medium text-slate-700 whitespace-nowrap"><span class="inline-block w-2 h-2 rounded-full mr-1.5 align-middle" style="background:${color}"></span>${p.label} คน</td>
        <td class="py-1.5 pr-3" style="width:32%"><div class="bg-slate-100 rounded-full h-3"><div style="width:${w.toFixed(0)}%;background:${color};height:100%;border-radius:9999px"></div></div></td>
        <td class="py-1.5 pr-3 text-right tabular-nums">${fmtN(p.tx_count)}</td>
        <td class="py-1.5 pr-3 text-right tabular-nums font-semibold">${sharePct.toFixed(1)}%</td>
        <td class="py-1.5 pr-3 text-right tabular-nums text-slate-500">${fmtN(p.avg_bill||0)}</td>
        <td class="py-1.5 pr-3 text-right tabular-nums text-slate-500">${fmtN(p.avg_per_head||0)}</td>
        <td class="py-1.5 text-right tabular-nums text-[11px]">${headChip}</td>
      </tr>`;
    }).join('');
    el.innerHTML = `
      <div class="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
        ${[
          ['คู่/2 คน = กลุ่มหลัก', couplesPct!=null?couplesPct.toFixed(0)+'%':'—', 'ของบิลทั้งหมดเป็นโต๊ะ 2 คน', '#6366f1'],
          ['ยอด/หัวเกือบคงที่', phVals.length?`${fmtN(phMin)}–${fmtN(phMax)}`:'—', `ต่างแค่ ${phSpread.toFixed(0)}% ทุกขนาดกลุ่ม — บุฟเฟ่ต์คุมต่อหัวได้แม่น`, '#059669'],
          ['ชั่วโมงพีค', peakH?`${peakH.hour}:00 น.`:'—', peakH?`${fmtN(peakH.tx_count)} บิล/ชม.`:'', '#d97706'],
        ].map(([l,v,s,c])=>`<div class="p-3 rounded-lg border" style="border-color:${c}33;background:${c}0a">
          <p class="text-[11px] text-slate-500">${l}</p><p class="text-2xl font-extrabold" style="color:${c}">${v}</p>
          <p class="text-[11px] text-slate-400 mt-0.5">${s}</p></div>`).join('')}
      </div>
      <p class="text-xs font-semibold text-slate-600 mb-1">การกระจายขนาดกลุ่มลูกค้า — สัดส่วนบิล · ยอด/บิล · ยอด/หัว</p>
      <div class="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-4">
        <div class="lg:col-span-2 overflow-x-auto">
          <table class="text-xs w-full"><thead><tr class="text-left text-slate-400">
            <th class="pb-1 pr-3">กลุ่ม</th><th class="pb-1 pr-3">สัดส่วนบิล</th><th class="pb-1 pr-3 text-right">บิล</th>
            <th class="pb-1 pr-3 text-right">% บิล</th><th class="pb-1 pr-3 text-right">ยอด/บิล</th><th class="pb-1 pr-3 text-right">ยอด/หัว</th>
            <th class="pb-1 text-right">vs เฉลี่ย/หัว</th>
          </tr></thead><tbody>${rows}</tbody></table>
        </div>
        <div>
          <p class="text-[11px] text-slate-400 mb-1 text-center">สัดส่วนบิลตามขนาดกลุ่ม</p>
          <div style="position:relative;height:170px"><canvas id="rptPartyDonut"></canvas></div>
        </div>
      </div>
      <p class="text-xs font-semibold text-slate-600 mb-1">โครงสร้างยอดขาย</p>
      <div class="rounded-lg overflow-hidden border border-slate-200 flex" style="height:30px">
        ${fdSeg('บุฟเฟ่ต์ & อื่นๆ', fdAbs.other_abs||0, '#6366f1')}
        ${fdSeg('Food à la carte', fdAbs.food_abs||0, '#10b981')}
        ${fdSeg('Drink', fdAbs.drink_abs||0, '#f59e0b')}
      </div>
      <p class="text-[11px] text-slate-400 mt-1">🟦 บุฟเฟ่ต์&อื่นๆ ${fdTot?((fdAbs.other_abs||0)/fdTot*100).toFixed(1):'—'}% · 🟩 Food ${fdTot?((fdAbs.food_abs||0)/fdTot*100).toFixed(1):'—'}% · 🟧 Drink ${fdTot?((fdAbs.drink_abs||0)/fdTot*100).toFixed(1):'—'}%</p>`;
    if (typeof Chart !== 'undefined') {
      const donutCanvas = document.getElementById('rptPartyDonut');
      if (chartInstances.rptPartyDonut) { try { chartInstances.rptPartyDonut.destroy(); } catch(e){} }
      if (donutCanvas) {
        chartInstances.rptPartyDonut = new Chart(donutCanvas, {
          type: 'doughnut',
          data: {
            labels: psSorted.map(p => p.label + ' คน'),
            datasets: [{
              data: psSorted.map(p => p.tx_count||0),
              backgroundColor: psSorted.map((_,i) => PS_COLORS[i % PS_COLORS.length]),
              borderWidth: 2, borderColor: '#fff',
            }],
          },
          options: {
            responsive: true, maintainAspectRatio: false, cutout: '55%',
            plugins: {
              legend: { position: 'bottom', labels: { color:'#334155', font:{size:10}, boxWidth:10, padding:8 } },
              datalabels: { color:'#fff', font:{weight:'bold', size:10}, formatter: (v,ctx) => { const tot = ctx.chart.data.datasets[0].data.reduce((a,b)=>a+b,0); return tot ? (v/tot*100).toFixed(0)+'%' : ''; } },
              tooltip: { callbacks: { label: ctx => `${ctx.label}: ${fmtN(ctx.parsed)} บิล` } },
            },
          },
        });
        // report data loads async after switchTab's own resize sweep already ran,
        // so this chart can be born inside a not-yet-laid-out panel — nudge once.
        setTimeout(() => { try { chartInstances.rptPartyDonut.resize(); } catch(e){} }, 60);
      }
    }
  })();

  // ── §6 Time & Operations
  const openHours = timeHourly.filter(h => h.is_open !== false);
  const totalHourRev = openHours.reduce((a,h)=>a+(h.revenue||0),0);
  const peak = openHours.reduce((mx,h)=>h.revenue>(mx?.revenue||0)?h:mx,null);
  const quiet = openHours.filter(h=>h.tx_count>0).reduce((mn,h)=>h.revenue<(mn?.revenue||Infinity)?h:mn,null);
  document.getElementById('rptTimeKpis').innerHTML = [
    { label:'ชั่วโมงเปิดทำการ', value: openHours.length+'/24', sub:'configured' },
    { label:'Peak Hour', value: peak?`${peak.hour}:00`:'—', sub: peak?`${fmtN(peak.revenue)}`:'' },
    { label:'Quietest Hour', value: quiet?`${quiet.hour}:00`:'—', sub: quiet?`${fmtN(quiet.revenue)}`:'' },
    { label:'Tx per Open Hr', value: openHours.length?fmtN(Math.round(openHours.reduce((a,h)=>a+h.tx_count,0)/openHours.length)):'—', sub:'avg' },
  ].map(k =>
    `<div class="text-center p-3 bg-slate-50 rounded-lg">
      <p class="text-xs text-slate-500 uppercase tracking-wide mb-1">${k.label}</p>
      <p class="text-xl font-bold text-indigo-700">${k.value}</p>
      <p class="text-xs text-slate-400">${k.sub}</p>
    </div>`).join('');
  if (!peak) {
    document.getElementById('rptTimeNarrative').innerHTML = 'No transaction data in selected period.';
  } else {
    // Weekday vs weekend (avg/day)
    const _avgOf = ds => { const a = ds.map(d=>(timeDow||[]).find(r=>r.dow===d)).filter(Boolean); return a.length ? a.reduce((s,r)=>s+(r.avg_revenue||0),0)/a.length : 0; };
    const wkdayAvg = _avgOf([1,2,3,4,5]), wkendAvg = _avgOf([6,0]);
    const wkLift = wkdayAvg > 0 ? (wkendAvg/wkdayAvg-1)*100 : null;
    // Top-3 hour concentration
    const hSorted = [...openHours].sort((a,b)=>(b.revenue||0)-(a.revenue||0));
    const top3Share = totalHourRev ? hSorted.slice(0,3).reduce((a,h)=>a+(h.revenue||0),0)/totalHourRev*100 : 0;
    // Dayparts (within open range)
    const dpDefs = [
      { label:'เช้า–เที่ยง', lo:6,  hi:14 },
      { label:'บ่าย',        lo:14, hi:17 },
      { label:'เย็น',        lo:17, hi:20 },
      { label:'ค่ำ',         lo:20, hi:24 },
    ];
    const dpRows = dpDefs.map(dp => {
      const hs = openHours.filter(h => h.hour >= dp.lo && h.hour < dp.hi);
      const rev = hs.reduce((a,h)=>a+(h.revenue||0),0);
      const tx  = hs.reduce((a,h)=>a+(h.tx_count||0),0);
      return { ...dp, rev, tx, share: totalHourRev ? rev/totalHourRev*100 : 0 };
    }).filter(d => d.rev > 0).sort((a,b)=>b.rev-a.rev);
    document.getElementById('rptTimeNarrative').innerHTML = `
      <p class="mb-3">ชั่วโมงพีค <b>${peak.hour}:00</b> ทำ <b>${(peak.revenue/totalHourRev*100).toFixed(1)}%</b> ของรายได้ในวัน · <b>3 ชั่วโมงแรก</b>รวมกัน <b>${top3Share.toFixed(1)}%</b> (ความกระจุกตัว)</p>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <p class="text-xs font-semibold text-slate-600 mb-2">วันธรรมดา vs สุดสัปดาห์ (เฉลี่ย/วัน)</p>
          <div class="flex gap-3">
            <div class="flex-1 p-3 rounded-lg bg-slate-50 text-center"><p class="text-xs text-slate-500">จ–ศ</p><p class="text-lg font-bold text-slate-700">${fmtN(wkdayAvg)}</p></div>
            <div class="flex-1 p-3 rounded-lg bg-cyan-50 text-center"><p class="text-xs text-slate-500">ส–อา</p><p class="text-lg font-bold text-cyan-700">${fmtN(wkendAvg)}</p><p class="text-[11px]">${wkLift!=null?momChip(wkLift)+' vs วันธรรมดา':''}</p></div>
          </div>
        </div>
        <div>
          <p class="text-xs font-semibold text-slate-600 mb-2">สัดส่วนรายได้ตามช่วงเวลา (Daypart)</p>
          <table class="text-xs w-full">
            <tbody>${dpRows.map(d=>`<tr class="border-t border-slate-50">
              <td class="py-1 font-medium">${d.label}</td>
              <td class="py-1"><div class="bg-slate-100 rounded-full h-2"><div style="width:${d.share.toFixed(0)}%;background:#6366f1;height:100%;border-radius:9999px"></div></div></td>
              <td class="py-1 text-right text-slate-500 w-12">${d.share.toFixed(0)}%</td>
              <td class="py-1 text-right text-slate-400 w-16">${fmtN(d.tx)} บิล</td>
            </tr>`).join('')}</tbody>
          </table>
        </div>
      </div>
      <p class="text-[11px] text-slate-400 mt-2">ตั้งค่าชั่วโมงเปิดทำการที่ Settings → ชั่วโมงเปิดทำการ เพื่อความแม่นยำ</p>`;
  }

  // ── §7 รายได้ตามวันและเวลา (share% = avg/day ÷ Σ avg/day — consistent units)
  const openHrsRpt = (timeHourly || []).filter(h => h.is_open !== false);
  const hrAvg = h => h.avg_daily_revenue ?? h.revenue ?? 0;
  const totalHrAvg = openHrsRpt.reduce((a,h)=>a+hrAvg(h),0) || 1;
  const peakRpt = openHrsRpt.length ? openHrsRpt.reduce((mx,h)=>hrAvg(h)>hrAvg(mx)?h:mx, openHrsRpt[0]) : null;
  const DOW_LABELS_RPT = ['อา','จ','อ','พ','พฤ','ศ','ส'];
  const dowOrder = [1,2,3,4,5,6,0];
  const dowSorted = dowOrder.map(d => (timeDow||[]).find(r=>r.dow===d) || {dow:d,revenue:0,avg_revenue:0,day_count:0});
  const peakDow = dowSorted.length ? dowSorted.reduce((mx,d)=>(d.avg_revenue||0)>(mx.avg_revenue||0)?d:mx, dowSorted[0]) : null;
  const dowTotal = dowSorted.reduce((a,d)=>a+(d.avg_revenue||0),0) || 1;
  const hrsByRev = [...openHrsRpt].sort((a,b)=>hrAvg(b)-hrAvg(a));
  let _hrCum = 0;
  document.getElementById('rptDayTimeBlock').innerHTML = `
    <div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
      ${peakRpt ? `<div class="p-3 rounded-lg bg-indigo-50 text-center"><p class="text-xs text-slate-500">Peak Hour</p><p class="text-2xl font-bold text-indigo-700">${peakRpt.hour}:00</p><p class="text-xs text-slate-400">${fmtN(hrAvg(peakRpt))}/วัน · ${(hrAvg(peakRpt)/totalHrAvg*100).toFixed(1)}% ของวัน</p></div>` : ''}
      ${peakDow ? `<div class="p-3 rounded-lg bg-cyan-50 text-center"><p class="text-xs text-slate-500">Peak Day</p><p class="text-2xl font-bold text-cyan-700">${DOW_LABELS_RPT[peakDow.dow]||'—'}</p><p class="text-xs text-slate-400">${fmtN(peakDow.avg_revenue||0)}/วัน · ${((peakDow.avg_revenue||0)/dowTotal*100).toFixed(1)}% ของสัปดาห์</p></div>` : ''}
      <div class="p-3 rounded-lg bg-emerald-50 text-center"><p class="text-xs text-slate-500">Open Hours</p><p class="text-2xl font-bold text-emerald-700">${openHrsRpt.length}</p><p class="text-xs text-slate-400">ชั่วโมงต่อวัน</p></div>
      <div class="p-3 rounded-lg bg-amber-50 text-center"><p class="text-xs text-slate-500">Revenue/Open Hr</p><p class="text-xl font-bold text-amber-700">${openHrsRpt.length?fmtN(Math.round(totalHrAvg/openHrsRpt.length)):'—'}</p><p class="text-xs text-slate-400">avg/day across hours</p></div>
    </div>
    <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
      <div>
        <p class="text-xs font-semibold text-slate-600 mb-2">Revenue by Hour (avg/day · เรียงมาก→น้อย)</p>
        <table class="text-xs w-full">
          <thead><tr class="text-slate-400 border-b border-slate-100"><th class="py-1 text-left">ชั่วโมง</th><th class="py-1 text-right">Avg/วัน</th><th class="py-1 text-right">Share</th><th class="py-1 text-right">สะสม</th></tr></thead>
          <tbody>${hrsByRev.map(h=>{ const sh = hrAvg(h)/totalHrAvg*100; _hrCum += sh; return `
            <tr class="border-t border-slate-50">
              <td class="py-1 font-mono">${h.hour}:00</td>
              <td class="py-1 text-right font-medium">${fmtN(hrAvg(h))}</td>
              <td class="py-1 text-right text-slate-500">${sh.toFixed(1)}%</td>
              <td class="py-1 text-right text-slate-400">${_hrCum.toFixed(1)}%</td>
            </tr>`; }).join('')}</tbody>
        </table>
      </div>
      <div>
        <p class="text-xs font-semibold text-slate-600 mb-2">Revenue by Day of Week (avg/day)</p>
        <div style="position:relative;height:140px" class="mb-3"><canvas id="rptDowChart"></canvas></div>
        <table class="text-xs w-full">
          <thead><tr class="text-slate-400 border-b border-slate-100"><th class="py-1 text-left">วัน</th><th class="py-1 text-right">Avg/วัน</th><th class="py-1 text-right">Share</th><th class="py-1 text-right">vs เฉลี่ยสัปดาห์</th></tr></thead>
          <tbody>${[...dowSorted].sort((a,b)=>(b.avg_revenue||0)-(a.avg_revenue||0)).map(d=>{
            const avgOfWk = dowTotal/7;
            const dd = avgOfWk ? ((d.avg_revenue||0)-avgOfWk)/avgOfWk*100 : 0;
            return `
            <tr class="border-t border-slate-50 ${d.dow===peakDow?.dow?'bg-cyan-50':''}">
              <td class="py-1 font-medium">${d.dow===peakDow?.dow?'🔥 ':''}${DOW_LABELS_RPT[d.dow]||'—'}</td>
              <td class="py-1 text-right font-medium">${fmtN(d.avg_revenue||0)}</td>
              <td class="py-1 text-right text-slate-500">${((d.avg_revenue||0)/dowTotal*100).toFixed(1)}%</td>
              <td class="py-1 text-right" style="color:${dd>=0?'#059669':'#dc2626'}">${dd>=0?'▲':'▼'}${Math.abs(dd).toFixed(0)}%</td>
            </tr>`; }).join('')}</tbody>
        </table>
      </div>
    </div>`;
  if (typeof Chart !== 'undefined') {
    const dowCanvas = document.getElementById('rptDowChart');
    if (chartInstances.rptDowChart) { try { chartInstances.rptDowChart.destroy(); } catch(e){} }
    if (dowCanvas) {
      chartInstances.rptDowChart = new Chart(dowCanvas, {
        type: 'bar',
        data: {
          labels: dowSorted.map(d => DOW_LABELS_RPT[d.dow] || '—'),
          datasets: [{
            data: dowSorted.map(d => d.avg_revenue || 0),
            backgroundColor: dowSorted.map(d => d.dow === peakDow?.dow ? '#0891b2' : '#c7d2fe'),
            borderRadius: 4,
          }],
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            datalabels: { display: false },
            tooltip: { callbacks: { label: ctx => fmtN(ctx.parsed.y) + '/วัน' } },
          },
          scales: {
            x: { ticks: { color:'#64748b', font:{size:11} }, grid: { display:false } },
            y: { ticks: { color:'#94a3b8', font:{size:10}, callback: v => fmtN(v) }, grid: { color:'#f1f5f9' } },
          },
        },
      });
      setTimeout(() => { try { chartInstances.rptDowChart.resize(); } catch(e){} }, 60);
    }
  }

  // ── §8 Cost Contribution — latest month, per-branch selectable, real MoM Δ
  _rptLastMonth = mLast.period_month || getMonthTo() || getMonthFrom() || '';
  // populate branch selector once (preserve current selection)
  const csel = document.getElementById('rptCostBranch');
  if (csel) {
    const want = getBranch() || '';
    const opts = ['<option value="">ทุกสาขา</option>']
      .concat([...branches].sort((a,b)=>(b.revenue||0)-(a.revenue||0)).map(b=>`<option value="${esc(b.branch)}">${esc(b.branch)}</option>`));
    csel.innerHTML = opts.join('');
    csel.value = want;
  }
  await renderReportCost(getBranch() || '');
  renderReportTier(_rptLastMonth);   // §9 tier block — async, non-blocking

  // ── §9 Pricing & Discounts
  const discOverall = (discounts && discounts.overall) ? discounts.overall : {};
  const discByBranch = (discounts && Array.isArray(discounts.by_branch)) ? discounts.by_branch : [];
  const totalDisc = discOverall.total_discount || 0;
  document.getElementById('rptDiscountSummary').innerHTML = totalDisc > 0
    ? `Discounts: <b>${fmtN(totalDisc)}</b> across <b>${fmtN(discOverall.discount_tx||0)}</b> of <b>${fmtN(discOverall.total_tx||0)}</b> transactions (avg ${fmtN(discOverall.avg_discount||0)} each).`
    : 'No discount data.';
  const discSorted = [...discByBranch].sort((a,b)=>(b.rate||0)-(a.rate||0));
  document.getElementById('rptDiscountBody').innerHTML = discSorted.slice(0,15).map(d =>
    `<tr class="border-t border-slate-100">
      <td class="py-2 pr-4">${esc(d.branch)}</td>
      <td class="py-2 pr-4 text-right">${fmtN(d.discount_tx||0)} / ${fmtN(d.total_tx||0)}</td>
      <td class="py-2 pr-4 text-right text-red-500">${fmtN(d.total_discount||0)}</td>
      <td class="py-2 text-right">${(d.rate||0).toFixed(1)}%</td>
    </tr>`).join('');

  // Per-branch discount composition (nature) + MoM (current period vs prior month)
  try {
    const hasPrior = priorQpStr !== qpStr;   // distinct prior month only when a month/range is set
    const [compCur, compPrev] = await Promise.all([
      fetch(`${API}/api/analysis/discount_composition${qpStr}`).then(r=>r.json()).catch(()=>({branches:[]})),
      hasPrior ? fetch(`${API}/api/analysis/discount_composition${priorQpStr}`).then(r=>r.json()).catch(()=>({branches:[]})) : Promise.resolve({branches:[]}),
    ]);
    const BK = [
      { k:'free',       label:'ฟรี/100%+', color:'#7f1d1d' },
      { k:'ge50',       label:'50%+',       color:'#dc2626' },
      { k:'p20_50',     label:'20–50%',     color:'#f59e0b' },
      { k:'p10_20',     label:'10–20%',     color:'#facc15' },
      { k:'lt10',       label:'<10%',       color:'#84cc16' },
      { k:'zero_gross', label:'ไม่มียอดบิล', color:'#6b7280' },
    ];
    const prevMap = {}; (compPrev.branches||[]).forEach(b=>prevMap[b.branch]=b);
    const rows = (compCur.branches||[]).slice(0,15);
    const el = document.getElementById('rptDiscountComposition');
    if (!rows.length) { el.innerHTML = '<p class="text-slate-400 text-xs py-2">ไม่มีข้อมูลส่วนลด</p>'; }
    else el.innerHTML = `<table class="w-full text-xs">
      <thead><tr class="text-left text-slate-500 border-b border-slate-200">
        <th class="py-2 pr-3">สาขา</th><th class="py-2 pr-3 text-right">ส่วนลดรวม</th>
        <th class="py-2 pr-3 text-right">vs เดือนก่อน</th>
        <th class="py-2 pr-3">องค์ประกอบ (ตาม % ของบิล)</th>
        <th class="py-2 pr-3">เด่น</th></tr></thead>
      <tbody>${rows.map(b => {
        const tot = b.total_discount || 0;
        const prev = prevMap[b.branch];
        const mom = (hasPrior && prev && prev.total_discount>0) ? ((tot-prev.total_discount)/prev.total_discount*100) : null;
        const seg = BK.map(bk => { const v = (b.buckets?.[bk.k]||0); const w = tot? v/tot*100 : 0; return w>0?`<div title="${bk.label}: ${fmtN(v)} (${w.toFixed(0)}%)" style="width:${w}%;background:${bk.color}"></div>`:''; }).join('');
        const dom = BK.find(bk=>bk.k===b.dominant);
        return `<tr class="border-b border-slate-50">
          <td class="py-1.5 pr-3 font-medium">${esc(b.branch)}</td>
          <td class="py-1.5 pr-3 text-right text-red-500">${fmtN(tot)}</td>
          <td class="py-1.5 pr-3 text-right">${mom==null?'<span class="text-slate-300">—</span>':momChip(mom)}</td>
          <td class="py-1.5 pr-3"><div class="flex h-3 rounded overflow-hidden" style="min-width:120px">${seg}</div></td>
          <td class="py-1.5 pr-3">${dom?`<span style="color:${dom.color};font-weight:600">${dom.label}</span>`:'—'}</td>
        </tr>`;
      }).join('')}</tbody></table>
      <div class="flex flex-wrap gap-3 mt-2 text-[11px] text-slate-500">${BK.map(bk=>`<span class="flex items-center gap-1"><span style="width:10px;height:10px;background:${bk.color};border-radius:2px;display:inline-block"></span>${bk.label}</span>`).join('')}</div>`;
  } catch(e) { console.error('discount composition failed', e); }

  // ── §10 Next-month forecast — projects the month AFTER the latest complete
  //    month so it can be tracked: at month-end, drop actuals next to it.
  (function renderNextMonth() {
    const el = document.getElementById('rptNextMonth'); if (!el) return;
    const series = (trendFull || []).map(r => r.revenue || 0);
    if (series.length < 3 || !_lastMo) { el.innerHTML = ''; return; }
    const ols = ys => {
      const n = ys.length, xs = ys.map((_, i) => i);
      const mx = xs.reduce((a,b)=>a+b,0)/n, my = ys.reduce((a,b)=>a+b,0)/n;
      let num=0, den=0; for (let i=0;i<n;i++){ num+=(xs[i]-mx)*(ys[i]-my); den+=(xs[i]-mx)**2; }
      const slope = den?num/den:0, inter = my-slope*mx;
      const sd = Math.sqrt(ys.reduce((a,y,i)=>a+(y-(inter+slope*i))**2,0)/n);
      return { sd, pred: inter + slope*n };
    };
    const f = ols(series);
    const pred = Math.max(0, f.pred);
    const lo = Math.max(0, pred - 1.28*f.sd), hi = pred + 1.28*f.sd;  // ~80% band
    const [yy, mm] = _lastMo.split('-').map(Number);
    const nextMo = mm === 12 ? `${yy+1}-01` : `${yy}-${String(mm+1).padStart(2,'0')}`;
    const lastRev = series[series.length-1];
    const momProj = lastRev > 0 ? (pred-lastRev)/lastRev*100 : null;
    const branchProj = Object.keys(_bm).map(br => {
      const ys = _allMonthsB.map(m => revOf(br, m)).filter(v => v > 0);
      const p = ys.length >= 3 ? Math.max(0, ols(ys).pred) : (ys.length ? ys[ys.length-1] : 0);
      return { branch: br, last: revOf(br, _lastMo), proj: p };
    }).filter(b => b.proj > 0).sort((a,b)=>b.proj-a.proj);
    const sumProj = branchProj.reduce((a,b)=>a+b.proj,0);
    const chip = p => p==null ? '' : `<span style="color:${p>=0?'#059669':'#dc2626'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}%</span>`;
    el.innerHTML = `
      <div class="rounded-xl border-2 p-4 mb-3" style="border-color:#4f46e533;background:linear-gradient(135deg,#eef2ff 0%,#ffffff 70%)">
        <div class="flex items-center justify-between flex-wrap gap-2 mb-2">
          <h3 class="text-sm font-bold text-indigo-900">🔮 พยากรณ์เดือนถัดไป — ${fmtMonth(nextMo)}</h3>
          <span class="text-[11px] text-slate-500">linear trend จาก ${series.length} เดือน · สิ้นเดือนนำ actual มาเทียบช่องนี้เพื่อติดตาม</span>
        </div>
        <div class="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div class="p-3 rounded-lg bg-white border border-slate-100"><p class="text-[11px] text-slate-500">คาดการณ์รายได้</p><p class="text-2xl font-extrabold text-indigo-700">${fmt(pred)}</p><p class="text-[11px] text-slate-400">${fmtN(Math.round(pred))} บาท</p></div>
          <div class="p-3 rounded-lg bg-white border border-slate-100"><p class="text-[11px] text-slate-500">ช่วงเชื่อมั่น ~80%</p><p class="text-sm font-bold text-slate-700">${fmt(lo)} – ${fmt(hi)}</p><p class="text-[11px] text-slate-400">low – high</p></div>
          <div class="p-3 rounded-lg bg-white border border-slate-100"><p class="text-[11px] text-slate-500">vs ${fmtMonth(_lastMo)} (ล่าสุด)</p><p class="text-lg font-bold">${chip(momProj)}</p><p class="text-[11px] text-slate-400">${fmt(lastRev)} → ${fmt(pred)}</p></div>
          <div class="p-3 rounded-lg bg-white border border-slate-100"><p class="text-[11px] text-slate-500">รวมจากรายสาขา</p><p class="text-lg font-bold text-slate-700">${fmt(sumProj)}</p><p class="text-[11px] text-slate-400">${branchProj.length} สาขา</p></div>
        </div>
      </div>
      <details class="mb-1"><summary class="text-xs font-semibold text-slate-600 cursor-pointer">พยากรณ์รายสาขา — ${fmtMonth(nextMo)} (กดเพื่อดู)</summary>
        <div class="overflow-x-auto mt-2"><table class="w-full text-xs">
          <thead><tr class="text-left text-slate-400 border-b border-slate-200"><th class="py-1 pr-3">สาขา</th><th class="py-1 pr-3 text-right">${fmtMonth(_lastMo)} (ล่าสุด)</th><th class="py-1 pr-3 text-right">คาด ${fmtMonth(nextMo)}</th><th class="py-1 text-right">Δ</th></tr></thead>
          <tbody>${branchProj.map(b=>{const d=b.last>0?(b.proj-b.last)/b.last*100:null;return `<tr class="border-b border-slate-50"><td class="py-1 pr-3 font-medium">${esc(b.branch)}</td><td class="py-1 pr-3 text-right text-slate-500">${fmtN(b.last)}</td><td class="py-1 pr-3 text-right font-semibold">${fmtN(Math.round(b.proj))}</td><td class="py-1 text-right">${chip(d)}</td></tr>`;}).join('')}</tbody>
        </table></div>
      </details>`;
  })();

  // ── §10 Forecasts & Action Items
  const fcEl = document.getElementById('rptForecast');
  if (forecast && forecast.available) {
    fcEl.innerHTML = `คาดการณ์รายได้ <b>${fmtMonth(forecast.period)}</b> (ทุกสาขา): <b>${fmtN(forecast.projected)}</b> บาท
      · ช่วงความเชื่อมั่น ${fmtN(forecast.lo)} – ${fmtN(forecast.hi)}
      · อ้างอิงข้อมูล ${forecast.days_elapsed}/${forecast.days_total} วัน (MTD ${fmtN(forecast.mtd)} บาท · เฉลี่ย ${fmtN(forecast.avg_daily)}/วัน).`;
  } else { fcEl.textContent = 'Forecast not available for the selected scope.'; }

  // ── Forecast scorecard (projected / MoM / YoY / target) + scenario
  const scEl   = document.getElementById('rptForecastScorecard');
  const scenEl = document.getElementById('rptScenario');
  if (forecast && forecast.available) {
    const proj   = forecast.projected;
    const momPct = (forecastBranches && forecastBranches.total) ? forecastBranches.total.mom_pct : null;
    const yoyPct = (latestYoy && latestYoy.yoy_pct != null) ? latestYoy.yoy_pct : null;
    const prior  = (forecastBranches && forecastBranches.total) ? forecastBranches.total.prior_actual : null;
    // Target attainment (respects branch filter; empty-state when no target set)
    let targetTotal = 0;
    try {
      const tg = await fetch(`${API}/api/targets?month=${forecast.period}`).then(r => r.json()).catch(() => []);
      const bsel = getBranch();
      targetTotal = (Array.isArray(tg) ? tg : [])
        .filter(t => !bsel || t.branch === bsel)
        .reduce((a, t) => a + (t.revenue_target || 0), 0);
    } catch (e) {}
    const attainPct = targetTotal > 0 ? (proj / targetTotal * 100) : null;
    const pctChip = p => p == null ? '<span class="text-slate-300">—</span>'
      : `<span style="color:${p>=0?'#059669':'#dc2626'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}%</span>`;
    const card = (label, valHtml, sub, color, onclick) => `<div class="p-3 rounded-lg bg-slate-50 ${onclick?'cursor-pointer hover:bg-slate-100':''}" ${onclick?`onclick="${onclick}"`:''}>
      <p class="text-xs text-slate-500 mb-0.5">${label}</p>
      <p class="text-lg font-bold" style="color:${color||'#1e293b'}">${valHtml}</p>
      <p class="text-[11px] text-slate-400">${sub}</p></div>`;
    scEl.innerHTML =
      card('คาดสิ้นเดือน', fmtN(proj), 'run-rate projection', '#4f46e5') +
      card('vs เดือนก่อน (MoM)', pctChip(momPct), 'projected vs last month', '#1e293b') +
      card('vs ปีก่อน (YoY)', yoyPct==null?'—':(yoyPct>=0?'+':'')+yoyPct.toFixed(1)+'%',
           latestYoy?`${latestYoy.period_month} vs ${latestYoy.ly_period}`:'ไม่มีข้อมูล',
           yoyPct==null?'#94a3b8':yoyPct>=0?'#059669':'#dc2626') +
      (attainPct!=null
        ? card('เทียบเป้า', attainPct.toFixed(0)+'%', `เป้า ${fmtN(targetTotal)}`, attainPct>=100?'#059669':attainPct>=90?'#d97706':'#dc2626')
        : card('เทียบเป้า', 'ตั้งเป้า →', 'ยังไม่ได้ตั้งเป้าเดือนนี้', '#6366f1', "switchTab('settings')"));
    // Scenario best / base / worst from the confidence band
    const vsPrior = v => prior ? `${v>=prior?'+':''}${((v-prior)/prior*100).toFixed(1)}% vs เดือนก่อน` : '';
    const scLo = forecast.lo, scHi = forecast.hi, scBase = forecast.projected;
    const scRange = (scHi - scLo) || 1;
    const scBasePct = Math.min(100, Math.max(0, (scBase - scLo) / scRange * 100));
    const scPriorPct = (prior != null && prior >= scLo && prior <= scHi) ? (prior - scLo) / scRange * 100 : null;
    scenEl.innerHTML = `<h3 class="text-sm font-bold text-slate-600 mb-2">สถานการณ์จำลอง (Scenario)</h3>
      <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
        ${[
          ['🟢 ดีสุด (Best)',  forecast.hi,        '#059669', 'วันหยุด/โปรช่วยดันยอด · +1SD'],
          ['🔵 ฐาน (Base)',    forecast.projected, '#4f46e5', 'คงอัตราปัจจุบัน (run-rate)'],
          ['🔴 แย่สุด (Worst)', forecast.lo,        '#dc2626', 'สาขาขาช้า/สภาพอากาศ · −1SD'],
        ].map(([t,v,c,assume]) => `<div class="p-4 rounded-xl border" style="border-color:${c}33;background:${c}0a">
          <p class="text-xs font-semibold mb-1" style="color:${c}">${t}</p>
          <p class="text-xl font-bold text-slate-800">${fmtN(v)}</p>
          <p class="text-[11px] text-slate-500 mt-0.5">${vsPrior(v)}</p>
          <p class="text-[11px] text-slate-400 mt-1">${assume}</p></div>`).join('')}
      </div>
      <div class="mt-4 px-1">
        <p class="text-[11px] text-slate-400 mb-2">ตำแหน่งของคาดการณ์ฐาน (Base) ภายในช่วงความเชื่อมั่น</p>
        <div class="relative h-2.5 rounded-full" style="background:linear-gradient(90deg,#dc262633,#4f46e533,#05966933)">
          ${scPriorPct != null ? `<div class="absolute top-1/2 -translate-y-1/2 w-0.5 h-5 bg-slate-500" style="left:${scPriorPct.toFixed(1)}%" title="เดือนก่อน ${fmtN(prior)}"></div>` : ''}
          <div class="absolute top-1/2 -translate-y-1/2 w-3.5 h-3.5 rounded-full border-2 border-white shadow" style="left:calc(${scBasePct.toFixed(1)}% - 7px);background:#4f46e5" title="ฐาน ${fmtN(scBase)}"></div>
        </div>
        <div class="flex justify-between text-[10px] text-slate-400 mt-1">
          <span>🔴 แย่สุด ${fmtN(scLo)}</span>
          ${scPriorPct != null ? `<span>| เดือนก่อน ${fmtN(prior)}</span>` : ''}
          <span>🟢 ดีสุด ${fmtN(scHi)}</span>
        </div>
      </div>`;
  } else { scEl.innerHTML = ''; scenEl.innerHTML = ''; }

  // Per-branch month-end projection table
  const fbWrap = document.getElementById('rptForecastBranchWrap');
  const momCell = pct => pct == null
    ? '<span class="text-slate-300">—</span>'
    : `<span style="color:${pct>=0?'#059669':'#dc2626'}">${pct>=0?'▲':'▼'} ${Math.abs(pct).toFixed(1)}%</span>`;
  if (forecastBranches && forecastBranches.available && (forecastBranches.branches||[]).length) {
    // A branch whose prior month is <5% of its projection barely operated last
    // month (newly opened) — its MoM% would be a meaningless 5-digit number.
    const momBranchCell = b => (b.prior_actual != null && b.prior_actual < b.projected * 0.05)
      ? '<span style="color:#0891b2">🆕 ใหม่</span>'
      : momCell(b.mom_pct);
    document.getElementById('rptForecastBranchBody').innerHTML = forecastBranches.branches.map(b =>
      `<tr class="border-b border-slate-100">
        <td class="py-1.5 pr-4 font-medium text-slate-800">${esc(b.branch)}</td>
        <td class="py-1.5 pr-4 text-right text-slate-500">${fmtN(b.mtd)}</td>
        <td class="py-1.5 pr-4 text-right font-semibold">${fmtN(b.projected)}</td>
        <td class="py-1.5 pr-4 text-right text-slate-500">${b.prior_actual!=null?fmtN(b.prior_actual):'—'}</td>
        <td class="py-1.5 text-right">${momBranchCell(b)}</td>
      </tr>`).join('');
    const t = forecastBranches.total || {};
    document.getElementById('rptForecastBranchFoot').innerHTML =
      `<tr class="border-t-2 border-slate-300 font-bold text-slate-800">
        <td class="py-2 pr-4">รวมทุกสาขา</td>
        <td class="py-2 pr-4 text-right">${fmtN(t.mtd||0)}</td>
        <td class="py-2 pr-4 text-right">${fmtN(t.projected||0)}</td>
        <td class="py-2 pr-4 text-right">${t.prior_actual!=null?fmtN(t.prior_actual):'—'}</td>
        <td class="py-2 text-right">${momCell(t.mom_pct)}</td>
      </tr>`;
    // Inactive-branch note (explains the 26-vs-27 gap honestly)
    const noteEl = document.getElementById('rptInactiveNote');
    const inact = forecastBranches.inactive_branches || [];
    if (noteEl) {
      noteEl.innerHTML = `แสดง <b>${forecastBranches.active_branches}</b> สาขาที่มียอดในเดือน ${fmtMonth(forecastBranches.period)}`
        + (forecastBranches.total_branches ? ` จากทั้งหมด <b>${forecastBranches.total_branches}</b> สาขา` : '')
        + (inact.length ? ` · ⚠️ ไม่มียอด: ${inact.map(b=>`${esc(b.branch)} (ล่าสุด ${b.last_sale||'—'})`).join(', ')}` : '');
    }
    fbWrap.classList.remove('hidden');
  } else { fbWrap.classList.add('hidden'); }

  document.getElementById('rptAnomalies').innerHTML = anomalies.length
    ? anomalies.slice(0,8).map(a => `<li>${a.kind || a.type || 'Anomaly'} on <b>${a.date || a.period || ''}</b> at <b>${a.branch || 'multiple branches'}</b>${a.note?' — '+a.note:''}${a.z_score?' (z='+a.z_score.toFixed(1)+')':''}</li>`).join('')
    : '<li class="italic text-slate-400">No anomalies detected.</li>';

  // ── Action items — prioritized, specific, ฿-quantified, owner-tagged
  const actions = [];
  const pushA = (pri, owner, text, impact) => actions.push({ pri, owner, text, impact });
  const topItems = (q, n=3) => items.filter(r => r.quadrant === q).sort((a,b)=>(b.revenue||0)-(a.revenue||0)).slice(0,n);
  const topNames = (q, n=3) => topItems(q, n).map(r => esc(r.description || r.sku_code));
  const sumRev   = q => items.filter(r => r.quadrant === q).reduce((a,r)=>a+(r.revenue||0),0);

  const plowItems = items.filter(r => r.quadrant === 'plowhorse');
  if (plowItems.length) pushA('high', 'ราคา/ต้นทุน',
    `<b>${plowItems.length} Plowhorse SKU</b> (ขายดีแต่มาร์จิ้นต่ำ) เช่น ${topNames('plowhorse').join(', ')} — ขึ้นราคาเล็กน้อยหรือลดต้นทุนต่อจาน ให้ผลกับกำไรเร็วสุดเพราะปริมาณสูง.`,
    `ฐานรายได้กระทบ ~${fmtN(sumRev('plowhorse'))} บาท`);

  const dogItems = items.filter(r => r.quadrant === 'dog');
  if (dogItems.length) pushA('med', 'เมนู',
    `<b>${dogItems.length} Dog SKU</b> (ขายน้อย-มาร์จิ้นต่ำ) เช่น ${topNames('dog').join(', ')} — พิจารณาถอด/ปรับราคา/รวมเมนู.`,
    `รายได้รวมเพียง ${fmtN(sumRev('dog'))} บาท`);

  const puzzleItems = items.filter(r => r.quadrant === 'puzzle');
  if (puzzleItems.length) pushA('med', 'เมนู/การตลาด',
    `<b>${puzzleItems.length} Puzzle SKU</b> (มาร์จิ้นสูงแต่ขายน้อย) เช่น ${topNames('puzzle').join(', ')} — ดันยอดผ่านโปรโมท/จัดวางเมนู/ให้พนักงานเชียร์.`,
    `อัปไซด์กำไร ถ้าดันยอดได้`);

  if (cs.uncosted_skus > 0) pushA('high', 'ต้นทุน/ข้อมูล',
    `<b>${cs.uncosted_skus} SKU ยังไม่มีต้นทุน</b> (จาก ${cs.total_skus||0}) — กำไร/มาร์จิ้นยังไม่ครบ. อัปโหลดที่ Settings → Cost Management.`,
    `บล็อกความแม่นยำของ §4, §8`);

  const discList = (discounts && Array.isArray(discounts.by_branch)) ? [...discounts.by_branch].sort((a,b)=>(b.rate||0)-(a.rate||0)) : [];
  const worstDisc = discList[0];
  if (worstDisc && (worstDisc.rate||0) > 10) pushA('high', 'สาขา/การเงิน',
    `ส่วนลดสูงสุดที่สาขา <b>${esc(worstDisc.branch)}</b> ${(worstDisc.rate||0).toFixed(1)}% — ตรวจการกดส่วนลด (ดูบิลที่ §9).`,
    `ส่วนลด ${fmtN(worstDisc.total_discount||0)} บาท`);
  else if ((discOverall.discount_tx || 0) / (discOverall.total_tx || 1) > 0.10) pushA('med', 'การเงิน',
    `อัตราการให้ส่วนลดรวมเกิน 10% — ตรวจสอบประสิทธิภาพโปรโมชั่น.`,
    `ส่วนลดรวม ${fmtN(discOverall.total_discount||0)} บาท`);

  if (latestYoy && latestYoy.yoy_pct != null && latestYoy.yoy_pct < 0) pushA('high', 'ผู้บริหาร',
    `รายได้ลดลง YoY <b>${latestYoy.yoy_pct.toFixed(1)}%</b> (${latestYoy.period_month} เทียบ ${latestYoy.ly_period}) — เจาะหาสาขา/เมนูที่ฉุดยอด.`,
    `แนวโน้มรายได้`);

  if (forecastBranches && forecastBranches.available) {
    const dropping = forecastBranches.branches.filter(b => b.mom_pct != null && b.mom_pct < -10);
    if (dropping.length) pushA('high', 'สาขา',
      `<b>${dropping.length} สาขา</b> คาดรายได้สิ้นเดือนต่ำกว่าเดือนก่อน >10%: ${dropping.slice(0,4).map(b=>esc(b.branch)+' ('+b.mom_pct.toFixed(0)+'%)').join(', ')}.`,
      `รวม ~${fmtN(dropping.reduce((a,b)=>a+((b.prior_actual||0)-(b.projected||0)),0))} บาทที่อาจหาย`);
  }

  if (cs.overall_margin_pct != null && cs.overall_margin_pct < 60) pushA('med', 'ต้นทุน',
    `Gross margin รวม ${cs.overall_margin_pct.toFixed(1)}% — ต่ำกว่าเกณฑ์ร้านอาหารทั่วไป (~65–70%). ทบทวนต้นทุนวัตถุดิบ/สูตร.`,
    `ทุก 1% margin = ${fmtN((totalRevTrend||0)*0.01)} บาท/ช่วง`);

  const PRI = { high:{o:0,b:'🔴',label:'เร่งด่วน',bg:'#fef2f2'}, med:{o:1,b:'🟡',label:'ควรทำ',bg:'#fffbeb'}, info:{o:2,b:'🟢',label:'ข้อมูล',bg:'#f0fdf4'} };
  actions.sort((a,b)=>PRI[a.pri].o - PRI[b.pri].o);
  document.getElementById('rptActions').innerHTML = actions.length
    ? actions.map(a => `<li class="flex gap-2 items-start rounded-lg px-3 py-2" style="background:${PRI[a.pri].bg}">
        <span class="mt-0.5">${PRI[a.pri].b}</span>
        <div class="flex-1">
          <div>${a.text}</div>
          <div class="flex items-center gap-2 mt-1 text-[11px]">
            <span class="px-1.5 py-0.5 rounded font-medium" style="background:#e0e7ff;color:#4338ca">👤 ${esc(a.owner)}</span>
            ${a.impact?`<span class="text-slate-500">💰 ${a.impact}</span>`:''}
          </div>
        </div></li>`).join('')
    : '<li class="italic text-slate-400">Operations look healthy — no urgent flags.</li>';
}


// ════════════════════════════════════════════════════════════════
// COST UPLOAD MODAL
// ════════════════════════════════════════════════════════════════
function openCostModal() {
  document.getElementById('costModal').classList.remove('hidden');
  document.getElementById('costModal').classList.add('flex');
  fetch(`${API}/api/cost`).then(r=>r.json()).then(data => {
    costModalSkuMap = {};
    data.forEach(s => { costModalSkuMap[s.sku_code] = s; });
  });
}
function closeCostModal() {
  document.getElementById('costModal').classList.add('hidden');
  document.getElementById('costModal').classList.remove('flex');
  document.getElementById('costPreview').classList.add('hidden');
  document.getElementById('previewBody').innerHTML = '';
  document.getElementById('saveBtn').disabled = true;
  document.getElementById('saveStatus').textContent = '';
  document.getElementById('costFile').value = '';
  parsedCostRows = [];
}
function onDrop(e) {
  e.preventDefault();
  document.getElementById('dropZone').classList.remove('border-indigo-400','bg-indigo-50');
  const file = e.dataTransfer.files[0];
  if (file) parseCsvFile(file);
}
function onCostFileChange(e) { if (e.target.files[0]) parseCsvFile(e.target.files[0]); }
function parseCsvFile(file) {
  const reader = new FileReader();
  reader.onload = e => renderCostPreview(e.target.result);
  reader.readAsText(file);
}
function renderCostPreview(text) {
  const lines = text.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);
  if (!lines.length) return;
  const hasHeader = lines[0].toLowerCase().includes('sku') || lines[0].toLowerCase().includes('code');
  const dataLines = hasHeader ? lines.slice(1) : lines;
  parsedCostRows = [];
  const unknowns = [];
  const rows = dataLines.map(line => {
    const parts = line.includes('\t') ? line.split('\t') : line.split(',');
    const sku_code = (parts[0]||'').trim();
    const costRaw = (parts[1]||'').trim().replace(/[,\s]/g,'');
    const unit_cost = parseFloat(costRaw);
    if (!sku_code) return null;
    const known = costModalSkuMap[sku_code];
    const valid = !isNaN(unit_cost) && unit_cost >= 0;
    if (valid) parsedCostRows.push({sku_code, unit_cost});
    if (!known) unknowns.push(sku_code);
    return {sku_code, description: known?.description||'—', unit_cost: valid?unit_cost:null, known:!!known, valid};
  }).filter(Boolean);
  const body = document.getElementById('previewBody');
  body.innerHTML = '';
  rows.forEach(r => {
    const sc = !r.known ? 'text-amber-600' : r.valid ? 'text-emerald-600' : 'text-red-600';
    const st = !r.known ? 'Unknown' : r.valid ? 'OK' : 'Invalid';
    body.innerHTML += `<tr class="border-t border-slate-100">
      <td class="py-1.5 px-3 font-mono text-indigo-600 text-xs">${r.sku_code}</td>
      <td class="py-1.5 px-3 text-slate-500 truncate max-w-xs text-xs">${esc(r.description)}</td>
      <td class="py-1.5 px-3 text-right text-xs">${r.unit_cost!=null?fmtN(r.unit_cost):'—'}</td>
      <td class="py-1.5 px-3 text-xs ${sc}">${st}</td>
    </tr>`;
  });
  document.getElementById('previewMeta').textContent = `${rows.length} rows · ${parsedCostRows.length} valid · ${rows.length-parsedCostRows.length} skipped`;
  document.getElementById('previewWarn').textContent = unknowns.length ? `${unknowns.length} unknown SKUs` : '';
  document.getElementById('costPreview').classList.remove('hidden');
  document.getElementById('saveBtn').disabled = parsedCostRows.length === 0;
}
async function saveCosts() {
  const btn = document.getElementById('saveBtn');
  const status = document.getElementById('saveStatus');
  btn.disabled = true;
  status.textContent = 'Saving…'; status.className = 'text-sm text-slate-400';
  try {
    const res = await fetch(`${API}/api/cost`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(parsedCostRows) });
    const data = await res.json();
    if (!res.ok) throw new Error(data.detail || 'Save failed');
    if (data.skipped_price_as_cost) {
      status.textContent = `✓ ${data.updated} saved · ⚠ ${data.skipped_price_as_cost} skipped (looked like price, not cost)`;
      status.className = 'text-sm text-amber-600';
      checkCostSpikes();
      return;  // keep modal open so the user can correct the skipped rows
    }
    status.textContent = `✓ ${data.updated} SKUs updated`; status.className = 'text-sm text-emerald-600';
    checkCostSpikes();
    setTimeout(closeCostModal, 1200);
  } catch(err) {
    status.textContent = '✗ ' + err.message; status.className = 'text-sm text-red-600';
    btn.disabled = false;
  }
}
async function downloadCostTemplate() {
  const btn = event?.target?.closest('button');
  const origText = btn?.innerHTML;
  if (btn) { btn.disabled = true; btn.innerHTML = '⏳ Preparing…'; }
  try {
    const data = await fetch(`${API}/api/cost/template`).then(r => r.json());
    const headers = [
      'sku_code',
      'unit_cost',          // ← fill this in (THB per portion)
      'description',
      'category',
      'ref_total_revenue',  // reference only — do not edit
      'ref_qty_sold',       // reference only — do not edit
      'ref_last_sold',      // reference only — do not edit
    ];
    const rows = [headers];
    data.forEach(s => rows.push([
      s.sku_code,
      s.unit_cost ?? '',    // pre-fill if already set
      s.description ?? '',
      s.category ?? '',
      s.total_revenue ?? 0,
      s.total_qty ?? 0,
      s.last_sold ?? '',
    ]));
    const csv = rows.map(r =>
      r.map(v => `"${String(v).replace(/"/g,'""')}"`).join(',')
    ).join('\r\n');
    const blob = new Blob(['﻿' + csv, ''], { type: 'text/csv;charset=utf-8' });
    const a = Object.assign(document.createElement('a'), {
      href: URL.createObjectURL(blob),
      download: `oshinei_cost_template_${new Date().toISOString().slice(0,10)}.csv`,
    });
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 10000);
  } catch(e) {
    alert('Download failed: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = origText; }
  }
}

// Kept for backward compat (modal ↓ Template button)

// ════════════════════════════════════════════════════════════════
// PHASE 8 — MONTHLY COST OVERRIDES
// ════════════════════════════════════════════════════════════════
let mcRows = [];        // current loaded rows
let mcEdits = {};       // sku_code -> {unit_cost, notes}
let mcHistChartRef = null;

function _mcCurrentMonth() {
  const el = document.getElementById('mcMonth');
  let m = (el?.value || '').trim();
  if (!m) {
    const d = new Date();
    m = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
    if (el) el.value = m;
  }
  return m;
}

async function loadMonthlyCost() {
  const month = _mcCurrentMonth();
  const status = document.getElementById('mcostStatus');
  status.textContent = 'กำลังโหลด…';
  try {
    const data = await fetch(`${API}/api/cost/monthly?month=${month}`).then(r => r.json());
    mcRows = Array.isArray(data) ? data : [];
    mcEdits = {};
    document.getElementById('mcSaveBtn').disabled = true;
    document.getElementById('mcSaveStatus').textContent = '';
    renderMonthlyCostTable();
    status.textContent = `${mcRows.length} SKUs · เดือน ${month}`;
  } catch(e) {
    status.textContent = '✗ โหลดไม่สำเร็จ: ' + e.message;
  }
}

function renderMonthlyCostTable() {
  const body = document.getElementById('mcostBody');
  if (!mcRows.length) {
    body.innerHTML = '<tr><td colspan="8" class="py-4 text-center text-slate-400">ไม่มีข้อมูล</td></tr>';
    return;
  }
  const q = (document.getElementById('mcSearch')?.value || '').trim().toLowerCase();
  const srcFilter = document.getElementById('mcSourceFilter')?.value || '';
  const month = _mcCurrentMonth();
  const fmt = v => (v==null || v==='') ? '' : (typeof fmtN === 'function' ? fmtN(v) : Number(v).toLocaleString('th-TH',{maximumFractionDigits:2}));
  const sourceBadge = {
    monthly:   '<span class="px-1.5 py-0.5 rounded bg-indigo-100 text-indigo-700">monthly</span>',
    inherited: '<span class="px-1.5 py-0.5 rounded bg-amber-100 text-amber-700">inherited</span>',
    default:   '<span class="px-1.5 py-0.5 rounded bg-slate-100 text-slate-600">default</span>',
    none:      '<span class="px-1.5 py-0.5 rounded bg-red-100 text-red-700">none</span>',
  };
  const filtered = mcRows.filter(r => {
    if (srcFilter && r.source !== srcFilter) return false;
    if (q) {
      const hay = ((r.sku_code||'') + ' ' + (r.description||'')).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
  body.innerHTML = filtered.map(r => {
    const edit = mcEdits[r.sku_code];
    const currentMonthly = edit !== undefined
      ? (edit.unit_cost === '' ? '' : edit.unit_cost)
      : (r.source === 'monthly' ? r.unit_cost : '');
    const currentNotes = edit !== undefined ? (edit.notes || '') : (r.notes || '');
    return `<tr class="border-t border-slate-100 hover:bg-slate-50">
      <td class="py-1.5 pr-3 font-mono text-indigo-600 text-xs">
        <a href="#" onclick="openMcHistory('${r.sku_code.replace(/'/g,"\\'")}'); return false;" class="hover:underline">${r.sku_code}</a>
      </td>
      <td class="py-1.5 pr-3 text-slate-600 truncate max-w-xs">${esc(r.description || '')}</td>
      <td class="py-1.5 pr-3 text-right text-slate-500">${fmt(r.default_cost)}</td>
      <td class="py-1.5 pr-3 text-right">
        <input type="number" step="0.01" min="0" value="${currentMonthly}"
               oninput="onMcCellEdit('${r.sku_code.replace(/'/g,"\\'")}', 'unit_cost', this.value)"
               class="w-24 text-right border border-slate-300 rounded px-1.5 py-0.5 text-xs">
      </td>
      <td class="py-1.5 pr-3 text-right font-semibold ${r.source==='none'?'text-red-600':'text-slate-700'}">${fmt(r.unit_cost)}</td>
      <td class="py-1.5 pr-3">${sourceBadge[r.source] || r.source}</td>
      <td class="py-1.5 pr-3">
        <input type="text" value="${(currentNotes||'').replace(/"/g,'&quot;')}"
               oninput="onMcCellEdit('${r.sku_code.replace(/'/g,"\\'")}', 'notes', this.value)"
               class="w-32 border border-slate-200 rounded px-1.5 py-0.5 text-xs" placeholder="—">
      </td>
      <td class="py-1.5 pr-3 text-right">
        ${r.source==='monthly' ? `<button onclick="deleteMcRow('${r.sku_code.replace(/'/g,"\\'")}')" class="text-red-500 hover:text-red-700 text-xs" title="ลบ override เดือนนี้">🗑</button>` : ''}
      </td>
    </tr>`;
  }).join('');
}

function onMcCellEdit(sku, field, value) {
  if (!mcEdits[sku]) mcEdits[sku] = { unit_cost: '', notes: '' };
  mcEdits[sku][field] = value;
  document.getElementById('mcSaveBtn').disabled = false;
}

async function saveMonthlyCostEdits() {
  const month = _mcCurrentMonth();
  const payload = [];
  for (const [sku_code, e] of Object.entries(mcEdits)) {
    const raw = String(e.unit_cost || '').trim();
    if (raw === '') continue;        // empty input = no override to save
    const uc = parseFloat(raw);
    if (isNaN(uc) || uc < 0) continue;
    payload.push({ sku_code, period_month: month, unit_cost: uc, notes: e.notes || null });
  }
  const status = document.getElementById('mcSaveStatus');
  if (!payload.length) { status.textContent = 'ไม่มีข้อมูลที่จะบันทึก'; return; }
  status.textContent = 'กำลังบันทึก…';
  try {
    const res = await fetch(`${API}/api/cost/monthly`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.detail || 'บันทึกไม่สำเร็จ');
    let msg = `✓ บันทึก ${data.written} รายการ`;
    if (data.unknown_skus?.length) msg += ` · unknown: ${data.unknown_skus.length}`;
    if (data.invalid_months?.length) msg += ` · invalid_months: ${data.invalid_months.length}`;
    status.textContent = msg;
    await loadMonthlyCost();
  } catch(e) {
    status.textContent = '✗ ' + e.message;
  }
}

async function deleteMcRow(sku) {
  if (!confirm(`ลบ monthly override ของ ${sku} เดือน ${_mcCurrentMonth()} ?`)) return;
  const month = _mcCurrentMonth();
  try {
    const res = await fetch(`${API}/api/cost/monthly?sku=${encodeURIComponent(sku)}&month=${month}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('delete failed');
    await loadMonthlyCost();
  } catch(e) { alert('ลบไม่สำเร็จ: ' + e.message); }
}

async function downloadMonthlyTemplate() {
  const month = _mcCurrentMonth();
  try {
    const res = await fetch(`${API}/api/cost/monthly/template?month=${month}`);
    if (!res.ok) throw new Error('template fetch failed');
    const blob = await res.blob();
    const a = Object.assign(document.createElement('a'), {
      href: URL.createObjectURL(blob),
      download: `cost_monthly_${month}.csv`,
    });
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 10000);
  } catch(e) { alert('ดาวน์โหลดไม่สำเร็จ: ' + e.message); }
}

function onMonthlyCsvSelected(ev) {
  const file = ev.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async () => {
    const text = reader.result;
    const month = _mcCurrentMonth();
    const lines = text.split(/\r?\n/).filter(l => l.trim());
    if (!lines.length) return;
    // Detect header
    const first = lines[0].toLowerCase();
    const hasHeader = first.includes('sku') || first.includes('code');
    const headerCells = hasHeader ? lines[0].split(',').map(s => s.trim().toLowerCase().replace(/"/g,'')) : null;
    let idxSku = 0, idxCost = -1, idxNotes = -1, idxMonth = -1;
    if (headerCells) {
      idxSku   = headerCells.findIndex(h => h.includes('sku'));
      idxMonth = headerCells.findIndex(h => h.includes('period') || h === 'month');
      idxCost  = headerCells.findIndex(h => h.includes('monthly_unit_cost'));
      if (idxCost === -1) idxCost = headerCells.findIndex(h => h.includes('unit_cost'));
      idxNotes = headerCells.findIndex(h => h.includes('note'));
    } else {
      idxCost = 1;
    }
    const payload = [];
    const skip = [];
    for (const line of (hasHeader ? lines.slice(1) : lines)) {
      // simple CSV split (no embedded commas/quotes expected in our template)
      const parts = line.split(',').map(s => s.trim().replace(/^"|"$/g,''));
      const sku_code = parts[idxSku] || '';
      const costRaw  = idxCost >= 0 ? (parts[idxCost] || '') : '';
      const notes    = idxNotes >= 0 ? (parts[idxNotes] || '') : '';
      const pm       = (idxMonth >= 0 && parts[idxMonth]) ? parts[idxMonth] : month;
      if (!sku_code || costRaw === '') { skip.push(sku_code); continue; }
      const uc = parseFloat(costRaw);
      if (isNaN(uc) || uc < 0) { skip.push(sku_code); continue; }
      payload.push({ sku_code, period_month: pm, unit_cost: uc, notes: notes || null });
    }
    if (!payload.length) { alert(`ไม่มีแถวที่ใช้ได้ (skipped ${skip.length})`); ev.target.value=''; return; }
    if (!confirm(`อัปโหลด ${payload.length} แถว (skip ${skip.length}) เดือน ${month} ?`)) { ev.target.value=''; return; }
    try {
      const res = await fetch(`${API}/api/cost/monthly`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'upload failed');
      alert(`✓ บันทึก ${data.written}\n• unknown SKUs: ${data.unknown_skus?.length||0}\n• invalid months: ${data.invalid_months?.length||0}`);
      await loadMonthlyCost();
    } catch(err) {
      alert('อัปโหลดไม่สำเร็จ: ' + err.message);
    } finally {
      ev.target.value = '';
    }
  };
  reader.readAsText(file);
}

// Upload a sales-data file (cleansed-raw Easy export or legacy .txt) to /api/upload.
// The backend auto-detects format and routes to the shared upload_data engine.
async function onSalesDataSelected(ev) {
  const file = ev.target.files && ev.target.files[0];
  if (!file) return;
  if (!confirm(`อัพโหลดไฟล์ยอดขาย "${file.name}" เข้าฐานข้อมูล?\n(จะแทนที่ข้อมูลของเดือนนั้น — curated cost ไม่ถูกแตะ)`)) {
    ev.target.value = ''; return;
  }
  const fd = new FormData();
  fd.append('file', file);
  // Hosted deploys require an upload token (X-Upload-Token). Local dev needs none.
  const doUpload = (tok) => {
    const headers = tok ? { 'X-Upload-Token': tok } : {};
    return fetch(`${API}/api/upload`, { method: 'POST', body: fd, headers });
  };
  try {
    let res = await doUpload(localStorage.getItem('oshinei_upload_token') || '');
    if (res.status === 403) {
      const tok = prompt('การอัพโหลดบนเซิร์ฟเวอร์นี้ต้องใช้ Upload Token:');
      if (!tok) { ev.target.value = ''; return; }
      localStorage.setItem('oshinei_upload_token', tok.trim());
      res = await doUpload(tok.trim());
    }
    const data = await res.json();
    if (!res.ok) {
      if (res.status === 403) localStorage.removeItem('oshinei_upload_token');
      throw new Error(data.detail || 'upload failed');
    }
    alert(`✓ อัพโหลดสำเร็จ\n• ไฟล์: ${data.file}\n• ชนิด: ${data.file_type}\n• เดือน: ${data.period}\n• สาขา: ${data.branch}\n• แถว: ${data.rows_ingested}`);
    location.reload();
  } catch (err) {
    alert('อัพโหลดไม่สำเร็จ: ' + err.message);
  } finally {
    ev.target.value = '';
  }
}

async function openMcHistory(sku) {
  const modal = document.getElementById('mcHistoryModal');
  modal.classList.remove('hidden'); modal.classList.add('flex');
  document.getElementById('mcHistTitle').textContent = `ประวัติต้นทุน — ${sku}`;
  document.getElementById('mcHistBody').innerHTML = '<tr><td colspan="4" class="py-3 text-center text-slate-400">กำลังโหลด…</td></tr>';
  try {
    const data = await fetch(`${API}/api/cost/monthly?sku=${encodeURIComponent(sku)}`).then(r => r.json());
    const monthly = (data || []).filter(r => r.source === 'monthly').sort((a,b)=>a.period_month.localeCompare(b.period_month));
    const def = (data || []).find(r => r.source === 'default');
    const tbody = document.getElementById('mcHistBody');
    const rows = [...monthly];
    if (def) rows.push({ period_month: '— default —', unit_cost: def.unit_cost, source: 'default', notes: '' });
    tbody.innerHTML = rows.length ? rows.map(r => `
      <tr class="border-t border-slate-100">
        <td class="py-1.5 pr-3">${r.period_month || ''}</td>
        <td class="py-1.5 pr-3 text-right">${r.unit_cost==null?'—':(typeof fmtN==='function'?fmtN(r.unit_cost):r.unit_cost)}</td>
        <td class="py-1.5 pr-3 text-xs text-slate-500">${r.source}</td>
        <td class="py-1.5 pr-3 text-xs text-slate-500">${r.notes||''}</td>
      </tr>`).join('') : '<tr><td colspan="4" class="py-3 text-center text-slate-400">ไม่มีข้อมูล</td></tr>';

    // Render simple line chart (Chart.js available globally)
    const canvas = document.getElementById('mcHistChart');
    if (canvas && typeof Chart !== 'undefined') {
      if (mcHistChartRef) { try { mcHistChartRef.destroy(); } catch(_){} }
      const labels = monthly.map(r => r.period_month);
      const values = monthly.map(r => r.unit_cost);
      mcHistChartRef = new Chart(canvas.getContext('2d'), {
        type: 'line',
        data: {
          labels,
          datasets: [{
            label: 'unit_cost',
            data: values,
            borderColor: '#6366f1',
            backgroundColor: 'rgba(99,102,241,.1)',
            tension: 0.25,
            fill: true,
          }, def ? {
            label: 'default',
            data: labels.map(() => def.unit_cost),
            borderColor: '#94a3b8',
            borderDash: [5,4],
            pointRadius: 0,
            fill: false,
          } : null].filter(Boolean),
        },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: true } } },
      });
    }
  } catch(e) {
    document.getElementById('mcHistBody').innerHTML = `<tr><td colspan="4" class="py-3 text-center text-red-500">${e.message}</td></tr>`;
  }
}

function closeMcHistory() {
  const modal = document.getElementById('mcHistoryModal');
  modal.classList.add('hidden'); modal.classList.remove('flex');
  if (mcHistChartRef) { try { mcHistChartRef.destroy(); } catch(_){} mcHistChartRef = null; }
}

// ════════════════════════════════════════════════════════════════
// TAB 6 — COST ANALYSIS
// ════════════════════════════════════════════════════════════════

let costData = null;            // raw API response
let activeCostTab = 'overview';
let costSortKey = 'revenue';
let costSortAsc = false;

function switchCostTab(name) {
  activeCostTab = name;
  document.querySelectorAll('#tab-cost .subtab-btn').forEach((b, i) => {
    b.classList.toggle('active', ['overview','detail','suggestions'][i] === name);
  });
  ['overview','detail','suggestions'].forEach(s =>
    document.getElementById('costtab-' + s).classList.toggle('hidden', s !== name)
  );
  if (!costData) return;
  if (name === 'overview')    renderCostOverview();
  if (name === 'detail')      renderCostDetail();
  if (name === 'suggestions') renderSuggestions();
}

// ════════════════════════════════════════════════════════════════
// PROFIT ANALYSIS — joins sales × sku_cost ⇒ GP, margin, per-bill
// ════════════════════════════════════════════════════════════════
let _buffetPerBillGran = 'monthly';
function setBuffetPerBillGran(g) {
  _buffetPerBillGran = g;
  ['daily','weekly','monthly','quarterly'].forEach(v => {
    const btn = document.getElementById('bpb-' + v);
    if (!btn) return;
    btn.className = (v === g)
      ? 'px-3 py-1.5 bg-pink-600 text-white border-l border-slate-200'
      : 'px-3 py-1.5 bg-white text-slate-600 hover:bg-pink-50 border-l border-slate-200';
  });
  loadBuffetPerBill();
}

async function loadBuffetPerBill() {
  const p = new URLSearchParams();
  if (getBranch())    p.set('branch',     getBranch());
  if (getMonthFrom()) p.set('month_from', getMonthFrom());
  if (getMonthTo())   p.set('month_to',   getMonthTo());
  p.set('granularity', _buffetPerBillGran);
  const d = await fetch(`${API}/api/profit/buffet_per_bill?${p}`).then(r => r.json()).catch(() => null);
  if (!d || !d.rows) return;

  const ov = d.overall || {};
  const kpi = (lbl, val, sub, color) =>
    `<div class="rounded-lg p-3 border" style="background:${color}10;border-color:${color}33">
      <p class="text-[10px] text-slate-500 uppercase tracking-wide">${lbl}</p>
      <p class="text-lg font-bold" style="color:${color}">${val}</p>
      <p class="text-[10px] text-slate-400">${sub}</p>
    </div>`;
  document.getElementById('bpbKpiStrip').innerHTML = [
    kpi('บิลทั้งหมด',          fmtN(ov.bills),               `${fmtN(ov.pax)} pax`,        '#ec4899'),
    kpi('รายได้ ex-VAT',        fmt(ov.revenue_ex),           `เฉลี่ย/บิล ${fmt(ov.avg_per_bill_rev)}`,    '#4f46e5'),
    kpi('BoM (ต้นทุน)',         fmt(ov.cost),                 `เฉลี่ย/บิล ${fmt(ov.avg_per_bill_cost)}`,   '#dc2626'),
    kpi('กำไรขั้นต้น',          fmt(ov.profit),               `เฉลี่ย/บิล ${fmt(ov.avg_per_bill_profit)}`, '#10b981'),
    kpi('% Margin',             `${(ov.margin_pct||0).toFixed(1)}%`, `BoM ${(100-(ov.margin_pct||0)).toFixed(1)}% ของรายได้`, ov.margin_pct >= 40 ? '#10b981' : ov.margin_pct >= 25 ? '#f59e0b' : '#ef4444'),
  ].join('');

  const rows = d.rows;

  // Line+bar chart: avg revenue/bill, avg cost/bill, avg profit/bill per period
  mkChart('chartBuffetPerBill', {
    type: 'bar',
    data: {
      labels: rows.map(r => r.period),
      datasets: [
        { type:'bar',  label:'เฉลี่ย/บิล: รายได้', data: rows.map(r => r.avg_per_bill_rev),    backgroundColor:'rgba(79,70,229,0.55)', borderRadius:3, yAxisID:'y' },
        { type:'bar',  label:'เฉลี่ย/บิล: BoM',     data: rows.map(r => r.avg_per_bill_cost),   backgroundColor:'rgba(220,38,38,0.65)', borderRadius:3, yAxisID:'y' },
        { type:'line', label:'เฉลี่ย/บิล: กำไร',    data: rows.map(r => r.avg_per_bill_profit), borderColor:'#10b981', backgroundColor:'rgba(16,185,129,0.15)', tension:0.3, fill:true, yAxisID:'y' },
        { type:'line', label:'% Margin',            data: rows.map(r => r.margin_pct),          borderColor:'#f59e0b', borderDash:[4,3], backgroundColor:'transparent', tension:0.25, yAxisID:'y1', pointRadius:3 },
      ],
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: true, position: 'bottom', labels: { font: { size: 10 } } },
        datalabels: { display: false },
        tooltip: { mode: 'index', intersect: false },
      },
      scales: {
        x: { ticks: { font: { size: 9 } } },
        y:  { position:'left',  ticks: { font: { size: 9 }, callback: v => fmt(v) } },
        y1: { position:'right', ticks: { font: { size: 9 }, callback: v => v.toFixed(0) + '%' }, grid: { display: false }, min: 0, max: 100 },
      },
    },
  });

  // Cost mix doughnut — concentration of BoM cost by per-head spend bracket
  const tierMix = ov.tier_cost_mix || {};
  const TIER_COLORS = { '≤450': '#eab308', '450-600': '#10b981', '600-720': '#4f46e5', '>720': '#f97316' };
  const tierKeys = Object.keys(tierMix);
  mkChart('chartBuffetCostMix', {
    type: 'doughnut',
    data: {
      labels: tierKeys,
      datasets: [{
        data: tierKeys.map(k => tierMix[k]),
        backgroundColor: tierKeys.map(k => TIER_COLORS[k] || '#94a3b8'),
        borderWidth: 2, borderColor: '#fff',
      }],
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '60%',
      plugins: {
        legend: { display: true, position: 'bottom', labels: { font: { size: 10 }, boxWidth: 10 } },
        datalabels: { display: false },
        tooltip: { callbacks: {
          label: ctx => {
            const tot = tierKeys.reduce((s,k) => s + (tierMix[k]||0), 0);
            const pct = tot ? (ctx.raw / tot * 100).toFixed(1) : 0;
            return ` ${ctx.label}: ${fmt(ctx.raw)} (${pct}%)`;
          }
        } },
      },
    },
  });

  // Detail table
  const colorMargin = v => v >= 40 ? 'text-emerald-600 font-semibold' : v >= 25 ? 'text-amber-600' : 'text-red-600 font-semibold';
  document.getElementById('bpbTableBody').innerHTML = rows.map(r => `
    <tr class="border-t border-slate-100 hover:bg-pink-50/40">
      <td class="py-1.5 pr-2 font-medium">${r.period}</td>
      <td class="py-1.5 pr-2 text-right">${fmtN(r.bills)}</td>
      <td class="py-1.5 pr-2 text-right">${fmtN(r.pax)}</td>
      <td class="py-1.5 pr-2 text-right">${fmt(r.revenue_ex)}</td>
      <td class="py-1.5 pr-2 text-right">${fmt(r.cost)}</td>
      <td class="py-1.5 pr-2 text-right font-semibold ${r.profit >= 0 ? 'text-emerald-700' : 'text-red-700'}">${fmt(r.profit)}</td>
      <td class="py-1.5 pr-2 text-right ${colorMargin(r.margin_pct)}">${r.margin_pct.toFixed(1)}%</td>
      <td class="py-1.5 pr-2 text-right">${fmt(r.avg_per_bill_rev)}</td>
      <td class="py-1.5 pr-2 text-right">${fmt(r.avg_per_bill_cost)}</td>
      <td class="py-1.5 pr-2 text-right font-semibold">${fmt(r.avg_per_bill_profit)}</td>
      <td class="py-1.5 text-right text-[11px] text-slate-500">${r.dominant_tier || '—'}</td>
    </tr>
  `).join('');

  // Insight summary
  const insightEl = document.getElementById('bpbInsight');
  if (rows.length >= 2 && insightEl) {
    const last  = rows[rows.length - 1];
    const prev  = rows[rows.length - 2];
    const dM    = last.margin_pct - prev.margin_pct;
    const dRev  = last.avg_per_bill_rev - prev.avg_per_bill_rev;
    const arrow = dM >= 0 ? '▲' : '▼';
    const trend = dM >= 0 ? 'text-emerald-600' : 'text-red-600';
    insightEl.innerHTML = `💡 <b>เทียบ ${last.period} กับ ${prev.period}:</b>
      Margin <span class="${trend}">${arrow} ${Math.abs(dM).toFixed(1)} percentage points</span>
      · รายได้เฉลี่ย/บิล ${dRev >= 0 ? '▲' : '▼'} ${fmt(Math.abs(dRev))}
      · ช่วงใช้จ่าย/หัวที่พบบ่อยสุด <b>${last.dominant_tier || '—'}</b> บาท`;
  } else if (insightEl) {
    insightEl.innerHTML = '';
  }
}

async function loadProfitAnalysis() {
  const params = new URLSearchParams();
  if (getBranch())    params.set('branch',     getBranch());
  if (getMonthFrom()) params.set('month_from', getMonthFrom());
  if (getMonthTo())   params.set('month_to',   getMonthTo());

  // Kick off buffet per-bill in parallel; no need to await it
  loadBuffetPerBill();

  // Fetch endpoints in parallel (Top/Bottom-SKU removed 2026-06-01)
  const [summary, trend, byBranch, dist] = await Promise.all([
    fetch(`${API}/api/profit/summary?${params}`).then(r=>r.json()),
    fetch(`${API}/api/profit/trend?${params}`).then(r=>r.json()),
    fetch(`${API}/api/profit/by-branch?${params}`).then(r=>r.json()),
    fetch(`${API}/api/profit/per-bill-distribution?${params}`).then(r=>r.json()),
  ]);

  // KPI cards
  document.getElementById('pftRev').textContent     = fmtN(summary.revenue_ex_vat || 0);
  document.getElementById('pftCogs').textContent    = fmtN(summary.cogs || 0);
  document.getElementById('pftGp').textContent      = fmtN(summary.gross_profit || 0);
  document.getElementById('pftMargin').textContent  = summary.margin_pct != null ? summary.margin_pct.toFixed(1) + '%' : '—';
  document.getElementById('pftPerBill').textContent = fmtN(summary.profit_per_bill || 0);

  // Cost-coverage banner
  const cov = summary.cost_coverage_pct || 0;
  const banner = document.getElementById('profitCoverageBanner');
  const msg    = document.getElementById('profitCoverageMsg');
  if (cov < 90) {
    banner.classList.remove('hidden');
    if (cov === 0) {
      msg.innerHTML = '<b>No SKU costs uploaded yet.</b> Profit metrics show 0 until you upload cost data via <b>Settings → Costs</b>. Upload a CSV with sku_code, unit_cost columns to activate this dashboard.';
    } else {
      msg.innerHTML = `<b>Cost coverage: ${cov.toFixed(0)}%</b> of revenue. Some SKUs lack cost data. Profit figures reflect only costed SKUs. Improve accuracy by uploading more costs in <b>Settings → Costs</b>.`;
    }
  } else {
    banner.classList.add('hidden');
  }

  // Trend chart: Revenue, COGS, GP, Margin %
  mkChart('chartProfitTrend', {
    type: 'bar',
    data: {
      labels: trend.map(t => fmtPeriod(t.period_month)),
      datasets: [
        { type:'bar',  label:'COGS',         data: trend.map(t=>t.cogs),                  backgroundColor:'rgba(239,68,68,0.7)',  stack:'stack1', order:2 },
        { type:'bar',  label:'Gross Profit', data: trend.map(t=>t.gross_profit),          backgroundColor:'rgba(16,185,129,0.7)', stack:'stack1', order:2 },
        { type:'line', label:'Margin %',     data: trend.map(t=>t.margin_pct),            yAxisID:'y1', borderColor:'#06b6d4', backgroundColor:'#06b6d4', tension:0.25, order:1, fill:false },
      ],
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      plugins: { legend:{position:'bottom'}, datalabels:{display:false},
        tooltip:{callbacks:{label:ctx=>ctx.dataset.label+': '+(ctx.dataset.label==='Margin %'?(ctx.raw??0).toFixed(1)+'%':fmtN(ctx.raw||0))}} },
      scales: {
        x: { stacked:true, ticks:{color:chartTheme().text} },
        y: { stacked:true, ticks:{color:chartTheme().text, callback:v=>fmtN(v)} },
        y1:{ position:'right', grid:{display:false}, ticks:{color:'#06b6d4', callback:v=>v+'%'}, max:100, min:0 },
      },
    },
  });

  // Per-bill distribution
  mkChart('chartProfitDist', {
    type: 'bar',
    data: {
      labels: dist.buckets.map(b=>b.label),
      datasets: [{ label:'Bills', data: dist.buckets.map(b=>b.count), backgroundColor:'#8b5cf6' }],
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      plugins: { legend:{display:false}, datalabels:{display:false},
        tooltip:{callbacks:{label:ctx=>fmtN(ctx.raw)+' bills'}} },
      scales: { x:{ticks:{color:chartTheme().text}}, y:{beginAtZero:true,ticks:{color:chartTheme().text}} },
    },
  });
  document.getElementById('pftDistNote').textContent = dist.note
    ? `⚠ ${dist.note}`
    : `Range: ${fmtN(dist.min_profit)} → ${fmtN(dist.max_profit)} · Avg: ${fmtN(dist.avg_profit)} · Margin used: ${dist.margin_pct_used}% · ${fmtN(dist.total_tx)} bills`;

  // By-branch bar chart
  mkChart('chartProfitBranch', {
    type: 'bar',
    data: {
      labels: byBranch.map(b=>b.branch),
      datasets: [
        { label:'Revenue (ex-VAT)', data: byBranch.map(b=>b.revenue_ex_vat||0), backgroundColor:'rgba(79,70,229,0.6)' },
        { label:'COGS',             data: byBranch.map(b=>b.cogs||0),           backgroundColor:'rgba(239,68,68,0.6)' },
        { label:'Gross Profit',     data: byBranch.map(b=>b.gross_profit||0),   backgroundColor:'rgba(16,185,129,0.6)' },
      ],
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      plugins: { legend:{position:'bottom'}, datalabels:{display:false},
        tooltip:{callbacks:{label:ctx=>ctx.dataset.label+': '+fmtN(ctx.raw||0)}} },
      scales: { x:{ticks:{color:chartTheme().text}}, y:{ticks:{color:chartTheme().text, callback:v=>fmtN(v)}} },
    },
  });

  // Top/Bottom 15 SKU tables removed 2026-06-01 (per-SKU profit unreliable for buffet).
}

// ════════════════════════════════════════════════════════════════
// TAB: P&L DEEP DIVE
// ════════════════════════════════════════════════════════════════
let pnlDeepBranch = '';
let pnlBranchRows = [];
let pnlSortCol = 'gross_profit';
let pnlSortAsc = false;

async function loadPnlTab() {
  const params = new URLSearchParams();
  if (getBranch())    params.set('branch',     getBranch());
  if (getMonthFrom()) params.set('month_from', getMonthFrom());
  if (getMonthTo())   params.set('month_to',   getMonthTo());
  if (getGroup())     params.set('group',      getGroup());

  const branchParams = new URLSearchParams();
  if (getMonthFrom()) branchParams.set('month_from', getMonthFrom());
  if (getMonthTo())   branchParams.set('month_to',   getMonthTo());
  if (getGroup())     branchParams.set('group',      getGroup());

  const [summary, monthly, branchRows] = await Promise.all([
    fetch(`${API}/api/profit/summary?${params}`).then(r => r.json()),
    fetch(`${API}/api/pnl/monthly?${params}`).then(r => r.json()),
    fetch(`${API}/api/pnl/branches?${branchParams}`).then(r => r.json()),
  ]);

  renderPnlKpis(summary);
  renderPnlTrend(monthly);

  pnlBranchRows = branchRows;
  renderPnlBranchTable();
  populatePnlDeepBranchSelector(branchRows);

  // Bill distribution: use branch detail when branch is selected, else chain-wide estimate
  if (getBranch()) {
    fetch(`${API}/api/pnl/branch-detail?${params}`).then(r => r.json()).then(d => {
      renderPnlBillDist(d.bill_stats, true);
    });
  } else {
    fetch(`${API}/api/profit/per-bill-distribution?${params}`).then(r => r.json()).then(dist => {
      renderPnlBillDistChain(dist);
    });
  }

  // Reload deep dive if a branch was already selected
  if (pnlDeepBranch) loadPnlDeepDive(pnlDeepBranch);
}

function renderPnlKpis(s) {
  const cov = s.cost_coverage_pct || 0;
  const banner = document.getElementById('pnlCoverageBanner');
  const msg    = document.getElementById('pnlCoverageMsg');
  if (cov < 90 && banner) {
    banner.classList.remove('hidden');
    msg.innerHTML = cov === 0
      ? '<b>No SKU costs uploaded yet.</b> GP / Margin show 0. Upload costs via <b>Settings → Costs</b>.'
      : `<b>Cost coverage: ${cov.toFixed(0)}%</b> of revenue. Profit figures reflect only costed SKUs.`;
  } else if (banner) banner.classList.add('hidden');

  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('pnlRev',     fmtN(s.revenue_ex_vat || 0));
  set('pnlCogs',    fmtN(s.cogs || 0));
  set('pnlGp',      fmtN(s.gross_profit || 0));
  set('pnlMargin',  s.margin_pct != null ? s.margin_pct.toFixed(1) + '%' : '—');
  set('pnlPerBill', s.profit_per_bill != null ? fmtN(s.profit_per_bill) : '—');
  set('pnlBills',   fmtN(s.tx_count || 0));
}

function renderPnlTrend(monthly) {
  mkChart('chartPnlTrend', {
    type: 'bar',
    data: {
      labels: monthly.map(m => fmtPeriod(m.period_month)),
      datasets: [
        { type:'bar',  label:'รายได้ (ก่อน VAT)', data: monthly.map(m => m.revenue_ex_vat||0), backgroundColor:'rgba(79,70,229,0.45)', order:3 },
        { type:'bar',  label:'ต้นทุน (COGS)',     data: monthly.map(m => m.cogs||0),           backgroundColor:'rgba(239,68,68,0.65)', order:3 },
        { type:'line', label:'กำไรขั้นต้น',       data: monthly.map(m => m.gross_profit||0),   borderColor:'#10b981', backgroundColor:'rgba(16,185,129,0.12)', tension:0.3, fill:true, order:1 },
        { type:'line', label:'% กำไรขั้นต้น',     data: monthly.map(m => m.margin_pct),        borderColor:'#f59e0b', borderDash:[4,3], backgroundColor:'transparent', tension:0.25, yAxisID:'y1', order:0, fill:false },
      ],
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      plugins:{
        legend:{ position:'bottom', labels:{ font:{size:10} } },
        datalabels:{ display:false },
        tooltip:{ callbacks:{ label: ctx => ctx.dataset.label === 'Margin %'
          ? 'Margin: ' + (ctx.raw??0).toFixed(1) + '%'
          : ctx.dataset.label + ': '+fmtN(ctx.raw||0) }},
      },
      scales:{
        x:{ ticks:{color:chartTheme().text} },
        y:{ ticks:{color:chartTheme().text, callback:v=>fmt(v)} },
        y1:{ position:'right', grid:{display:false}, ticks:{color:'#f59e0b', callback:v=>v+'%'}, min:0 },
      },
    },
  });
}

function renderPnlBillDistChain(dist) {
  const note = document.getElementById('pnlBillDistNote');
  if (!dist.buckets || dist.buckets.length === 0) {
    if (note) note.textContent = 'Upload SKU costs to see estimated GP/bill distribution';
    return;
  }
  if (note) note.textContent = `Est. GP/bill · Margin rate used: ${dist.margin_pct_used}% · ${fmtN(dist.total_tx)} bills`;
  mkChart('chartPnlBillDist', {
    type:'bar',
    data:{ labels: dist.buckets.map(b=>b.label), datasets:[{ label:'Bills', data:dist.buckets.map(b=>b.count), backgroundColor:'#8b5cf6', borderRadius:3, borderWidth:0 }] },
    options:{ responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false},datalabels:{display:false},tooltip:{callbacks:{label:ctx=>fmtN(ctx.raw)+' bills'}}},
      scales:{x:{ticks:{color:chartTheme().text}},y:{beginAtZero:true,ticks:{color:chartTheme().text}}} },
  });
}

function renderPnlBillDist(stats, isRevenue) {
  const note = document.getElementById('pnlBillDistNote');
  if (!stats || stats.tx_count === 0) {
    if (note) note.textContent = 'No Easy POS transaction data for this period (available from May 2025)';
    return;
  }
  const buckets = isRevenue ? stats.buckets : stats.profit_buckets;
  const label   = isRevenue ? 'Revenue/bill ' : 'Est. GP/bill ';
  if (note) note.textContent = `${fmtN(stats.tx_count)} bills · Avg ${fmtN(stats.avg)} · Median ${fmtN(stats.p50)}${stats.margin_pct_used > 0 ? ' · Margin: '+stats.margin_pct_used+'%' : ''}`;
  mkChart('chartPnlBillDist', {
    type:'bar',
    data:{ labels: buckets.map(b=>b.label+' '), datasets:[{ label, data:buckets.map(b=>b.count), backgroundColor:'#4f46e5', borderRadius:3, borderWidth:0 }] },
    options:{ responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false},datalabels:{display:false},tooltip:{callbacks:{label:ctx=>fmtN(ctx.raw)+' bills'}}},
      scales:{x:{ticks:{color:chartTheme().text,font:{size:9}}},y:{beginAtZero:true,ticks:{color:chartTheme().text}}} },
  });
}

// Branch comparison table
function renderPnlBranchTable() {
  const rows = [...pnlBranchRows].sort((a, b) => {
    const va = a[pnlSortCol] ?? (pnlSortAsc ? Infinity : -Infinity);
    const vb = b[pnlSortCol] ?? (pnlSortAsc ? Infinity : -Infinity);
    return typeof va === 'string'
      ? (pnlSortAsc ? va.localeCompare(vb) : vb.localeCompare(va))
      : (pnlSortAsc ? va - vb : vb - va);
  });
  // Update sort indicator
  ['branch','revenue_ex_vat','cogs','gross_profit','margin_pct','tx_count','avg_ticket','profit_per_bill'].forEach(c => {
    const el = document.getElementById('pnlSort' + c.charAt(0).toUpperCase() + c.slice(1));
    if (el) el.textContent = c === pnlSortCol ? (pnlSortAsc ? '▲' : '▼') : '↕';
  });
  const gpMax = Math.max(...pnlBranchRows.map(r => r.gross_profit || 0), 1);
  document.getElementById('pnlBranchBody').innerHTML = rows.map(r => {
    const gp = r.gross_profit || 0;
    const gpPct = Math.round(gp / gpMax * 100);
    const mColor = (r.margin_pct||0) > 40 ? '#10b981' : (r.margin_pct||0) > 20 ? '#f59e0b' : '#ef4444';
    return `<tr class="border-b border-slate-100 hover:bg-slate-50 cursor-pointer" onclick="clickPnlBranchRow('${jsAttr(r.branch)}')">
      <td class="py-1.5 pr-3 font-medium text-indigo-600">${esc(r.branch)}</td>
      <td class="py-1.5 pr-3 text-right">${fmtN(r.revenue_ex_vat||0)}</td>
      <td class="py-1.5 pr-3 text-right text-red-500">${fmtN(r.cogs||0)}</td>
      <td class="py-1.5 pr-3 text-right">
        <div class="flex items-center justify-end gap-1.5">
          <div class="bg-slate-100 rounded-full h-1.5 w-14 overflow-hidden hidden sm:block">
            <div class="bg-emerald-500 h-full rounded-full" style="width:${gpPct}%"></div>
          </div>
          <span class="text-emerald-600 font-semibold">${fmtN(gp)}</span>
        </div>
      </td>
      <td class="py-1.5 pr-3 text-right font-bold" style="color:${mColor}">${r.margin_pct != null ? r.margin_pct.toFixed(1)+'%' : '—'}</td>
      <td class="py-1.5 pr-3 text-right">${fmtN(r.tx_count||0)}</td>
      <td class="py-1.5 pr-3 text-right">${fmtN(r.avg_ticket||0)}</td>
      <td class="py-1.5 text-right font-medium" style="color:#8b5cf6">${r.profit_per_bill != null ? fmtN(r.profit_per_bill) : '—'}</td>
    </tr>`;
  }).join('');
}

function sortPnlTable(col) {
  pnlSortAsc = pnlSortCol === col ? !pnlSortAsc : false;
  pnlSortCol = col;
  renderPnlBranchTable();
}

function clickPnlBranchRow(branch) {
  const sel = document.getElementById('pnlDeepBranchSel');
  if (sel) sel.value = branch;
  loadPnlDeepDive(branch);
  // Scroll to deep dive section
  document.getElementById('pnlDeepContent')?.scrollIntoView({ behavior:'smooth', block:'start' });
}

function populatePnlDeepBranchSelector(branches) {
  const sel = document.getElementById('pnlDeepBranchSel');
  if (!sel) return;
  const prev = pnlDeepBranch || sel.value;
  sel.innerHTML = '<option value="">— Select a branch —</option>' +
    branches.map(b => `<option value="${esc(b.branch)}"${b.branch === prev ? ' selected' : ''}>${esc(b.branch)}</option>`).join('');
}

function onPnlDeepBranchChange() {
  const branch = document.getElementById('pnlDeepBranchSel')?.value;
  if (branch) loadPnlDeepDive(branch);
  else {
    pnlDeepBranch = '';
    document.getElementById('pnlDeepContent')?.classList.add('hidden');
    document.getElementById('pnlDeepBranchHint')?.classList.remove('hidden');
  }
}

async function loadPnlDeepDive(branch) {
  pnlDeepBranch = branch;
  const p = new URLSearchParams({ branch });
  if (getMonthFrom()) p.set('month_from', getMonthFrom());
  if (getMonthTo())   p.set('month_to',   getMonthTo());

  const data = await fetch(`${API}/api/pnl/branch-detail?${p}`).then(r => r.json());

  document.getElementById('pnlDeepContent')?.classList.remove('hidden');
  document.getElementById('pnlDeepBranchHint')?.classList.add('hidden');

  renderPnlDeepTrend(data.monthly);
  renderPnlDeepBillStats(data.bill_stats);
  renderPnlDeepMonthTable(data.monthly);
  renderPnlDeepIngredients(data.top_ingredients || []);
  renderPnlDeepCategoryMix(data.category_mix || []);
  renderPnlDeepSkus(data.top_skus);

  // Update selector to match
  const sel = document.getElementById('pnlDeepBranchSel');
  if (sel && sel.value !== branch) sel.value = branch;
}

function renderPnlDeepTrend(monthly) {
  mkChart('chartPnlDeepTrend', {
    type:'bar',
    data:{
      labels: monthly.map(m => fmtPeriod(m.period_month)),
      datasets:[
        { type:'bar',  label:'รายได้',      data:monthly.map(m=>m.revenue_ex_vat||0), backgroundColor:'rgba(79,70,229,0.35)', order:2 },
        { type:'bar',  label:'COGS',         data:monthly.map(m=>m.cogs||0),           backgroundColor:'rgba(239,68,68,0.6)',  order:2 },
        { type:'line', label:'Gross Profit', data:monthly.map(m=>m.gross_profit||0),   borderColor:'#10b981', tension:0.3, fill:false, order:1, pointRadius:3 },
        { type:'line', label:'GP/Bill',      data:monthly.map(m=>m.profit_per_bill),   borderColor:'#8b5cf6', borderDash:[4,2], tension:0.3, fill:false, order:0, yAxisID:'y1', pointRadius:2 },
      ],
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      plugins:{ legend:{position:'bottom',labels:{font:{size:10}}}, datalabels:{display:false},
        tooltip:{callbacks:{label:ctx=>ctx.dataset.yAxisID==='y1'?ctx.dataset.label+': '+fmtN(ctx.raw||0):ctx.dataset.label+': '+fmtN(ctx.raw||0)}} },
      scales:{
        x:{ ticks:{color:chartTheme().text,font:{size:9}} },
        y:{ ticks:{color:chartTheme().text, callback:v=>fmt(v)} },
        y1:{ position:'right', grid:{display:false}, ticks:{color:'#8b5cf6', callback:v=>fmt(v)} },
      },
    },
  });
}

function renderPnlDeepBillStats(stats) {
  const el = document.getElementById('pnlBillStatsTable');
  if (!el) return;
  if (!stats || stats.tx_count === 0) {
    el.innerHTML = '<p class="text-slate-400 py-2">No Easy POS transaction data for this period (Easy POS available from May 2025)</p>';
    return;
  }
  const m = stats.margin_pct_used;
  const gpRow = m > 0 ? `<tr class="border-b border-slate-100">
    <td class="py-1 pr-2 text-slate-500">Est. GP/Bill</td>
    <td class="text-right py-1">${fmtN((stats.p10*m/100).toFixed(0))}</td>
    <td class="text-right py-1">${fmtN((stats.p25*m/100).toFixed(0))}</td>
    <td class="text-right py-1 font-semibold">${fmtN((stats.p50*m/100).toFixed(0))}</td>
    <td class="text-right py-1">${fmtN((stats.p75*m/100).toFixed(0))}</td>
    <td class="text-right py-1">${fmtN((stats.p90*m/100).toFixed(0))}</td>
    <td class="text-right py-1 font-bold text-emerald-600">${fmtN(stats.avg_profit)}</td>
  </tr>` : '';
  el.innerHTML = `<table class="w-full border-collapse">
    <thead><tr class="border-b border-slate-200 text-slate-500">
      <th class="text-left py-1 pr-2"></th>
      <th class="text-right py-1 pr-2">P10</th><th class="text-right py-1 pr-2">P25</th>
      <th class="text-right py-1 pr-2">Median</th><th class="text-right py-1 pr-2">P75</th>
      <th class="text-right py-1 pr-2">P90</th><th class="text-right py-1">Avg</th>
    </tr></thead>
    <tbody>
      <tr class="border-b border-slate-100">
        <td class="py-1 pr-2 text-slate-600 font-medium">Revenue/Bill</td>
        <td class="text-right py-1">${fmtN(stats.p10)}</td>
        <td class="text-right py-1">${fmtN(stats.p25)}</td>
        <td class="text-right py-1 font-semibold">${fmtN(stats.p50)}</td>
        <td class="text-right py-1">${fmtN(stats.p75)}</td>
        <td class="text-right py-1">${fmtN(stats.p90)}</td>
        <td class="text-right py-1 font-bold text-indigo-600">${fmtN(stats.avg)}</td>
      </tr>${gpRow}
    </tbody>
  </table>
  <p class="text-slate-400 mt-1">${fmtN(stats.tx_count)} bills · Range ${fmtN(stats.min)}–${fmtN(stats.max)}${m>0?' · Margin rate: '+m+'%':' · Upload costs for GP estimate'}</p>`;

  // Revenue histogram
  mkChart('chartPnlDeepBillDist', {
    type:'bar',
    data:{ labels:stats.buckets.map(b=>b.label+' '), datasets:[{ label:'Bills', data:stats.buckets.map(b=>b.count), backgroundColor:'#4f46e5', borderRadius:3, borderWidth:0 }] },
    options:{ responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false},datalabels:{display:false},tooltip:{callbacks:{label:ctx=>fmtN(ctx.raw)+' bills'}}},
      scales:{x:{ticks:{color:chartTheme().text,font:{size:9}}},y:{beginAtZero:true,ticks:{color:chartTheme().text}}} },
  });

  // Profit distribution
  const profitNote = document.getElementById('pnlDeepProfitNote');
  if (stats.profit_buckets && stats.profit_buckets.length > 0 && m > 0) {
    if (profitNote) profitNote.textContent = `Avg GP/bill: ${fmtN(stats.avg_profit)} · Margin rate applied: ${m}%`;
    mkChart('chartPnlDeepProfitDist', {
      type:'bar',
      data:{ labels:stats.profit_buckets.map(b=>b.label+' '),
        datasets:[{ label:'Bills', data:stats.profit_buckets.map(b=>b.count),
          backgroundColor: stats.profit_buckets.map((b,i)=>i===0?'rgba(239,68,68,0.7)':'rgba(16,185,129,0.7)'), borderRadius:3, borderWidth:0 }] },
      options:{ responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false},datalabels:{display:false},tooltip:{callbacks:{label:ctx=>fmtN(ctx.raw)+' bills'}}},
        scales:{x:{ticks:{color:chartTheme().text,font:{size:9}}},y:{beginAtZero:true,ticks:{color:chartTheme().text}}} },
    });
  } else if (profitNote) {
    profitNote.textContent = 'Upload SKU costs via Settings → Costs to see GP/bill distribution';
  }
}

function renderPnlDeepMonthTable(monthly) {
  document.getElementById('pnlDeepMonthBody').innerHTML = monthly.map(m => {
    const gp = m.gross_profit || 0;
    const gpColor = gp > 0 ? 'text-emerald-600' : 'text-red-500';
    const momHtml = m.mom_pct != null
      ? `<span class="${m.mom_pct>=0?'text-emerald-500':'text-red-500'} ml-1">(${m.mom_pct>0?'+':''}${m.mom_pct}%)</span>` : '';
    return `<tr class="border-b border-slate-100 hover:bg-slate-50">
      <td class="py-1 pr-2 font-medium">${fmtPeriod(m.period_month)}</td>
      <td class="py-1 pr-2 text-right">${fmtN(m.revenue_ex_vat||0)}</td>
      <td class="py-1 pr-2 text-right text-red-400">${fmtN(m.cogs||0)}</td>
      <td class="py-1 pr-2 text-right ${gpColor} font-semibold">${fmtN(gp)}${momHtml}</td>
      <td class="py-1 pr-2 text-right">${m.margin_pct!=null?m.margin_pct.toFixed(1)+'%':'—'}</td>
      <td class="py-1 pr-2 text-right">${fmtN(m.tx_count||0)}</td>
      <td class="py-1 pr-2 text-right">${fmtN(m.avg_ticket||0)}</td>
      <td class="py-1 text-right text-violet-600">${m.profit_per_bill!=null?fmtN(m.profit_per_bill):'—'}</td>
    </tr>`;
  }).join('');
}

function renderPnlDeepIngredients(ings) {
  document.getElementById('pnlDeepIngBody').innerHTML = ings.map((r,i)=>`
    <tr class="border-b border-slate-50">
      <td class="py-1.5 pr-2 text-slate-400">${i+1}</td>
      <td class="py-1.5 pr-2">${esc(r.name)}</td>
      <td class="py-1.5 pr-2 text-right text-red-500">${fmtN(r.cost)}</td>
      <td class="py-1.5 text-right font-semibold">${(r.pct||0).toFixed(1)}%</td>
    </tr>`).join('') || '<tr><td colspan="4" class="py-3 text-center text-slate-400">—</td></tr>';
}

function renderPnlDeepCategoryMix(cats) {
  document.getElementById('pnlDeepCatBody').innerHTML = cats.map(r=>{
    const m = (r.revenue>0) ? (100*(r.revenue-r.cogs)/r.revenue) : null;
    return `<tr class="border-b border-slate-50">
      <td class="py-1.5 pr-2">${esc((r.category||'').replace(/^Oshinei\s+/i,''))}</td>
      <td class="py-1.5 pr-2 text-right text-slate-500">${fmtN(r.revenue)}</td>
      <td class="py-1.5 pr-2 text-right text-red-500">${fmtN(r.cogs)}</td>
      <td class="py-1.5 text-right font-semibold">${(r.cost_pct||0).toFixed(1)}%</td>
    </tr>`;
  }).join('') || '<tr><td colspan="4" class="py-3 text-center text-slate-400">—</td></tr>';
}

function renderPnlDeepSkus(skus) {
  const note = document.getElementById('pnlDeepSkuNote');
  const totalCogs = skus.reduce((a,s)=>a+(s.cogs||0),0);
  const cumTop = skus.reduce((a,s)=>a+(s.cost_pct||0),0);
  if (note) note.textContent =
    `${skus.length} เมนูที่ขับต้นทุนสูงสุด (BoM) · รวม ${cumTop.toFixed(0)}% ของต้นทุนทั้งสาขา · เรียงตามต้นทุน`;
  document.getElementById('pnlDeepSkuBody').innerHTML = skus.map((s, i) => {
    const hasGp = s.gp != null;
    const gpColor = hasGp ? (s.gp >= 0 ? 'text-emerald-600' : 'text-red-500') : 'text-slate-300';
    const rowBg = hasGp && s.gp < 0 ? 'bg-red-50' : '';
    const pct = s.cost_pct || 0;
    // mini bar for cost share
    const bar = `<div style="display:inline-block;width:40px;height:6px;background:#fee2e2;border-radius:3px;vertical-align:middle;margin-right:4px"><div style="width:${Math.min(100,pct*2)}%;height:100%;background:#ef4444;border-radius:3px"></div></div>`;
    return `<tr class="border-b border-slate-100 hover:bg-slate-50 ${rowBg}">
      <td class="py-1.5 pr-2 text-slate-400">${i+1}</td>
      <td class="py-1.5 pr-2 font-mono text-slate-600">${s.sku_code}</td>
      <td class="py-1.5 pr-2 font-medium">${esc(s.description)}</td>
      <td class="py-1.5 pr-2 text-slate-500">${s.category}</td>
      <td class="py-1.5 pr-2 text-right">${fmtN(s.qty||0)}</td>
      <td class="py-1.5 pr-2 text-right">${fmtN(s.revenue_ex_vat||0)}</td>
      <td class="py-1.5 pr-2 text-right text-red-500 font-medium">${fmtN(s.cogs||0)}</td>
      <td class="py-1.5 pr-2 text-right whitespace-nowrap">${bar}<span class="font-semibold">${pct.toFixed(1)}%</span></td>
      <td class="py-1.5 pr-2 text-right font-bold ${gpColor}">${hasGp?fmtN(s.gp):'—'}</td>
      <td class="py-1.5 text-right">${s.margin_pct!=null?s.margin_pct.toFixed(1)+'%':'—'}</td>
    </tr>`;
  }).join('');
}

async function loadCostAnalysis() {
  const params = new URLSearchParams();
  if (getBranch())    params.set('branch',     getBranch());
  if (getMonthFrom()) params.set('month_from', getMonthFrom());
  if (getMonthTo())   params.set('month_to',   getMonthTo());
  costData = await fetch(`${API}/api/cost/analysis?${params}`).then(r => r.json());

  // Populate category filter for รายละเอียดเมนู
  const cats = [...new Set(costData.items.map(r => r.category))].sort();
  const catSel = document.getElementById('costItemCat');
  catSel.innerHTML = '<option value="">ทุกหมวด</option>';
  cats.forEach(c => { const o = document.createElement('option'); o.value=c; o.textContent=c; catSel.appendChild(o); });

  if (activeCostTab === 'overview')    renderCostOverview();
  if (activeCostTab === 'detail')      renderCostDetail();
  if (activeCostTab === 'suggestions') renderSuggestions();
  loadFoodCostTrend();
  renderCphCompare();
}

// Branch cost/head comparison — reuses the enriched cost-per-head endpoint.
// Uses the selected end month (or the last COMPLETE month, to avoid a 3-day
// partial month) so cost/head is a fair full-month figure.
async function renderCphCompare() {
  let month = getMonthTo() || getMonthFrom() || '';
  if (!month) {
    try { const w = await fetch(`${API}/api/meta/data-window`).then(r=>r.json()); month = w.last_complete_month || w.max_month || ''; }
    catch (e) {}
  }
  const p = new URLSearchParams(); p.set('gran', 'month');
  if (month) p.set('date', month + '-15');
  if (getBranch()) p.set('branch', getBranch());
  if (getGroup()) p.set('group', getGroup());
  let d; try { d = await fetch(`${API}/api/sales/cost-per-head?${p}`).then(r=>r.json()); } catch (e) { return; }
  const branches = (d.branches || []).filter(b => b.cost_per_head != null).sort((a,b)=>b.cost_per_head - a.cost_per_head);
  const avg = (d.total || {}).cost_per_head;
  const mLabel = (d.cur_range && d.cur_range[0]) ? (typeof fmtMonth==='function'?fmtMonth((d.cur_range[0]||'').slice(0,7)):(d.cur_range[0]||'').slice(0,7)) : (month||'');
  const mEl = document.getElementById('cphCompareMonth'); if (mEl) mEl.textContent = `เดือน ${mLabel}${avg!=null?` · เฉลี่ยเครือ ${fmt(avg)}/หัว`:''}`;
  const ins = document.getElementById('cphCompareInsight');
  if (ins && branches.length >= 2 && avg != null) {
    const hi = branches[0], lo = branches[branches.length-1];
    ins.innerHTML = `<div class="text-xs flex flex-wrap gap-x-6 gap-y-1 p-2 rounded-lg" style="background:var(--bg-subtle)">
      <span>🔴 สูงสุด <b>${esc(hi.branch)}</b> ${fmt(hi.cost_per_head)}/หัว (ต้นทุน ${hi.cost_pct}% · รายได้/หัว ${fmt(hi.rev_per_head)})</span>
      <span>🟢 ต่ำสุด <b>${esc(lo.branch)}</b> ${fmt(lo.cost_per_head)}/หัว (ต้นทุน ${lo.cost_pct}%)</span>
      <span style="color:var(--text-muted)">ช่วงห่าง ${fmt(hi.cost_per_head - lo.cost_per_head)}/หัว</span></div>`;
  } else if (ins) { ins.innerHTML = ''; }
  if (!branches.length) { if (chartInstances['chartCphCompare']) chartInstances['chartCphCompare'].destroy(); return; }
  mkChart('chartCphCompare', {
    type: 'bar',
    data: {
      labels: branches.map(b => b.branch),
      datasets: [{
        label: 'ต้นทุน/หัว (BoM)',
        data: branches.map(b => b.cost_per_head),
        backgroundColor: branches.map(b => (avg != null && b.cost_per_head > avg) ? '#ef4444' : '#10b981'),
        borderRadius: 4,
      }]
    },
    options: {
      indexAxis: 'y', responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false }, datalabels: { display: false },
        tooltip: { callbacks: { label: ctx => {
          const b = branches[ctx.dataIndex];
          return ` ต้นทุน/หัว ${fmt(b.cost_per_head)} · ต้นทุน ${b.cost_pct}% · รายได้/หัว ${fmt(b.rev_per_head)} · GP/หัว ${fmt(b.gp_per_head)}`;
        } } }
      },
      scales: {
        x: { ticks: { callback: v => fmt(v) }, title: { display: true, text: avg!=null?`เฉลี่ยเครือ ${fmt(avg)}/หัว`:'' } },
        y: { ticks: { font: { size: 10 }, autoSkip: false } }
      }
    }
  });
}

async function loadFoodCostTrend() {
  const threshold = document.getElementById('foodCostThreshold')?.value || 35;
  const params = new URLSearchParams({ alert_threshold: threshold });
  if (getBranch())    params.set('branch', getBranch());
  if (getGroup())     params.set('group',  getGroup());
  const d = await fetch(`${API}/api/analysis/food_cost_trend?${params}`).then(r => r.json()).catch(() => null);
  if (!d || !d.months || !d.months.length) return;

  // Alerts
  const alertEl = document.getElementById('foodCostAlerts');
  if (alertEl) {
    alertEl.innerHTML = (d.alerts || []).map(a =>
      `<div class="text-xs px-3 py-1.5 rounded-lg font-medium" style="background:#fef3c7;color:#92400e">${a.message}</div>`
    ).join('') || '';
  }

  // Build comparison chart: revenue vs CoGS vs servings, with cost % line
  // 3 axes: y (currency for rev/cost) · y1 (% for cost ratio) · y2 (servings count)
  const overall = d.overall;
  mkChart('chartFoodCostTrend', {
    data: { labels: d.months, datasets: [
      { type:'bar',  label:'รายได้ (ex-VAT)',  data: overall.map(o => o.revenue),  backgroundColor:'rgba(79,70,229,0.55)',  borderRadius:3, order:3, yAxisID:'y'  },
      { type:'bar',  label:'CoGS (BoM)',        data: overall.map(o => o.cost),     backgroundColor:'rgba(220,38,38,0.7)',   borderRadius:3, order:3, yAxisID:'y'  },
      { type:'line', label:'จำนวนเสิร์ฟ',       data: overall.map(o => o.servings), borderColor:'#0891b2', backgroundColor:'transparent', borderWidth:2, pointRadius:3, tension:0.3, order:1, yAxisID:'y2' },
      { type:'line', label:'% Food Cost',       data: overall.map(o => o.cost_pct), borderColor:'#f59e0b', backgroundColor:'rgba(245,158,11,0.10)', borderWidth:2, borderDash:[4,3], pointRadius:3, tension:0.25, fill:true, order:0, yAxisID:'y1' },
      { type:'line', label:`Threshold (${threshold}%)`, data: d.months.map(() => parseFloat(threshold)), borderColor:'#ef4444', borderWidth:1, borderDash:[6,3], pointRadius:0, fill:false, yAxisID:'y1' },
    ] },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { position:'bottom', labels: { font: { size: 10 }, boxWidth: 14 } },
        datalabels: { display: false },
        tooltip: { mode:'index', intersect:false, callbacks: {
          afterBody: (ctxs) => {
            const idx = ctxs[0]?.dataIndex; if (idx == null) return '';
            const o = overall[idx]; if (!o) return '';
            const rps = o.rev_per_serving, cps = o.cost_per_serving;
            const lines = [];
            if (rps != null) lines.push(`รายได้/เสิร์ฟ: ${fmtN(rps)}`);
            if (cps != null) lines.push(`ต้นทุน/เสิร์ฟ: ${fmtN(cps)}`);
            return lines;
          }
        } },
      },
      scales: {
        x:  { ticks: { font: { size: 9 } } },
        y:  { position:'left',  ticks: { font: { size: 9 }, callback: v => fmt(v) }, title: { display: true, text: 'รายได้ / ต้นทุน (บาท)', font: { size: 9 } } },
        y1: { position:'right', ticks: { font: { size: 9 }, callback: v => v + '%' }, grid: { display: false }, min: 0, suggestedMax: Math.max(60, parseFloat(threshold) + 10) },
        y2: { display: false, beginAtZero: true },
      }
    }
  });

  // Insight strip below the chart — latest period focus
  const last = overall[overall.length - 1];
  const prev = overall[overall.length - 2];
  const insightEl = document.getElementById('foodCostInsight');
  if (insightEl && last) {
    const dPct  = (prev && last.cost_pct != null && prev.cost_pct != null) ? (last.cost_pct - prev.cost_pct) : null;
    const trendIcon = dPct == null ? '➡️' : dPct > 0 ? '▲' : '▼';
    const trendColor = dPct == null ? '#64748b' : dPct > 0 ? '#ef4444' : '#10b981';
    insightEl.innerHTML = `
      <div class="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs">
        <div class="rounded-lg border border-indigo-100 bg-indigo-50/50 px-3 py-2">
          <p class="text-[10px] text-indigo-600 font-semibold">รายได้ ${d.months[d.months.length-1]}</p>
          <p class="text-base font-bold text-indigo-700">${fmt(last.revenue)}</p>
        </div>
        <div class="rounded-lg border border-red-100 bg-red-50/50 px-3 py-2">
          <p class="text-[10px] text-red-600 font-semibold">CoGS (BoM)</p>
          <p class="text-base font-bold text-red-700">${fmt(last.cost)}</p>
        </div>
        <div class="rounded-lg border border-cyan-100 bg-cyan-50/50 px-3 py-2">
          <p class="text-[10px] text-cyan-600 font-semibold">จำนวนเสิร์ฟ</p>
          <p class="text-base font-bold text-cyan-700">${fmtN(last.servings)}</p>
          <p class="text-[10px] text-slate-500">รายได้/เสิร์ฟ ${fmtN(last.rev_per_serving || 0)}</p>
        </div>
        <div class="rounded-lg border px-3 py-2" style="background:${(last.cost_pct||0)>parseFloat(threshold)?'#fef2f2':'#f0fdf4'};border-color:${(last.cost_pct||0)>parseFloat(threshold)?'#fecaca':'#bbf7d0'}">
          <p class="text-[10px] font-semibold" style="color:${(last.cost_pct||0)>parseFloat(threshold)?'#dc2626':'#16a34a'}">% Food Cost</p>
          <p class="text-base font-bold" style="color:${(last.cost_pct||0)>parseFloat(threshold)?'#dc2626':'#16a34a'}">${last.cost_pct != null ? last.cost_pct.toFixed(1)+'%' : '—'}</p>
          ${dPct != null ? `<p class="text-[10px]" style="color:${trendColor}">${trendIcon} ${Math.abs(dPct).toFixed(1)}pp เทียบเดือนก่อน</p>` : ''}
        </div>
      </div>`;
  }
}


// ── Overview ──────────────────────────────────────────────────

function renderCostOverview() {
  if (!costData) return;
  const s = costData.summary;
  const items = costData.items;
  const hasCosts = s.costed_skus > 0;

  // ── KPI cards ──
  const marginColor = s.overall_margin_pct == null ? '#94a3b8'
    : s.overall_margin_pct >= 60 ? '#10b981'
    : s.overall_margin_pct >= 40 ? '#f59e0b' : '#ef4444';

  document.getElementById('costKpis').innerHTML = [
    { label:'รายได้รวม',  value:fmt(s.total_revenue),      sub: fmtN(s.total_skus)+' items sold',     color:'#4f46e5' },
    { label:'Total COGS',     value: hasCosts ? fmt(s.total_cogs) : '—',
                               sub: hasCosts ? s.costed_skus+' SKUs costed' : 'no costs entered', color:'#ef4444' },
    { label:'Gross Profit',   value: hasCosts ? fmt(s.total_gross_profit) : '—',
                               sub: hasCosts ? 'Revenue (ex-VAT) minus COGS' : 'requires cost data', color:'#10b981' },
    { label:'Overall Margin', value: s.overall_margin_pct != null ? s.overall_margin_pct.toFixed(1)+'%' : '—',
                               sub: hasCosts ? 'weighted gross margin' : 'requires cost data', color: marginColor },
  ].map(k => `
    <div class="card kpi-card p-4">
      <div class="kpi-card-top"><p class="kpi-label">${k.label}</p></div>
      <p class="kpi-value" style="color:${k.color}">${k.value}</p>
      <div class="kpi-card-bottom"><p class="kpi-sub">${k.sub}</p></div>
    </div>`).join('');

  // ── No-cost banner ──
  const banner = document.getElementById('costNoBanner');
  if (s.uncosted_skus > 0) {
    document.getElementById('costNoBannerText').textContent =
      `${s.uncosted_skus} of ${s.total_skus} menu items have no cost data — margin analysis is incomplete.`;
    banner.classList.remove('hidden');
  } else {
    banner.classList.add('hidden');
  }

  // ── Scatter chart ──
  // Mode A (no costs): Qty vs Revenue — Revenue on Y, Qty on X, colour by category
  // Mode B (costs):    Qty vs Margin% with quadrant colouring
  const QCOLORS = { star:'#10b981', puzzle:'#4f46e5', plowhorse:'#f59e0b', dog:'#ef4444', uncosted:'#94a3b8' };
  let scatterDatasets;

  if (hasCosts) {
    document.getElementById('scatterTitle').textContent    = 'ตารางวิเคราะห์เมนู';
    document.getElementById('scatterMode').textContent     = 'margin vs popularity';
    document.getElementById('scatterMode').className       = 'pill pill-up';
    document.getElementById('scatterSubtitle').textContent = 'X = orders (popularity)  ·  Y = gross margin %  ·  Colour = quadrant';
    const quadGroups = ['star','puzzle','plowhorse','dog','uncosted'];
    const qlabels    = { star:'⭐ Stars', puzzle:'🔮 Puzzles', plowhorse:'🐴 Plowhorses', dog:'🐕 Dogs', uncosted:'⚪ Uncosted' };
    scatterDatasets = quadGroups.map(q => ({
      label: qlabels[q],
      data: items.filter(r => r.quadrant === q && r.margin_pct != null)
                 .map(r => ({ x: r.qty, y: r.margin_pct, label: r.description })),
      backgroundColor: QCOLORS[q] + 'BB',
      borderColor:     QCOLORS[q],
      borderWidth: 1, pointRadius: 5, pointHoverRadius: 8,
    }));
  } else {
    document.getElementById('scatterTitle').textContent    = 'Revenue × Popularity';
    document.getElementById('scatterMode').textContent     = 'no cost data';
    document.getElementById('scatterMode').className       = 'pill pill-warn';
    document.getElementById('scatterSubtitle').textContent = 'X = qty ordered  ·  Y = revenue  ·  Colour = category';
    const cats = [...new Set(items.map(r => r.category))];
    scatterDatasets = cats.map((cat, i) => ({
      label: cat,
      data: items.filter(r => r.category === cat)
                 .map(r => ({ x: r.qty, y: r.revenue, label: r.description })),
      backgroundColor: PALETTE[i % PALETTE.length] + 'AA',
      borderColor:     PALETTE[i % PALETTE.length],
      borderWidth: 1, pointRadius: 4, pointHoverRadius: 7,
    }));
  }

  mkChart('chartMenuScatter', {
    type: 'scatter',
    data: { datasets: scatterDatasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { color:'#64748b', font:{size:10}, boxWidth:10, padding:8 } },
        datalabels: { display: false },
        tooltip: { callbacks: { label: ctx => `${ctx.raw.label}: ${hasCosts ? ctx.raw.y?.toFixed(1)+'%' : fmtN(ctx.raw.y)} (${fmtN(ctx.raw.x)} pcs)` } },
      },
      scales: {
        x: { title:{ display:true, text:'Qty Ordered', color:'#94a3b8', font:{size:11} }, grid:{color:'#f1f5f9'}, ticks:{color:'#94a3b8',font:{size:10}} },
        y: { title:{ display:true, text: hasCosts ? 'Margin %' : 'Revenue ', color:'#94a3b8', font:{size:11} },
             grid:{color:'#f1f5f9'}, ticks:{color:'#94a3b8',font:{size:10}, callback: v => hasCosts ? v+'%' : fmt(v)} },
      },
    },
  });

  // ── Category mix donut ──
  const catMap = {};
  items.forEach(r => { catMap[r.category] = (catMap[r.category]||0) + r.revenue; });
  const catEntries = Object.entries(catMap).sort((a,b) => b[1]-a[1]);
  const top8 = catEntries.slice(0, 8);
  const other = catEntries.slice(8).reduce((s,[,v]) => s+v, 0);
  if (other > 0) top8.push(['Other', other]);
  const top8Colors = top8.map(([k]) => colorForCategory(k));
  mkChart('chartCostCatMix', {
    type: 'doughnut',
    data: { labels: top8.map(([k])=>k), datasets:[{ data:top8.map(([,v])=>Math.round(v)), backgroundColor:top8Colors, borderWidth:2, borderColor:chartTheme().bg }] },
    options: { responsive:true, maintainAspectRatio:false, cutout:'65%',
      plugins:{ legend:{display:false}, datalabels:{display:false}, tooltip:{callbacks:{label:ctx=>` ${fmtN(ctx.raw)} (${(ctx.raw/s.total_revenue*100).toFixed(1)}%)`}} } },
  });
  document.getElementById('catMixLegend').innerHTML = top8.map(([k,v],i) =>
    `<div class="flex items-center justify-between text-xs">
      <span class="flex items-center gap-1.5"><span style="background:${top8Colors[i]};width:8px;height:8px;border-radius:2px;display:inline-block"></span><span class="text-slate-600">${k}</span></span>
      <span class="text-slate-400">${(v/s.total_revenue*100).toFixed(1)}%</span>
    </div>`).join('');

  // ── Quadrant panels ──
  if (hasCosts) {
    ['star','puzzle','plowhorse','dog'].forEach(q => {
      const qItems = items.filter(r => r.quadrant === q);
      document.getElementById(q+'Count').textContent = qItems.length;
      document.getElementById(q+'List').innerHTML = qItems.slice(0,5).map(r =>
        `<li class="text-xs text-slate-600 truncate flex justify-between gap-2" title="${esc(r.description)}">
          <span class="truncate">${esc(r.description)}</span>
          <span class="text-slate-400 flex-shrink-0">${r.margin_pct?.toFixed(0)}%</span>
        </li>`).join('') || '<li class="text-xs text-slate-400 italic">None</li>';
    });
  } else {
    // Without costs: show รายได้สูงสุด / Top by Qty / High-Rev Low-Qty / High-Qty Low-Rev
    const byRev = [...items].sort((a,b) => b.revenue-a.revenue);
    const byQty = [...items].sort((a,b) => b.qty-a.qty);
    document.getElementById('starCount').textContent     = 'by revenue';
    document.getElementById('puzzleCount').textContent   = 'by quantity';
    document.getElementById('plowhorseCount').textContent= 'high qty, low rev';
    document.getElementById('dogCount').textContent      = 'low qty, low rev';
    document.getElementById('starList').innerHTML = byRev.slice(0,5).map(r =>
      `<li class="text-xs text-slate-600 truncate flex justify-between gap-2"><span class="truncate">${esc(r.description)}</span><span class="text-slate-400 flex-shrink-0">${fmt(r.revenue)}</span></li>`).join('');
    document.getElementById('puzzleList').innerHTML = byQty.slice(0,5).map(r =>
      `<li class="text-xs text-slate-600 truncate flex justify-between gap-2"><span class="truncate">${esc(r.description)}</span><span class="text-slate-400 flex-shrink-0">${fmtN(r.qty)}</span></li>`).join('');
    // High qty but lower revenue rank (potential underpriced)
    const avgRevPerQty = s.total_revenue / (s.total_qty || 1);
    const underpriced  = [...items].filter(r => r.qty > 0 && r.revenue/r.qty < avgRevPerQty * 0.7)
                                   .sort((a,b) => b.qty-a.qty).slice(0,5);
    document.getElementById('plowhorseList').innerHTML = underpriced.map(r =>
      `<li class="text-xs text-slate-600 truncate flex justify-between gap-2"><span class="truncate">${esc(r.description)}</span><span class="text-slate-400 flex-shrink-0">${fmtN(r.qty)} pcs</span></li>`).join('')
      || '<li class="text-xs text-slate-400 italic">None found</li>';
    const longTail = items.filter(r => r.cum_revenue_pct > 95).slice(0,5);
    document.getElementById('dogList').innerHTML = longTail.map(r =>
      `<li class="text-xs text-slate-600 truncate flex justify-between gap-2"><span class="truncate">${esc(r.description)}</span><span class="text-slate-400 flex-shrink-0">${r.revenue_mix_pct?.toFixed(2)}%</span></li>`).join('')
      || '<li class="text-xs text-slate-400 italic">None</li>';
  }

  // ── Pareto ──
  let p80idx = items.findIndex(r => r.cum_revenue_pct >= 80);
  let p50idx = items.findIndex(r => r.cum_revenue_pct >= 50);
  if (p80idx < 0) p80idx = items.length - 1;
  if (p50idx < 0) p50idx = 0;
  const pct80 = (((p80idx+1)/items.length)*100).toFixed(0);
  const pct50 = (((p50idx+1)/items.length)*100).toFixed(0);
  // Cost concentration analysis (cumulative cost vs cumulative revenue)
  const costedItems = items.filter(r => r.cogs != null && r.cogs > 0)
    .sort((a, b) => (b.cogs || 0) - (a.cogs || 0));
  let cumCost = 0;
  const totalCost = costedItems.reduce((s, r) => s + (r.cogs || 0), 0);
  costedItems.forEach(r => { cumCost += r.cogs; r._cum_cost_pct = totalCost ? (cumCost / totalCost * 100) : 0; });
  let c80idx = costedItems.findIndex(r => r._cum_cost_pct >= 80);
  if (c80idx < 0) c80idx = costedItems.length - 1;
  const cPct80 = costedItems.length ? (((c80idx+1)/costedItems.length)*100).toFixed(0) : '—';

  document.getElementById('paretoContent').innerHTML = `
    <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
      <div class="bg-indigo-50 rounded-xl p-4 text-center">
        <p class="text-2xl font-bold text-indigo-700">${pct50}%</p>
        <p class="text-xs text-slate-500 mt-1">of SKUs = 50% of revenue</p>
      </div>
      <div class="bg-indigo-50 rounded-xl p-4 text-center">
        <p class="text-2xl font-bold text-indigo-700">${pct80}%</p>
        <p class="text-xs text-slate-500 mt-1">of SKUs = 80% of revenue</p>
      </div>
      <div class="bg-red-50 rounded-xl p-4 text-center">
        <p class="text-2xl font-bold text-red-700">${cPct80 !== '—' ? cPct80+'%' : '—'}</p>
        <p class="text-xs text-slate-500 mt-1">of costed SKUs = 80% of total cost</p>
      </div>
      <div class="bg-slate-50 rounded-xl p-4 text-center">
        <p class="text-2xl font-bold text-slate-700">${items.length - p80idx - 1}</p>
        <p class="text-xs text-slate-500 mt-1">items in the long tail (last 20% rev)</p>
      </div>
    </div>
    <!-- Revenue & Cost concentration line chart -->
    <div class="grid grid-cols-1 lg:grid-cols-2 gap-5 mt-4">
      <div>
        <p class="text-xs text-slate-500 font-medium mb-2">Revenue Concentration Curve</p>
        <div style="height:220px"><canvas id="chartParetoRev"></canvas></div>
      </div>
      <div>
        <p class="text-xs text-slate-500 font-medium mb-2">Cost Concentration Curve ${costedItems.length === 0 ? '<span class="text-amber-600 ml-2">(upload SKU costs to view)</span>' : ''}</p>
        <div style="height:220px"><canvas id="chartParetoCost"></canvas></div>
      </div>
    </div>
    <p class="text-xs text-slate-400 mt-4">A steeper curve means a few SKUs drive most of the metric. Use this to identify which items deserve cost-control attention first.</p>
    <div class="flex items-center gap-3 flex-wrap mt-3">
      <span class="text-xs font-medium text-slate-500">Top 80%-revenue SKUs:</span>
      ${items.slice(0, Math.min(p80idx+1, 8)).map((r,i) => `
        <div class="flex items-center gap-1.5 bg-indigo-50 rounded-lg px-2.5 py-1.5">
          <span class="text-xs font-semibold text-indigo-800">#${i+1}</span>
          <span class="text-xs text-slate-700 max-w-32 truncate">${esc(r.description)}</span>
          <span class="text-xs text-indigo-600 font-bold">${r.revenue_mix_pct?.toFixed(1)}%</span>
        </div>`).join('')}
      ${p80idx >= 8 ? `<span class="text-xs text-slate-400">+${p80idx-7} more…</span>` : ''}
    </div>`;

  // Render Pareto charts (after innerHTML so canvas exists)
  setTimeout(() => {
    // Revenue concentration
    const topN = Math.min(40, items.length);
    const revPoints = items.slice(0, topN);
    mkChart('chartParetoRev', {
      type: 'bar',
      data: {
        labels: revPoints.map((r, i) => '#' + (i+1)),
        datasets: [
          { type:'bar',  label:'Revenue %', data: revPoints.map(r => r.revenue_mix_pct || 0), backgroundColor:'rgba(79,70,229,0.7)', order:2 },
          { type:'line', label:'Cumulative %', data: revPoints.map(r => r.cum_revenue_pct || 0), borderColor:'#ef4444', backgroundColor:'transparent', borderWidth:2, pointRadius:0, tension:0.25, yAxisID:'y1', order:1 },
        ],
      },
      options: { responsive:true, maintainAspectRatio:false,
        plugins:{legend:{display:false}, datalabels:{display:false},
          tooltip:{callbacks:{title:(c)=>revPoints[c[0].dataIndex]?.description||'', label:ctx=>ctx.dataset.label+': '+(ctx.raw||0).toFixed(1)+'%'}}},
        scales:{ x:{ticks:{font:{size:9},color:'#94a3b8'}}, y:{ticks:{color:'#94a3b8',callback:v=>v+'%'}}, y1:{position:'right',max:100,min:0,grid:{display:false},ticks:{color:'#ef4444',callback:v=>v+'%'}}}},
    });

    if (costedItems.length) {
      const topC = Math.min(40, costedItems.length);
      const costPoints = costedItems.slice(0, topC);
      mkChart('chartParetoCost', {
        type: 'bar',
        data: {
          labels: costPoints.map((r, i) => '#' + (i+1)),
          datasets: [
            { type:'bar',  label:'Cost ', data: costPoints.map(r => r.cogs || 0), backgroundColor:'rgba(239,68,68,0.7)', order:2 },
            { type:'line', label:'Cumulative %', data: costPoints.map(r => r._cum_cost_pct || 0), borderColor:'#f59e0b', backgroundColor:'transparent', borderWidth:2, pointRadius:0, tension:0.25, yAxisID:'y1', order:1 },
          ],
        },
        options: { responsive:true, maintainAspectRatio:false,
          plugins:{legend:{display:false}, datalabels:{display:false},
            tooltip:{callbacks:{title:(c)=>costPoints[c[0].dataIndex]?.description||'', label:ctx=>ctx.dataset.label+': '+(ctx.dataset.label==='Cost '?fmtN(ctx.raw||0):(ctx.raw||0).toFixed(1)+'%')}}},
          scales:{ x:{ticks:{font:{size:9},color:'#94a3b8'}}, y:{ticks:{color:'#94a3b8',callback:v=>fmtN(v)}}, y1:{position:'right',max:100,min:0,grid:{display:false},ticks:{color:'#f59e0b',callback:v=>v+'%'}}}},
      });
    } else {
      const canvas = document.getElementById('chartParetoCost');
      if (canvas && canvas.getContext) {
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#94a3b8'; ctx.font = '13px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText('Upload SKU costs to see cost concentration', canvas.width/2, canvas.height/2);
      }
    }
  }, 50);

  renderCostAnalysisBar();
  renderAbcAnalysis();
}


let _abcMode = 'cost'; // 'revenue' | 'cost' — default to cost per user request
function setAbcMode(m) { _abcMode = m; renderAbcAnalysis(); }

function renderAbcAnalysis() {
  const el = document.getElementById('abcContent');
  if (!el || !costData) return;
  const items = costData.items;
  if (!items.length) { el.innerHTML = '<p class="text-sm text-slate-400">ไม่มีข้อมูล</p>'; return; }

  const byCost = _abcMode === 'cost';
  // Recompute cumulative pct based on chosen metric (BoM cost OR revenue)
  const sorted = [...items]
    .filter(r => byCost ? (r.cogs != null && r.cogs > 0) : (r.revenue > 0))
    .sort((a, b) => byCost ? (b.cogs - a.cogs) : (b.revenue - a.revenue));

  if (!sorted.length) {
    el.innerHTML = `<p class="text-sm text-amber-600">ยังไม่มีข้อมูล BoM cost — กลับไปใช้โหมดรายได้แทน หรืออัพโหลดต้นทุนใน Settings → Costs</p>`;
    return;
  }

  const total = sorted.reduce((s, r) => s + (byCost ? r.cogs : r.revenue), 0);
  let cum = 0;
  const classified = sorted.map(r => {
    const v = byCost ? r.cogs : r.revenue;
    cum += v;
    const cumPct = total ? (cum / total * 100) : 0;
    return { ...r, _val: v, _cumPct: cumPct,
             abc: cumPct <= 70 ? 'A' : cumPct <= 90 ? 'B' : 'C' };
  });

  const groupA = classified.filter(r => r.abc === 'A');
  const groupB = classified.filter(r => r.abc === 'B');
  const groupC = classified.filter(r => r.abc === 'C');
  const valA = groupA.reduce((s, r) => s + r._val, 0);
  const valB = groupB.reduce((s, r) => s + r._val, 0);
  const valC = groupC.reduce((s, r) => s + r._val, 0);
  const tot  = total || 1;
  const metricLabel = byCost ? 'ต้นทุน BoM' : 'รายได้';
  const valFmt = byCost ? fmt : fmt;

  // Each group's share of TOTAL BoM cost (independent of the ranking metric) —
  // so even in revenue mode you can see how much ingredient cost each class drives.
  const allCogs = (items.reduce((s, r) => s + (r.cogs || 0), 0)) || 1;
  const cogsOf  = grp => grp.reduce((s, r) => s + (r.cogs || 0), 0);
  const TOPN = 15;   // show up to 15 items per class (was 3)

  const card = (cls, color, border, items2, val, pct) => {
    const cogsPct = cogsOf(items2) / allCogs * 100;
    return `
    <div class="card p-4" style="border-top:3px solid ${border}">
      <div class="flex items-center gap-2 mb-2">
        <span class="text-lg font-black" style="color:${border}">Class ${cls}</span>
        <span class="pill text-xs ml-auto" style="background:${color};color:${border}">${items2.length} SKUs · ${((items2.length/classified.length)*100).toFixed(0)}%</span>
      </div>
      <p class="text-xl font-bold" style="color:${border}">${valFmt(val)}</p>
      <p class="text-xs text-slate-400 mt-0.5">${pct.toFixed(1)}% ของ${metricLabel}</p>
      <p class="text-[11px] font-semibold mt-0.5" style="color:${border}">🧾 ${cogsPct.toFixed(1)}% ของต้นทุน BoM รวม</p>
      <div class="mt-2 space-y-0.5 overflow-auto" style="max-height:240px">
        ${items2.slice(0,TOPN).map((r,i)=>`<div class="flex items-baseline justify-between gap-2 text-xs">
          <span class="text-slate-600 truncate" title="${esc(r.description)}">${i+1}. ${esc(r.description)}</span>
          <span class="text-slate-400 flex-shrink-0 tabular-nums">${fmt(byCost ? (r.cogs||0) : (r.revenue||0))}</span>
        </div>`).join('')}
        ${items2.length > TOPN ? `<div class="text-xs text-slate-400 pt-0.5">+${items2.length-TOPN} รายการ</div>` : ''}
      </div>
    </div>`;
  };

  const pA = (valA/tot*100).toFixed(1), pB = (valB/tot*100).toFixed(1), pC = (valC/tot*100).toFixed(1);

  // Mode toggle + insight
  const insight = byCost
    ? `Class A คือกลุ่ม SKU ที่ใช้ <b>ต้นทุนวัตถุดิบ 70% แรก</b> — ต้องโฟกัสด้าน supply chain (เจรจาราคา · safety stock · cycle count บ่อย)
       <br>Class C เป็น long-tail ของต้นทุน — อาจจะคุ้มน้อย ทบทวนว่าเป็น strategic items หรือไม่`
    : `Class A คือกลุ่ม SKU ที่ทำ <b>รายได้ 70% แรก</b> — ต้องโฟกัสด้าน sales (positioning · staff training · stockout prevention)
       <br>Class C เป็น long-tail — พิจารณาลดจำนวนเพื่อเพิ่ม kitchen execution speed`;

  el.innerHTML = `
    <div class="flex items-center gap-3 mb-4 flex-wrap">
      <span class="text-xs font-semibold text-slate-500 uppercase tracking-wide">วิเคราะห์ตาม</span>
      <div class="flex rounded-lg overflow-hidden border border-slate-200 text-xs font-medium">
        <button onclick="setAbcMode('cost')"    class="px-3 py-1.5 transition-colors ${byCost ? 'bg-rose-600 text-white' : 'bg-white text-slate-600 hover:bg-rose-50'}">ต้นทุน BoM</button>
        <button onclick="setAbcMode('revenue')" class="px-3 py-1.5 border-l border-slate-200 transition-colors ${byCost ? 'bg-white text-slate-600 hover:bg-rose-50' : 'bg-rose-600 text-white'}">รายได้</button>
      </div>
      <span class="text-xs text-slate-400">${sorted.length} SKUs ที่มีข้อมูล${byCost ? ' BoM' : 'รายได้'}</span>
    </div>
    <div class="grid grid-cols-3 gap-4 mb-5">
      ${card('A','#d1fae5','#10b981',groupA,valA,valA/tot*100)}
      ${card('B','#fef3c7','#f59e0b',groupB,valB,valB/tot*100)}
      ${card('C','#fee2e2','#ef4444',groupC,valC,valC/tot*100)}
    </div>
    <div class="mb-4">
      <div class="flex items-center gap-2 mb-1.5">
        <span class="text-xs font-semibold text-slate-500">สัดส่วน${metricLabel}</span>
        <span class="text-xs text-slate-400">${classified.length} SKUs</span>
      </div>
      <div class="flex rounded-full overflow-hidden h-5" style="width:100%">
        <div style="width:${pA}%;background:#10b981" class="flex items-center justify-center text-xs text-white font-bold" title="Class A: ${pA}%">${parseFloat(pA)>8?pA+'%':''}</div>
        <div style="width:${pB}%;background:#f59e0b" class="flex items-center justify-center text-xs text-white font-bold" title="Class B: ${pB}%">${parseFloat(pB)>8?pB+'%':''}</div>
        <div style="width:${pC}%;background:#ef4444" class="flex items-center justify-center text-xs text-white font-bold" title="Class C: ${pC}%">${parseFloat(pC)>8?pC+'%':''}</div>
      </div>
      <div class="flex gap-4 mt-1.5">
        <span class="text-xs text-slate-500">A: ${groupA.length} SKUs = ${pA}%</span>
        <span class="text-xs text-slate-500">B: ${groupB.length} SKUs = ${pB}%</span>
        <span class="text-xs text-slate-500">C: ${groupC.length} SKUs = ${pC}%</span>
      </div>
    </div>
    <p class="text-xs text-slate-500 leading-relaxed">📌 <b>ABC Analysis ตาม${metricLabel}</b> — A = 70% แรก · B = 70-90% · C = 90-100%
      <br>${insight}</p>`;
}


function renderCostAnalysisBar() {
  const el = document.getElementById('costAnalysisBar');
  if (!el || !costData) return;
  const items = costData.items;
  const s     = costData.summary;

  // Top 5 by revenue
  const top5 = items.slice(0, 5);
  const p20  = items.findIndex(r => r.cum_revenue_pct >= 80);
  const hasCosts = s.costed_skus > 0;

  const stat = (label, value, color = '#64748b') =>
    `<div>
      <p class="text-xs text-slate-400 mb-0.5">${label}</p>
      <p class="text-sm font-bold" style="color:${color}">${value}</p>
    </div>`;

  const topList = `
    <div>
      <p class="text-xs text-slate-400 mb-1">Top Items</p>
      ${top5.map((r, i) => `
        <div class="flex items-baseline justify-between gap-1 mb-0.5">
          <span class="text-xs text-slate-600 truncate" style="max-width:90px" title="${esc(r.description)}">${i+1}. ${esc(r.description.slice(0,16))}</span>
          <span class="text-xs font-semibold text-indigo-600 flex-shrink-0">${r.revenue_mix_pct?.toFixed(1)}%</span>
        </div>`).join('')}
    </div>`;

  el.innerHTML = [
    stat('Active SKUs',    fmtN(s.total_skus), '#4f46e5'),
    hasCosts ? stat('Avg Margin',    (s.overall_margin_pct?.toFixed(1)||'—')+'%', s.overall_margin_pct>=60?'#10b981':s.overall_margin_pct>=40?'#f59e0b':'#ef4444') : stat('Costed SKUs', '0 / '+s.total_skus, '#f59e0b'),
    p20 >= 0 ? stat('80% Rev in',    (p20+1)+' SKUs', '#0f172a') : '',
    '<hr class="border-slate-100">',
    topList,
  ].join('');
}


// ── รายละเอียดเมนู ──────────────────────────────────────────────

function filterCostDetail() { renderCostDetail(); }

function sortCostDetail(key) {
  if (costSortKey === key) costSortAsc = !costSortAsc;
  else { costSortKey = key; costSortAsc = false; }
  renderCostDetail();
}

function renderCostDetail() {
  if (!costData) return;
  const q  = (document.getElementById('costItemSearch')?.value || '').toLowerCase();
  const cat = document.getElementById('costItemCat')?.value || '';
  const qd  = document.getElementById('costItemQuadrant')?.value || '';

  let rows = costData.items.filter(r =>
    (!q   || r.description.toLowerCase().includes(q) || r.sku_code.toLowerCase().includes(q)) &&
    (!cat || r.category === cat) &&
    (!qd  || r.quadrant === qd)
  );

  rows = [...rows].sort((a, b) => {
    const av = a[costSortKey] ?? -Infinity;
    const bv = b[costSortKey] ?? -Infinity;
    return costSortAsc ? av - bv : bv - av;
  });

  const _leak = costData.summary?.buffet_leak_excluded || 0;
  document.getElementById('costItemCount').textContent =
    `${rows.length.toLocaleString()} items` +
    (_leak ? ` · ตัดเมนูบุฟเฟ่ต์ (ราคา/หน่วย≈0) ${_leak.toLocaleString()} รายการ` : '');

  const QLABELS = { star:'⭐', puzzle:'🔮', plowhorse:'🐴', dog:'🐕', uncosted:'⚪' };
  const QPILLS  = { star:'pill-up', puzzle:'pill-neu', plowhorse:'pill-warn', dog:'pill-down', uncosted:'' };

  document.getElementById('costItemBody').innerHTML = rows.map((r, i) => {
    const priced = _hasMenuPrice(r);              // buffet (B) has no per-dish price → margin undefined
    const mpv = priced ? r.margin_pct : null;
    const mc = mpv == null ? '#94a3b8'
      : mpv >= 60 ? '#10b981'
      : mpv >= 40 ? '#f59e0b' : '#ef4444';
    const mpShow = !priced
      ? '<span class="text-[10px] font-normal" style="color:#b45309" title="บุฟเฟต์ — รวมในแพ็กเกจ ไม่มีราคาขายรายจาน">บุฟเฟต์</span>'
      : (mpv != null ? mpv.toFixed(1)+'%' : '<span class="text-slate-300 font-normal">—</span>');
    return `<tr class="border-t border-slate-100">
      <td class="py-2 pr-2 text-slate-400 text-xs">${i+1}</td>
      <td class="py-2 pr-3 font-mono text-indigo-600 text-xs">${r.sku_code}</td>
      <td class="py-2 pr-3 text-slate-700 max-w-xs truncate font-medium" title="${esc(r.description)}">${esc(r.description)}</td>
      <td class="py-2 pr-3 text-xs text-slate-500">${r.category}</td>
      <td class="py-2 pr-3 text-right">${fmtN(r.qty)}</td>
      <td class="py-2 pr-3 text-right text-slate-400 text-xs">${r.qty_mix_pct?.toFixed(1)}%</td>
      <td class="py-2 pr-3 text-right font-semibold">${fmtN(r.revenue)}</td>
      <td class="py-2 pr-3 text-right text-xs">
        <div class="flex items-center justify-end gap-1">
          <div class="h-1.5 rounded-full bg-indigo-500" style="width:${Math.min(r.revenue_mix_pct*3,60)}px"></div>
          <span class="text-slate-500">${r.revenue_mix_pct?.toFixed(1)}%</span>
        </div>
      </td>
      <td class="py-2 pr-3 text-right text-slate-500">${r.unit_cost != null ? fmtN(r.unit_cost) : '<span class="text-slate-300">—</span>'}</td>
      <td class="py-2 pr-3 text-right font-bold" style="color:${mc}">${mpShow}</td>
      <td class="py-2 text-center">
        ${priced
          ? `<span class="pill ${QPILLS[r.quadrant]||''} text-xs">${QLABELS[r.quadrant]||''} ${r.quadrant !== 'uncosted' ? r.quadrant : '—'}</span>`
          : '<span class="pill text-xs" style="background:#fef3c7;color:#92400e">🍽️ บุฟเฟต์</span>'}
      </td>
    </tr>`;
  }).join('');
}


// ── Suggestions ───────────────────────────────────────────────

function renderSuggestions() {
  if (!costData) return;
  const s     = costData.summary;
  const items = costData.items;
  const hasCosts = s.costed_skus > 0;

  const cards = [];

  // ── 1. Health summary ──
  const healthColor = !hasCosts ? '#f59e0b'
    : s.overall_margin_pct >= 60 ? '#10b981'
    : s.overall_margin_pct >= 40 ? '#f59e0b' : '#ef4444';
  const healthLabel = !hasCosts ? 'ต้องอัพเดทต้นทุน'
    : s.overall_margin_pct >= 60 ? 'กำไรแข็งแรง'
    : s.overall_margin_pct >= 40 ? 'มีโอกาสปรับปรุง' : 'น่าเป็นห่วง';
  cards.push(`
    <div class="card p-5" style="border-left:4px solid ${healthColor}">
      <div class="flex items-center gap-3 mb-3">
        <span class="text-xl">${!hasCosts ? '📋' : s.overall_margin_pct >= 60 ? '✅' : s.overall_margin_pct >= 40 ? '⚠️' : '🚨'}</span>
        <div>
          <h3 class="font-bold text-slate-800">สุขภาพเมนู: ${healthLabel}</h3>
          <p class="text-xs text-slate-400">กำไรขั้นต้นรวม · ${s.total_skus} SKUs · ${s.costed_skus} ตัวที่มีต้นทุน</p>
        </div>
        ${hasCosts ? `<span class="ml-auto pill ${s.overall_margin_pct>=60?'pill-up':s.overall_margin_pct>=40?'pill-warn':'pill-down'} text-base">${s.overall_margin_pct?.toFixed(1)}%</span>` : ''}
      </div>
      <ul class="space-y-1.5 text-sm text-slate-600">
        <li>• เมนูมีทั้งหมด <strong>${s.total_skus} รายการ</strong> ยอดขายรวม <strong>${fmtN(Math.round(s.total_revenue))}</strong>${getMonth()?` ในเดือน ${fmtMonth(getMonth())}`:''}</li>
        ${hasCosts
          ? `<li>• ต้นทุนรวม: <strong>${fmtN(Math.round(s.total_cogs))}</strong> · กำไรขั้นต้น: <strong>${fmtN(Math.round(s.total_gross_profit))}</strong></li>
             <li>• อัตรากำไรขั้นต้น <strong>${s.overall_margin_pct?.toFixed(1)}%</strong> — ค่ามาตรฐานร้านอาหารไทยที่แข็งแรง 60–70%</li>`
          : `<li>• ยังขาดข้อมูลต้นทุน <strong>${s.uncosted_skus} รายการ</strong> — อัพเดทใน Settings เพื่อปลดล็อกการวิเคราะห์เต็มรูปแบบ</li>`}
      </ul>
    </div>`);

  // ── 2. Pareto + buffet concentration ──
  const p20idx = items.findIndex(r => r.cum_revenue_pct >= 80);
  const topPct  = p20idx >= 0 ? (((p20idx+1)/items.length)*100).toFixed(0) : '?';
  const top5Rev = items.slice(0,5).reduce((sum,r)=>sum+r.revenue,0);
  const top5Pct = s.total_revenue ? (top5Rev/s.total_revenue*100).toFixed(1) : '?';
  const buffetItems = items.filter(r => /BUFFET/i.test(r.sku_code || r.category || ''));
  const buffetRev   = buffetItems.reduce((sum,r)=>sum+r.revenue,0);
  const buffetCost  = buffetItems.reduce((sum,r)=>sum+(r.cogs||0),0);
  const buffetPct   = s.total_revenue ? (buffetRev/s.total_revenue*100).toFixed(1) : '0';
  const buffetCostPct = s.total_cogs ? (buffetCost/s.total_cogs*100).toFixed(1) : '0';
  const buffetMargin  = buffetRev > 0 && buffetCost > 0 ? ((buffetRev - buffetCost) / buffetRev * 100).toFixed(1) : null;
  cards.push(`
    <div class="card p-5">
      <div class="flex items-center gap-2 mb-3"><span class="text-xl">🍽️</span><h3 class="font-bold text-slate-800">กระจุกตัวรายได้ + บุฟเฟ่ต์</h3></div>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">
        <div class="rounded-lg p-3 border border-indigo-100" style="background:#eef2ff">
          <p class="text-xs text-indigo-600 font-semibold mb-1">Pareto 80/20</p>
          <p class="text-sm text-slate-700">SKU เพียง <b>${topPct}%</b> ทำรายได้ 80% — ${topPct <= 20 ? 'กระจุกตัวสมเหตุสมผล' : 'กระจายเกินไป (ปกติ ≤20%)'}</p>
          <p class="text-xs text-slate-500 mt-1">Top 5 รวม <b>${top5Pct}%</b> ของยอดทั้งหมด</p>
        </div>
        <div class="rounded-lg p-3 border" style="background:#fff7ed;border-color:#fed7aa">
          <p class="text-xs text-orange-600 font-semibold mb-1">บุฟเฟ่ต์</p>
          <p class="text-sm text-slate-700">บุฟเฟ่ต์คิดเป็น <b>${buffetPct}%</b> ของยอดขาย แต่ <b>${buffetCostPct}%</b> ของต้นทุนรวม</p>
          ${buffetMargin ? `<p class="text-xs text-slate-500 mt-1">อัตรากำไรขั้นต้นของบุฟเฟ่ต์ <b>${buffetMargin}%</b></p>` : ''}
        </div>
      </div>
      <p class="text-xs text-slate-500">💡 หาก buffet > 70% ของยอดขาย → ธุรกิจพึ่งพา volume สูง · เน้นควบคุม BoM และ portion control · พิจารณาเพิ่มเมนู à la carte กำไรสูงเพื่อกระจายความเสี่ยง</p>
    </div>`);

  // ── 3 & 4 — quadrant recommendations (only if costs exist) ──
  if (hasCosts) {
    const stars      = items.filter(r => r.quadrant === 'star');
    const plowhorses = items.filter(r => r.quadrant === 'plowhorse');
    const puzzles    = items.filter(r => r.quadrant === 'puzzle');
    const dogs       = items.filter(r => r.quadrant === 'dog');

    // High-cost SKUs (cost > 50% of price) — actionable for renegotiation.
    // Exclude buffet (B) items: they have NO à-la-carte price (revenue ≈ 0), so
    // cogs/revenue explodes to meaningless % (e.g. -29,709,896%). Per-dish margin
    // is only defined for à-la-carte items. Also cap the ratio at a sane 3× as a
    // backstop against price-as-cost data errors. See _hasMenuPrice().
    const highCostItems = items.filter(r => r.unit_cost != null && _hasMenuPrice(r)
                                  && r.cogs/r.revenue_ex_vat > 0.5 && r.cogs/r.revenue_ex_vat <= 3)
                               .sort((a,b)=>b.cogs-a.cogs).slice(0,8);
    if (highCostItems.length) {
      const topCostBurden = highCostItems.slice(0,3).reduce((s,r)=>s+r.cogs,0);
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #dc2626;background:#fef2f2">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">💰</span><h3 class="font-bold text-red-800">SKU ต้นทุนสูง — เป้าหมายลด BoM (${highCostItems.length} รายการ)</h3></div>
          <p class="text-sm text-slate-700 mb-3">รายการที่มีต้นทุน <b>เกิน 50%</b> ของยอดขาย ex-VAT แสดงว่า margin ต่ำ พร้อมถูกปรับ:</p>
          <div class="space-y-1 text-xs mb-3">
            ${highCostItems.map(r => `
              <div class="flex items-center justify-between bg-white rounded px-2 py-1 border border-red-100">
                <span class="truncate flex-1">${esc(r.description)}</span>
                <span class="text-slate-500 mx-2">ต้นทุน ${fmt(r.cogs)} (${(r.cogs/r.revenue_ex_vat*100).toFixed(0)}%)</span>
                <span class="font-bold text-red-600">${r.margin_pct?.toFixed(0)}%</span>
              </div>
            `).join('')}
          </div>
          <p class="text-xs text-slate-600 bg-white rounded p-2 border border-red-200">
            💡 <b>แนวทาง:</b> Top 3 รายการสูงสุดมีต้นทุนรวม <b>${fmt(topCostBurden)}</b> — ลดได้ 10% = ประหยัด <b>${fmt(topCostBurden * 0.1)}</b>/เดือน
            <br>• <b>เจรจาซัพพลายเออร์</b> สำหรับวัตถุดิบที่ใช้บ่อย (ปริมาณมากต่อรองได้มากกว่า)
            <br>• <b>ลด portion size 5-10%</b> ในรายการที่ลูกค้ามักทานเหลือ (ดูจาก feedback)
            <br>• <b>ปรับสูตรหลัก</b> สลับวัตถุดิบราคาแพงด้วยทางเลือกราคาดีคุณภาพใกล้เคียง
          </p>
        </div>`);
    }

    if (stars.length) {
      const starsRev = stars.reduce((sum,r)=>sum+r.revenue,0);
      const starsPct = s.total_revenue ? (starsRev/s.total_revenue*100).toFixed(1) : 0;
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #10b981">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">⭐</span><h3 class="font-bold text-emerald-800">⭐ ดาวเด่น Stars (${stars.length} รายการ · ${starsPct}% ของรายได้)</h3></div>
          <p class="text-sm text-slate-600 mb-3">เป็นทั้ง <b>ขายดี + กำไรสูง</b> — เป็นเครื่องจักรทำเงินของร้าน ต้องดูแลพิเศษ</p>
          <ul class="space-y-1 text-sm text-slate-600 mb-3">
            <li>• <b>การันตี supply chain</b> — สต็อกขาดสาขาเสียหายมากที่สุด ตั้ง safety stock 1.5 เท่า</li>
            <li>• <b>วางใน menu position ที่ดี</b> เช่น มุมขวาบน (golden corner) หรือมีรูปประกอบ</li>
            <li>• <b>ทดลองขึ้นราคา 5–10%</b> ลูกค้าที่รักเมนูนี้ ไม่ค่อย sensitive ต่อราคา</li>
            <li>• ใช้เป็น <b>menu engineering anchor</b> — เปรียบเทียบราคากับเมนูอื่นเพื่อทำให้ดูคุ้ม</li>
          </ul>
          <div class="flex flex-wrap gap-1">${stars.slice(0,10).map(r=>`<span class="pill pill-up">${esc(r.description.slice(0,20))} · ${r.margin_pct?.toFixed(0)}%</span>`).join('')}</div>
        </div>`);
    }

    if (plowhorses.length) {
      const avgMar = plowhorses.reduce((sum,r)=>sum+r.margin_pct,0)/plowhorses.length;
      const phRev = plowhorses.reduce((sum,r)=>sum+r.revenue,0);
      // Estimate the gain from a 5% price increase (assume 90% retention)
      const priceUpGain = phRev * 0.05 * 0.9;
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #f59e0b">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">🐴</span><h3 class="font-bold text-amber-800">🐴 ม้างาน Plowhorses (${plowhorses.length} รายการ · กำไรเฉลี่ย ${avgMar.toFixed(1)}%)</h3></div>
          <p class="text-sm text-slate-600 mb-3">ขายดีแต่กำไรต่ำ — ลูกค้ารัก แต่เราเสียโอกาส re-engineer เพื่อทำกำไรเพิ่ม</p>
          <ul class="space-y-1 text-sm text-slate-600 mb-3">
            <li>• <b>ตรวจต้นทุนวัตถุดิบรายตัว</b> — ประหยัด 1 บาท × volume สูง = ผลกระทบใหญ่</li>
            <li>• <b>ขึ้นราคา 5–10%</b> ทดลอง → คาดประหยัดต้นทุน + เพิ่มรายได้ <b>~${fmt(priceUpGain)}</b>/เดือน (สมมุติ retention 90%)</li>
            <li>• <b>ปรับสูตร/portion</b> เช่น ลดเนื้อจาก 200g เป็น 180g → ประหยัดต้นทุน 10% โดยไม่กระทบ perception</li>
            <li>• <b>Bundle กับ add-on margin สูง</b> (เครื่องดื่ม side dish) — ลูกค้าจ่ายเพิ่มเล็กน้อย margin รวมพุ่ง</li>
            <li>• ระวัง <b>plowhorse → dog spiral</b> ถ้าวัตถุดิบขึ้นราคา 20% แต่เราไม่ขึ้นตาม</li>
          </ul>
          <div class="flex flex-wrap gap-1">${plowhorses.slice(0,10).map(r=>`<span class="pill pill-warn">${esc(r.description.slice(0,20))} · ${r.margin_pct?.toFixed(0)}%</span>`).join('')}</div>
        </div>`);
    }

    if (puzzles.length) {
      const avgRev = puzzles.reduce((sum,r)=>sum+r.revenue_mix_pct,0)/puzzles.length;
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #4f46e5">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">🔮</span><h3 class="font-bold text-indigo-800">🔮 ปริศนา Puzzles (${puzzles.length} รายการ · revenue mix เฉลี่ย ${avgRev.toFixed(2)}%)</h3></div>
          <p class="text-sm text-slate-600 mb-3">กำไรดีแต่ขายน้อย — เพชรในตม ที่ลูกค้ายังไม่เห็น เป้าหมายคือเพิ่มยอดขาย</p>
          <ul class="space-y-1 text-sm text-slate-600 mb-3">
            <li>• <b>Training พนักงาน upselling</b> — front-of-house แนะนำได้ ยอดขายขยับเร็ว 30-50%</li>
            <li>• <b>"Chef's Special" หรือ "เมนูแนะนำ"</b> หมุนเวียนเด่นในเมนู ทำให้ดูพิเศษ</li>
            <li>• <b>Bundle กับ Plowhorse</b> เป็น combo set — ดึง volume จาก Plowhorse มาช่วย</li>
            <li>• <b>Reposition ในเมนู</b> ใส่รูปประกอบ + label "ขายดี" หรือ "ลูกค้าโปรด"</li>
            <li>• <b>โปรโมชั่นทดลอง</b> ลดราคา 10% ในสัปดาห์แรก เพื่อให้ลูกค้ารู้จัก</li>
          </ul>
          <div class="flex flex-wrap gap-1">${puzzles.slice(0,10).map(r=>`<span class="pill pill-neu">${esc(r.description.slice(0,20))} · ${r.margin_pct?.toFixed(0)}%</span>`).join('')}</div>
        </div>`);
    }

    if (dogs.length) {
      const dogsRev = dogs.reduce((sum,r)=>sum+r.revenue,0);
      const dogsPct = s.total_revenue ? (dogsRev/s.total_revenue*100).toFixed(1) : 0;
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #ef4444">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">🐕</span><h3 class="font-bold text-red-700">🐕 ตัวถ่วง Dogs (${dogs.length} รายการ · ${dogsPct}% ของรายได้)</h3></div>
          <p class="text-sm text-slate-600 mb-3">ขายน้อย <em>และ</em> กำไรต่ำ — เปลืองพื้นที่เมนู เปลือง training พนักงาน เปลืองสต็อก</p>
          <ul class="space-y-1 text-sm text-slate-600 mb-3">
            <li>• <b>ตัดออกจากเมนูเลย</b> — สั้นกระชับดีกว่า ลูกค้าตัดสินใจเร็วขึ้น</li>
            <li>• ถ้าเป็น <b>strategic items</b> (vegan/allergen-free) → ปรับสูตรลดต้นทุน</li>
            <li>• ถ้ามีกลุ่มลูกค้าเฉพาะที่สั่ง → ประเมินผลกระทบรายได้ก่อนตัด</li>
            <li>• <b>Industry rule of thumb:</b> เมนู 50–80 รายการทำงานดีกว่าเมนูใหญ่ ทั้งใน kitchen execution + customer decision speed</li>
            <li>• สาขาที่มีปัญหาเรื่อง kitchen capacity ควรเริ่มจากตัด Dogs ก่อน</li>
          </ul>
          <div class="flex flex-wrap gap-1">${dogs.slice(0,10).map(r=>`<span class="pill pill-down">${esc(r.description.slice(0,20))} · ${r.margin_pct?.toFixed(0)}%</span>`).join('')}</div>
        </div>`);
    }
  } else {
    // Without costs — volume-based insights
    const avgRevPerQty = s.total_revenue / (s.total_qty || 1);
    const potentiallyUnderpriced = items.filter(r => r.qty > 0 && r.revenue/r.qty < avgRevPerQty * 0.65).sort((a,b)=>b.qty-a.qty);
    if (potentiallyUnderpriced.length) {
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #f59e0b">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">💡</span><h3 class="font-bold text-amber-800">Potential Pricing Opportunity (${potentiallyUnderpriced.length} items)</h3></div>
          <p class="text-sm text-slate-600 mb-3">These items are ordered frequently but generate below-average revenue per portion — they may be underpriced relative to their popularity.</p>
          <div class="flex flex-wrap gap-2 mb-3">${potentiallyUnderpriced.slice(0,8).map(r=>`<span class="pill pill-warn">${esc(r.description.slice(0,22))} · ${fmtN(Math.round(r.revenue/r.qty))}/pc</span>`).join('')}</div>
          <p class="text-xs text-slate-400">Enter unit costs in Settings to confirm whether these items also have low margins.</p>
        </div>`);
    }

    // Long tail suggestion
    const longTailCount = items.filter(r => r.cum_revenue_pct > 90).length;
    if (longTailCount > 20) {
      cards.push(`
        <div class="card p-5" style="border-left:4px solid #94a3b8">
          <div class="flex items-center gap-2 mb-3"><span class="text-xl">✂️</span><h3 class="font-bold text-slate-700">Menu Simplification Opportunity</h3></div>
          <p class="text-sm text-slate-600 mb-2"><strong>${longTailCount} items</strong> (${(longTailCount/items.length*100).toFixed(0)}% of your menu) together contribute only 10% of revenue. A focused menu improves kitchen speed, reduces waste, and sharpens your brand.</p>
          <ul class="space-y-1 text-sm text-slate-600">
            <li>• Industry research shows menus with 50–80 items outperform larger menus on execution quality</li>
            <li>• You currently have <strong>${items.length} active SKUs</strong></li>
            <li>• Enter costs to identify which of these are also low-margin before deciding on removal</li>
          </ul>
        </div>`);
    }
  }

  // ── Buffet-specific deep dive (always shown if buffet category exists) ──
  if (buffetItems.length && hasCosts) {
    const sorted = [...buffetItems].sort((a,b) => (b.revenue || 0) - (a.revenue || 0));
    const topTier = sorted[0];
    const buffetGP = buffetItems.reduce((sum,r)=>sum+(r.gross_profit||0),0);
    const buffetGPPct = buffetRev > 0 ? (buffetGP/buffetRev*100).toFixed(1) : '0';
    // Find pricing imbalance: highest tier doesn't have highest margin?
    const highest_price = sorted.reduce((mx, r) => (r.revenue/r.qty > mx.revenue/mx.qty) ? r : mx, sorted[0]);
    const highest_margin = sorted.reduce((mx, r) => (r.margin_pct || 0) > (mx.margin_pct || 0) ? r : mx, sorted[0]);
    cards.push(`
      <div class="card p-5" style="border-left:4px solid #ec4899;background:linear-gradient(to right, #fdf2f8, #ffffff)">
        <div class="flex items-center gap-2 mb-3"><span class="text-xl">🥘</span><h3 class="font-bold text-pink-800">เจาะลึกบุฟเฟ่ต์ — Core Business Analysis</h3></div>
        <p class="text-sm text-slate-700 mb-3">บุฟเฟ่ต์เป็น <b>${buffetPct}%</b> ของยอดขาย แต่ใช้ <b>${buffetCostPct}%</b> ของต้นทุนรวม — อัตรากำไรขั้นต้น <b>${buffetGPPct}%</b></p>
        <div class="space-y-2 text-sm">
          <div class="bg-white rounded-lg p-3 border border-pink-100">
            <p class="font-semibold text-pink-700 mb-1">🎯 Tier ทำเงินสูงสุด</p>
            <p class="text-slate-700">${topTier.description} — ยอดขาย <b>${fmt(topTier.revenue)}</b> (${topTier.qty.toLocaleString()} pax) · margin <b>${topTier.margin_pct?.toFixed(1)}%</b></p>
          </div>
          ${highest_price.sku_code !== highest_margin.sku_code ? `
          <div class="bg-amber-50 rounded-lg p-3 border border-amber-200">
            <p class="font-semibold text-amber-800 mb-1">⚠️ Pricing imbalance</p>
            <p class="text-xs text-slate-700">Tier ราคาสูงสุด (<b>${highest_price.description}</b>) ทำกำไร <b>${highest_price.margin_pct?.toFixed(1)}%</b><br>
            แต่ Tier กำไรสูงสุดจริงคือ <b>${highest_margin.description}</b> ที่ <b>${highest_margin.margin_pct?.toFixed(1)}%</b><br>
            → พิจารณาขึ้นราคา Tier บน หรือ ลดต้นทุนวัตถุดิบ premium</p>
          </div>` : ''}
          <div class="bg-rose-50 rounded-lg p-3 border border-rose-200">
            <p class="font-semibold text-rose-800 mb-1">💡 Action items บุฟเฟ่ต์</p>
            <ul class="text-xs text-slate-700 space-y-1">
              <li>• <b>BoM Tracking</b> — บันทึกต้นทุนวัตถุดิบบุฟเฟ่ต์รายเดือน (เนื้อแซลมอน เนื้อวากิว ของหวาน) → ตอบโจทย์ว่า margin ตกหรือไม่</li>
              <li>• <b>Portion Control</b> — บุฟเฟ่ต์ที่ "all-you-can-eat" ต้องมีระบบ <b>ค่าปรับเหลือ</b> (มี SKU OT0012/0013/0016 อยู่แล้ว) เก็บอย่างเข้มงวด</li>
              <li>• <b>Daypart Pricing</b> — ลด tier ราคาตอน lunch (350) เพื่อดึงคน เพิ่ม tier ราคาตอน dinner (590/799) เพื่อเพิ่ม margin</li>
              <li>• <b>Premium Add-on</b> — ขาย add-on margin สูง เช่น แซลมอนพรีเมียม เครื่องดื่ม alcohol → ลูกค้าบุฟเฟ่ต์ตัดสินใจง่ายเพราะอารมณ์ "เปย์มาแล้ว"</li>
              <li>• <b>Buffet Mix Optimization</b> — Tier 590 เป็น sweet spot (78% volume) — ปรับ menu mix ในนี้เพื่อ <b>ลด BoM 5% = +${fmt(buffetCost * 0.05)}/เดือน</b></li>
            </ul>
          </div>
        </div>
      </div>`);
  }

  // ── Final: missing cost data CTA ──
  if (s.uncosted_skus > 0) {
    const coverageRev = costData.items.filter(r=>r.unit_cost!=null).reduce((a,r)=>a+r.revenue,0);
    const coveragePct = s.total_revenue ? (coverageRev/s.total_revenue*100).toFixed(1) : 0;
    cards.push(`
      <div class="card p-5" style="border-left:4px solid #06b6d4">
        <div class="flex items-center gap-2 mb-3"><span class="text-xl">📝</span><h3 class="font-bold text-cyan-800">เติมข้อมูลต้นทุนให้ครบ</h3></div>
        <p class="text-sm text-slate-600 mb-3">ยังขาดต้นทุน <strong>${s.uncosted_skus} SKUs</strong> · ครอบคลุมรายได้ปัจจุบัน <strong>${coveragePct}%</strong> · เติมให้ครบเพื่อปลดล็อก menu engineering เต็มรูปแบบ</p>
        <button onclick="switchTab('settings');switchSettingsTab('costs')"
          class="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-medium rounded-lg transition-colors">
          เปิดหน้าจัดการต้นทุน →
        </button>
      </div>`);
  }

  document.getElementById('suggestionsContent').innerHTML = cards.join('');
}


